        /* =================================================================
         * ADMIN ANALYTICS — search-query reporting (#719 PR 2d)
         *
         * Mirrors the Top search queries / Zero-result panels on
         * /manage/analytics. The other two analytics verbs
         * (`top_songs` / `top_books`) are already covered by the
         * existing `popular_songs` endpoint; this fills the search-side
         * gap.
         * ================================================================= */

        /* -----------------------------------------------------------------
         * Admin: top + zero-result search queries
         * GET ?action=admin_analytics_searches&range=7|30|90&limit=15
         * Default range = 30 days, limit = 15.
         * ----------------------------------------------------------------- */
        case 'admin_analytics_searches': {
            $authUser = getAuthenticatedUser();
            if (!$authUser || !in_array($authUser['Role'], ['admin', 'global_admin'])) {
                sendJson(['error' => 'Admin access required.'], 403);
                break;
            }

            $range = (int)($_GET['range'] ?? 30);
            if (!in_array($range, [7, 30, 90], true)) { $range = 30; }
            $limit = (int)($_GET['limit'] ?? 15);
            if ($limit < 1 || $limit > 100)           { $limit = 15; }
            $since = (new DateTime("-{$range} days"))->format('Y-m-d H:i:s');

            $top  = [];
            $zero = [];
            try {
                $db = getDbMysqli();

                $stmt = $db->prepare(
                    'SELECT Query AS query, COUNT(*) AS hits, MAX(ResultCount) AS top_count
                       FROM tblSearchQueries
                      WHERE SearchedAt >= ? AND Query <> ""
                      GROUP BY Query
                      ORDER BY hits DESC
                      LIMIT ?'
                );
                $stmt->bind_param('si', $since, $limit);
                $stmt->execute();
                $top = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
                $stmt->close();

                $stmt = $db->prepare(
                    'SELECT Query AS query, COUNT(*) AS hits
                       FROM tblSearchQueries
                      WHERE SearchedAt >= ? AND ResultCount = 0 AND Query <> ""
                      GROUP BY Query
                      ORDER BY hits DESC
                      LIMIT ?'
                );
                $stmt->bind_param('si', $since, $limit);
                $stmt->execute();
                $zero = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
                $stmt->close();

                /* Coerce numeric fields from string (mysqli_result default)
                   so JSON consumers don't have to parseInt. */
                foreach ($top as &$r) {
                    $r['hits']      = (int)$r['hits'];
                    $r['top_count'] = $r['top_count'] !== null ? (int)$r['top_count'] : 0;
                }
                unset($r);
                foreach ($zero as &$r) { $r['hits'] = (int)$r['hits']; }
                unset($r);
            } catch (\Throwable $e) {
                /* tblSearchQueries may not exist on a pre-#404 deploy.
                   Surface as 503 so the caller knows it's a setup issue
                   rather than malformed input. */
                error_log('[admin_analytics_searches] ' . $e->getMessage());
                sendJson([
                    'error' => 'Search analytics not yet available — tblSearchQueries may not be created.',
                    'note'  => 'Run /manage/setup-database to apply the search-query migration.',
                ], 503);
                break;
            }

            sendJson([
                'range_days' => $range,
                'since'      => $since,
                'top'        => $top,
                'zero'       => $zero,
            ]);
            break;
        }

        /* =================================================================
         * READ-SIDE DIAGNOSTICS (#719 PR 2d)
         *
         * Three operational endpoints natives + tooling clients (CI,
         * monitoring) probably want. All admin / global_admin gated.
         * Pure read paths; no mutations.
         * ================================================================= */

        /* -----------------------------------------------------------------
         * Admin: data-health snapshot
         * GET ?action=admin_data_health
         * Returns table-row counts for the canonical tables, plus the
         * legacy-fallback state (songs.json fallback active? share JSON
         * file count vs DB row count? legacy SQLite present?). Mirrors
         * /manage/data-health's panel.
         * ----------------------------------------------------------------- */
        case 'admin_data_health': {
            $authUser = getAuthenticatedUser();
            if (!$authUser || !in_array($authUser['Role'], ['admin', 'global_admin'])) {
                sendJson(['error' => 'Admin access required.'], 403);
                break;
            }

            /* Same allowlist /manage/data-health uses. Hard-coded so a
               future tweak to the canonical-table list lands once and
               both surfaces pick it up by reading this constant. */
            $healthTables = [
                'tblSongs', 'tblSongbooks', 'tblUsers', 'tblUserSetlists',
                'tblSharedSetlists', 'tblSongRequests', 'tblSongRevisions',
                'tblUserGroups', 'tblOrganisations',
            ];

            try {
                $db = getDbMysqli();
            } catch (\Throwable $dbErr) {
                sendJson([
                    'error'         => 'Database unreachable.',
                    'database_up'   => false,
                    'detail'        => $dbErr->getMessage(),
                ], 503);
                break;
            }

            $tableCounts = [];
            foreach ($healthTables as $tbl) {
                try {
                    /* Allowlist guard: $tbl came from the literal array
                       above, but a belt-and-braces in_array check makes
                       the safety provable at the query site without
                       tracing control flow. */
                    if (!in_array($tbl, $healthTables, true)) { continue; }
                    $stmt = $db->prepare('SELECT COUNT(*) FROM `' . $tbl . '`');
                    $stmt->execute();
                    $row = $stmt->get_result()->fetch_row();
                    $tableCounts[$tbl] = (int)($row[0] ?? 0);
                    $stmt->close();
                } catch (\Throwable $_e) {
                    /* Table missing on a fresh deploy is expected;
                       represent as null. */
                    $tableCounts[$tbl] = null;
                }
            }

            /* The SongData JSON-fallback probe was removed here: the
               whole-corpus songs.json fallback no longer exists (WS-J
               #1020), so isJsonFallback() is permanently false and the
               constructor now throws on DB-down (not corrupt JSON) — the
               probe only mislabelled an outage. The `songs_json_fallback`
               / `songs_json_note` response keys are dropped with it. */

            /* Legacy share-directory + SQLite presence checks. Defined
               constants come from config.php; treat absence as "not
               configured" rather than a 500. */
            $shareDirPath  = defined('APP_SETLIST_SHARE_DIR')  ? APP_SETLIST_SHARE_DIR  : '';
            $sqliteDbPath  = defined('APP_ROOT')
                ? dirname(APP_ROOT) . DIRECTORY_SEPARATOR . 'data_share' . DIRECTORY_SEPARATOR . 'SQLite'
                  . DIRECTORY_SEPARATOR . 'ihymns.db'
                : '';

            $shareFileCount      = null;
            $unimportedShareIds  = [];
            if ($shareDirPath && is_dir($shareDirPath)) {
                $files = glob($shareDirPath . DIRECTORY_SEPARATOR . '*.json') ?: [];
                $shareFileCount = count($files);
                if ($shareFileCount > 0 && isset($tableCounts['tblSharedSetlists'])) {
                    $idsOnDisk = array_filter(array_map(
                        fn($f) => preg_match('/^[a-f0-9]{6,32}$/i', basename($f, '.json'))
                                    ? basename($f, '.json') : null,
                        $files
                    ));
                    try {
                        $stmt = $db->prepare('SELECT ShareId FROM tblSharedSetlists');
                        $stmt->execute();
                        $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
                        $stmt->close();
                        $inDb = array_fill_keys(array_column($rows, 'ShareId'), true);
                        foreach ($idsOnDisk as $id) {
                            if (!isset($inDb[$id])) $unimportedShareIds[] = $id;
                        }
                    } catch (\Throwable $_e) {
                        /* tblSharedSetlists missing — leave unimported list empty. */
                    }
                }
            }
            $sqliteExists = $sqliteDbPath && file_exists($sqliteDbPath);
            $sqliteSize   = $sqliteExists ? (int)@filesize($sqliteDbPath) : 0;

            sendJson([
                'database_up'           => true,
                'table_counts'          => $tableCounts,
                'share_dir' => [
                    'configured'        => $shareDirPath !== '',
                    'present'           => $shareDirPath !== '' && is_dir($shareDirPath),
                    'file_count'        => $shareFileCount,
                    'unimported_count'  => count($unimportedShareIds),
                    'unimported_ids'    => $unimportedShareIds,
                ],
                'legacy_sqlite' => [
                    'present'   => $sqliteExists,
                    'size_bytes'=> $sqliteSize,
                ],
            ]);
            break;
        }

        /* -----------------------------------------------------------------
         * Admin: schema-audit JSON
         * GET ?action=admin_schema_audit
         * Mirrors /manage/schema-audit's diff payload — schema.sql vs
         * live DB vs migration coverage. Returns the same {byTable, summary}
         * shape the page consumes.
         * ----------------------------------------------------------------- */
        case 'admin_schema_audit': {
            $authUser = getAuthenticatedUser();
            if (!$authUser || !in_array($authUser['Role'], ['admin', 'global_admin'])) {
                sendJson(['error' => 'Admin access required.'], 403);
                break;
            }

            $schemaSrc = dirname(__DIR__, 1) . DIRECTORY_SEPARATOR . '.sql' . DIRECTORY_SEPARATOR . 'schema.sql';
            $sqlDir    = dirname(__DIR__, 1) . DIRECTORY_SEPARATOR . '.sql';

            try {
                $db = getDbMysqli();
                if (!is_readable($schemaSrc)) {
                    throw new \RuntimeException('schema.sql not readable at ' . $schemaSrc);
                }
                $schemaSql  = (string)file_get_contents($schemaSrc);
                $schemaCols = schemaAuditParseSchema($schemaSql);
                if (!$schemaCols) {
                    throw new \RuntimeException('Parsed zero tables from schema.sql — parser broken or file shape changed.');
                }
                $migrations = schemaAuditScanMigrations($sqlDir);
                $dbCols     = schemaAuditReadDb($db);
                $audit      = schemaAuditCompare($schemaCols, $dbCols, $migrations);

                sendJson([
                    'summary'  => $audit['summary'],
                    'by_table' => $audit['byTable'],
                ]);
            } catch (\Throwable $e) {
                error_log('[admin_schema_audit] ' . $e->getMessage());
                sendJson(['error' => 'Schema audit failed: ' . $e->getMessage()], 500);
            }
            break;
        }

        /* -----------------------------------------------------------------
         * Admin: migrations status
         * GET ?action=admin_migrations_status
         * Walks every migrate-*.php under appWeb/.sql/, matches each
         * declared (table, column) against the live DB, and reports
         * an applied|partial|pending status per migration. Designed
         * for tooling clients (CI, monitoring) — derives state from
         * the schema rather than maintaining a separate registry.
         * ----------------------------------------------------------------- */
        case 'admin_migrations_status': {
            $authUser = getAuthenticatedUser();
            if (!$authUser || !in_array($authUser['Role'], ['admin', 'global_admin'])) {
                sendJson(['error' => 'Admin access required.'], 403);
                break;
            }

            $sqlDir = dirname(__DIR__, 1) . DIRECTORY_SEPARATOR . '.sql';

            try {
                $db = getDbMysqli();
                $migrations = schemaAuditScanMigrations($sqlDir);
                $dbCols     = schemaAuditReadDb($db);

                /* Invert: [tbl.col => [files...]] becomes [file => [(tbl,col), ...]]. */
                $byFile = [];
                foreach ($migrations as $key => $files) {
                    [$tbl, $col] = explode('.', $key, 2);
                    foreach ($files as $f) {
                        $byFile[$f][] = ['table' => $tbl, 'column' => $col];
                    }
                }

                $report = [];
                foreach ($byFile as $file => $declared) {
                    $applied = 0;
                    foreach ($declared as $d) {
                        if (in_array($d['column'], $dbCols[$d['table']] ?? [], true)) {
                            $applied++;
                        }
                    }
                    $total  = count($declared);
                    $status = $applied === 0       ? 'pending'
                            : ($applied === $total ? 'applied' : 'partial');
                    $report[] = [
                        'file'             => $file,
                        'declared_columns' => $total,
                        'applied_columns'  => $applied,
                        'status'           => $status,
                    ];
                }

                /* Stable sort: pending first, then partial, then applied;
                   alphabetic within each group so the report reads as a
                   "what to run next" punchlist. */
                usort($report, function (array $a, array $b): int {
                    $rank = ['pending' => 0, 'partial' => 1, 'applied' => 2];
                    return $rank[$a['status']] <=> $rank[$b['status']]
                         ?: strcmp($a['file'], $b['file']);
                });

                $summary = ['pending' => 0, 'partial' => 0, 'applied' => 0];
                foreach ($report as $r) { $summary[$r['status']]++; }

                sendJson([
                    'summary'    => $summary,
                    'migrations' => $report,
                ]);
            } catch (\Throwable $e) {
                error_log('[admin_migrations_status] ' . $e->getMessage());
                sendJson(['error' => 'Could not derive migrations status: ' . $e->getMessage()], 500);
            }
            break;
        }

        /* -----------------------------------------------------------------
         * Admin: refresh IANA Language Subtag Registry + CLDR English (#738)
         *
         * Fetches the live IANA registry + CLDR English JSON files,
         * overwrites the bundled snapshots in appWeb/.sql/data/, then
         * re-runs migrate-iana-language-subtag-registry.php so the
         * picker tables pick up new rows. Reports per-table counts in
         * the response.
         *
         * Global-admin only. POST + X-Requested-With per the standard
         * CSRF guard.
         *
         * THIN DELEGATE (BCP 47 registry plan §3.3, rule #35 — one
         * mechanism): the actual fetch/sanity/write/re-import body used to
         * live inline here. It is now `languageRegistryRefreshCore()` in
         * `includes/language_registry_refresh.php`, shared with the new
         * keyed `language-registry-refresh.php` endpoint the monthly
         * GitHub Action pokes — so a fix here fixes both callers, and
         * there is exactly ONE `$sources` URL map in the whole codebase
         * (CI-guarded: tests/php/test-language-registry-refresh.php).
         * ----------------------------------------------------------------- */
        case 'admin_refresh_iana_cldr': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || ($authUser['Role'] ?? '') !== 'global_admin') {
                sendJson(['error' => 'Global admin access required.'], 403);
                break;
            }

            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'language_registry_refresh.php';
            $result = languageRegistryRefreshCore();

            if (!$result['ok']) {
                /* Two distinct failure shapes the pre-hoist handler had:
                   a directory-not-writable 500, or an upstream-fetch 502.
                   Tell them apart by whether any fetch actually failed. */
                $status = !empty($result['failed']) ? 502 : 500;
                sendJson(array_filter([
                    'error'   => $result['error'],
                    'fetched' => $result['fetched'],
                    'failed'  => $result['failed'] ?: null,
                    'hint'    => !empty($result['failed'])
                        ? 'Check server outbound HTTPS connectivity. The bundled snapshots remain in place; pre-existing data is untouched.'
                        : null,
                ], static fn($v) => $v !== null && $v !== []), $status);
                break;
            }

            sendJson([
                'ok'           => true,
                'fetched'      => $result['fetched'],
                'migrationLog' => $result['migrationLog'],
            ]);
            break;
        }

        /* =================================================================
         * API-COVERAGE BATCH 5 — curator workflows (#1969, plan
         * `.claude/api-coverage-2026-08-28.md` §4.3/§9 A10/A11/A13/A14/A15/A16)
         *
         * Every gate below is the SAME entitlement the sibling manage/*.php
         * page gates on (read from the page first, per the task's own
         * instruction) — never a looser/tighter substitute. Every write
         * delegates to a shared includes/*.php core the sibling page was
         * re-pointed onto in this same batch (rule #22) — no forked SQL.
         * ================================================================= */

        /* -----------------------------------------------------------------
         * A10 — Duplicate & counterpart songs (mirrors manage/duplicate-songs.php)
         * Gates: merge/rebuild/auto_link = manage_duplicate_songs (the
         * page's destructive/bulk-write gate); link/unlink =
         * edit_songs (the page's curator gate). #1218's same-official-
         * songbook force-guard is preserved EXACTLY inside
         * duplicateSongMergeExecute() — never re-implemented or weakened
         * here.
         * ----------------------------------------------------------------- */

        /* POST body: { survivor_id, duplicate_id, force?: bool }
           force=1 is the #1218 §2 type-to-confirm escape hatch for a
           same-official-songbook pair — the confirm ceremony itself lives
           client-side; the server only re-checks the boolean + re-derives
           the guard from the LIVE songbook rows, exactly as the page does. */
        case 'admin_song_merge': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_duplicate_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_duplicate_songs entitlement is required.'], 403);
                break;
            }
            $db   = getDbMysqli();
            $body = json_decode((string)file_get_contents('php://input'), true) ?: [];
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'duplicate_song_admin.php';

            $survivor  = (string)($body['survivor_id']  ?? '');
            $duplicate = (string)($body['duplicate_id'] ?? '');
            $force     = !empty($body['force']);
            $userId    = (int)($authUser['Id'] ?? 0) ?: null;

            try {
                $verdict = duplicateSongMergeExecute($db, $survivor, $duplicate, $force, $userId);
                if (!$verdict['ok']) {
                    sendJson(['error' => $verdict['error']], $verdict['status']);
                    break;
                }
                logActivity('api.admin.song.merge', 'song', $verdict['survivorId'], [
                    'merged_from' => $verdict['mergedFrom'],
                    'tables'      => $verdict['tables'],
                ]);
                sendJson(['ok' => true, 'survivorId' => $verdict['survivorId'], 'mergedFrom' => $verdict['mergedFrom']]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.song.merge', 'song', $duplicate, $e);
                error_log('[admin_song_merge] ' . $e->getMessage());
                sendJson(['error' => 'Merge failed.'], 500);
            }
            break;
        }

        /* POST body: { song_ids: [SongId, ...] (>= 2), note?: string }
           Cluster-batch: links every id to the FIRST id in the list,
           pairwise, via the shared per-song core includes/song_link_
           admin.php's songLinkAdd() — a behavioural MIRROR of api2.php's
           song_link_add (api2.php itself was out of scope for this batch
           and keeps its own copy; see song_link_admin.php's doc-block) —
           never a forked bulk algorithm within THIS batch's own scope
           (rule #22). A pair that is already in two DIFFERENT counterpart
           groups stops the batch with that pair's own 409 (status is the
           contract, rule #35); every id linked before the failure stays
           linked — a partial batch is reported, not silently rolled back,
           since each pairwise link is its own already-committed
           transaction. */
        case 'admin_song_link': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('edit_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The edit_songs entitlement is required.'], 403);
                break;
            }
            $db   = getDbMysqli();
            $body = json_decode((string)file_get_contents('php://input'), true) ?: [];
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'song_link_admin.php';

            $ids = $body['song_ids'] ?? [];
            if (is_string($ids)) { $ids = explode(',', $ids); }
            $ids = array_values(array_unique(array_filter(
                array_map(static fn($v): string => trim((string)$v), (array)$ids),
                static fn(string $v): bool => $v !== ''
            )));
            $note = trim((string)($body['note'] ?? ''));
            if (count($ids) < 2) {
                sendJson(['error' => 'Provide at least two song_ids to link.'], 400);
                break;
            }

            try {
                $userId  = (int)($authUser['Id'] ?? 0) ?: null;
                $groupId = null;
                $results = [];
                $failure = null;
                $n = count($ids);
                for ($i = 1; $i < $n; $i++) {
                    $r = songLinkAdd($db, $ids[0], $ids[$i], $note, $userId);
                    if (!$r['ok']) {
                        $failure = $r + ['songId' => $ids[$i]];
                        break;
                    }
                    $groupId = $r['groupId'];
                    $results[] = ['songId' => $ids[$i]] + array_diff_key($r, ['ok' => 1]);
                }
                if ($failure !== null) {
                    sendJson(['error' => $failure['error'], 'song_id' => $failure['songId'], 'linked' => $results], $failure['status']);
                    break;
                }
                logActivity('api.admin.song.link', 'song', $ids[0], ['groupId' => $groupId, 'members' => $ids]);
                sendJson(['ok' => true, 'groupId' => $groupId, 'members' => $ids, 'results' => $results]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.song.link', 'song', $ids[0] ?? '', $e);
                error_log('[admin_song_link] ' . $e->getMessage());
                sendJson(['error' => 'Link failed.'], 500);
            }
            break;
        }

        /* POST body: { song_ids: [SongId, ...] } (a single song_id is also
           accepted for a one-song unlink). Cluster-batch removal — each id
           is dropped from its OWN counterpart group independently via the
           SAME per-song core (includes/song_link_admin.php's
           songLinkRemove()) manage/duplicate-songs.php's own 'unlink'
           action also calls — one remove implementation within this
           batch's scope, and a behavioural MIRROR of api2.php's
           song_link_remove (api2.php itself was out of scope this batch;
           see song_link_admin.php's doc-block). */
        case 'admin_song_unlink': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('edit_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The edit_songs entitlement is required.'], 403);
                break;
            }
            $db   = getDbMysqli();
            $body = json_decode((string)file_get_contents('php://input'), true) ?: [];
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'song_link_admin.php';

            $ids = $body['song_ids'] ?? ($body['song_id'] ?? []);
            if (is_string($ids)) { $ids = explode(',', $ids); }
            $ids = array_values(array_unique(array_filter(
                array_map(static fn($v): string => trim((string)$v), (array)$ids),
                static fn(string $v): bool => $v !== ''
            )));
            if (count($ids) < 1) {
                sendJson(['error' => 'Provide at least one song_id to unlink.'], 400);
                break;
            }

            try {
                $deleted = [];
                foreach ($ids as $sid) {
                    $r = songLinkRemove($db, null, $sid);
                    $deleted[$sid] = (int)($r['deleted'] ?? 0);
                }
                logActivity('api.admin.song.unlink', 'song', $ids[0], ['song_ids' => $ids, 'deleted' => $deleted]);
                sendJson(['ok' => true, 'deleted' => $deleted]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.song.unlink', 'song', $ids[0] ?? '', $e);
                error_log('[admin_song_unlink] ' . $e->getMessage());
                sendJson(['error' => 'Unlink failed.'], 500);
            }
            break;
        }

        /* POST, no body — re-runs the fuzzy suggestion builder over the
           whole catalogue (#1219). Mirrors manage/duplicate-songs.php's
           'rebuild' action exactly (same shared core,
           duplicateSongRebuildSuggestions()). Gate matches the page's
           curator (edit_songs) gate — the page never required
           manage_duplicate_songs for this read-scoring-only op. */
        case 'admin_song_suggestions_rebuild': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('edit_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The edit_songs entitlement is required.'], 403);
                break;
            }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'duplicate_song_admin.php';

            try {
                $verdict = duplicateSongRebuildSuggestions();
                if (!$verdict['ok']) {
                    sendJson(['error' => $verdict['error']], $verdict['status']);
                    break;
                }
                sendJson(['ok' => true, 'message' => $verdict['message']]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.song.suggestions_rebuild', 'song', '', $e);
                error_log('[admin_song_suggestions_rebuild] ' . $e->getMessage());
                sendJson(['error' => 'Rebuild failed.'], 500);
            }
            break;
        }

        /* POST, no body — bulk-link cross-book songs sharing a hard id
           (ISWC/CCLI/ISRC, #1125). Mirrors manage/duplicate-songs.php's
           'auto_link' action exactly (shared core, duplicateSongAutoLink(),
           itself a thin wrapper over the pre-existing
           autoLinkHardIdCounterparts()). Gate = manage_duplicate_songs —
           the page's own gate for this bulk, non-interactive write. */
        case 'admin_song_auto_link': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_duplicate_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_duplicate_songs entitlement is required.'], 403);
                break;
            }
            $db = getDbMysqli();
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'duplicate_song_admin.php';

            try {
                $userId  = (int)($authUser['Id'] ?? 0) ?: null;
                $verdict = duplicateSongAutoLink($db, $userId);
                if (!$verdict['ok']) {
                    sendJson(['error' => $verdict['error']], $verdict['status']);
                    break;
                }
                $r = array_diff_key($verdict, ['ok' => 1]);
                logActivity('api.admin.song.link.auto', 'song', '', $r);
                sendJson(['ok' => true] + $r);
            } catch (\Throwable $e) {
                logActivityError('api.admin.song.auto_link', 'song', '', $e);
                error_log('[admin_song_auto_link] ' . $e->getMessage());
                sendJson(['error' => 'Auto-link failed.'], 500);
            }
            break;
        }

        /* -----------------------------------------------------------------
         * A11 — Deleted songs restore/purge (mirrors manage/deleted-songs.php)
         * Gates: restore = delete_songs (the page's own gate); purge =
         * purge_songs (the page's separate, stricter per-action gate —
         * D3 owner decision so a delete_songs-only role can never
         * silently gain irreversible purge power). Both delegate to the
         * ONE lifecycle core, includes/song_soft_delete.php, already
         * shared with the page — no new core needed here.
         * ----------------------------------------------------------------- */

        /* POST body: { song_id } */
        case 'admin_song_restore': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('delete_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The delete_songs entitlement is required.'], 403);
                break;
            }
            $db     = getDbMysqli();
            $body   = json_decode((string)file_get_contents('php://input'), true) ?: [];
            $songId = trim((string)($body['song_id'] ?? ''));
            $userId = (int)($authUser['Id'] ?? 0) ?: null;

            try {
                $verdict = songRestore($db, $songId, $userId);
                if (!$verdict['ok']) {
                    sendJson(['error' => $verdict['error']], $verdict['status']);
                    break;
                }
                logActivity('api.admin.song.restore', 'song', $songId, [
                    'title'    => (string)($verdict['title'] ?? ''),
                    'songbook' => (string)($verdict['songbook'] ?? ''),
                ]);
                sendJson(['ok' => true, 'songId' => $songId]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.song.restore', 'song', $songId, $e);
                error_log('[admin_song_restore] ' . $e->getMessage());
                sendJson(['error' => 'Restore failed.'], 500);
            }
            break;
        }

        /* POST body: { song_id, confirm, redirect_to? }
           `confirm` MUST equal `song_id` exactly (case-insensitive) — the
           #1218 §2 type-to-confirm ceremony re-enforced server-side
           (rule #29-adjacent: a client-side arm alone cannot be trusted;
           a replayed/hand-built POST without the typed id is refused). */
        case 'admin_song_purge': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('purge_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The purge_songs entitlement is required.'], 403);
                break;
            }
            $db      = getDbMysqli();
            $body    = json_decode((string)file_get_contents('php://input'), true) ?: [];
            $songId  = trim((string)($body['song_id'] ?? ''));
            $confirm = trim((string)($body['confirm'] ?? ''));
            if ($songId === '' || strcasecmp($confirm, $songId) !== 0) {
                sendJson(['error' => 'Type the exact song id to confirm the purge.'], 400);
                break;
            }
            $redirectTo = trim((string)($body['redirect_to'] ?? ''));
            $userId     = (int)($authUser['Id'] ?? 0) ?: null;

            try {
                $verdict = songPurge($db, $songId, $userId, $redirectTo === '' ? null : $redirectTo);
                if (!$verdict['ok']) {
                    sendJson(['error' => $verdict['error']], $verdict['status']);
                    break;
                }
                logActivity('api.admin.song.purge', 'song', $songId, [
                    'title'       => (string)($verdict['title'] ?? ''),
                    'songbook'    => (string)($verdict['songbook'] ?? ''),
                    'redirect_to' => $verdict['redirectTo'] ?? '(tombstone)',
                ]);
                sendJson([
                    'ok'         => true,
                    'songId'     => $songId,
                    'deleted'    => (int)($verdict['deleted'] ?? 0),
                    'redirectTo' => $verdict['redirectTo'] ?? null,
                ]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.song.purge', 'song', $songId, $e);
                error_log('[admin_song_purge] ' . $e->getMessage());
                sendJson(['error' => 'Purge failed.'], 500);
            }
            break;
        }

        /* -----------------------------------------------------------------
         * A13 — Musician-duplicate dismiss/undismiss (mirrors
         * manage/musician-duplicates.php). Gate = manage_musicians — the
         * page's ONE uniform gate for view + dismiss + merge (admin_musician_
         * merge already exists; never re-added here). Both delegate to the
         * ONE shared core, includes/musician_duplicates.php.
         * ----------------------------------------------------------------- */

        /* POST body: { ids: "1,2,3" or [1,2,3], reason? } */
        case 'admin_musician_duplicate_dismiss': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_musicians', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_musicians entitlement is required.'], 403);
                break;
            }
            $db   = getDbMysqli();
            $body = json_decode((string)file_get_contents('php://input'), true) ?: [];
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'musician_duplicates.php';

            $idsRaw = $body['ids'] ?? [];
            if (is_string($idsRaw)) { $idsRaw = explode(',', $idsRaw); }
            $userId = (int)($authUser['Id'] ?? 0) ?: null;

            try {
                $result = musicianDuplicatesDismissCluster($db, (array)$idsRaw, $userId, (string)($body['reason'] ?? ''));
                if (!$result['ok']) {
                    sendJson(['error' => $result['error']], $result['status']);
                    break;
                }
                logActivity('api.admin.musicians.dupe_dismiss', 'musician', (string)$result['ids'][0], [
                    'ids' => $result['ids'], 'reason' => $result['reason'],
                ]);
                sendJson(['ok' => true, 'ids' => $result['ids'], 'reason' => $result['reason']]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.musicians.dupe_dismiss', 'musician', '', $e);
                error_log('[admin_musician_duplicate_dismiss] ' . $e->getMessage());
                sendJson(['error' => 'Dismiss failed.'], 500);
            }
            break;
        }

        /* POST body: { id_a, id_b } */
        case 'admin_musician_duplicate_undismiss': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_musicians', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_musicians entitlement is required.'], 403);
                break;
            }
            $db   = getDbMysqli();
            $body = json_decode((string)file_get_contents('php://input'), true) ?: [];
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'musician_duplicates.php';

            try {
                $result = musicianDuplicatesUndismissPair($db, (int)($body['id_a'] ?? 0), (int)($body['id_b'] ?? 0));
                if (!$result['ok']) {
                    sendJson(['error' => $result['error']], $result['status']);
                    break;
                }
                logActivity('api.admin.musicians.dupe_undismiss', 'musician', (string)$result['idA'], [
                    'id_a' => $result['idA'], 'id_b' => $result['idB'],
