        /* Mint a NEW signing secret; the previous one keeps working for the
           #1909 24h grace window. POST body (JSON): { id } */
        case 'admin_webhook_rotate_secret': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_webhooks', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_webhooks entitlement is required.'], 403);
                break;
            }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'webhook_admin.php';
            $whDb = getDbMysqli();
            if (!webhookSchemaReady($whDb)) {
                sendJson(['error' => 'Webhook tables are not migrated on this environment.'], 409);
                break;
            }
            $whBody = json_decode((string)file_get_contents('php://input'), true) ?: [];
            $whId   = (int)($whBody['id'] ?? 0);
            if ($whId <= 0) { sendJson(['error' => 'id is required.'], 400); break; }

            try {
                $result = webhookSubscriptionRotateSecret($whDb, $whId);
                if (!$result['ok']) { sendJson(['error' => $result['error'] ?? 'Subscription not found.'], 404); break; }
                /* NEVER the secret itself in the audit log Details. */
                logActivity('api.admin.webhook.secret_rotate', 'webhook', (string)$whId, []);
                /* New signing secret returned ONCE — never retrievable again (show-once). */
                sendJson(['ok' => true, 'secret' => $result['secret']]);
            } catch (\Throwable $te) {
                logActivityError('api.admin.webhook.secret_rotate', 'webhook', (string)$whId, $te);
                sendJson(['error' => 'Could not rotate the secret.'], 500);
            }
            break;
        }

        /* Queue a one-off `webhook.test` delivery. POST body (JSON): { id } */
        case 'admin_webhook_send_test': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_webhooks', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_webhooks entitlement is required.'], 403);
                break;
            }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'webhook_admin.php';
            $whDb = getDbMysqli();
            if (!webhookSchemaReady($whDb)) {
                sendJson(['error' => 'Webhook tables are not migrated on this environment.'], 409);
                break;
            }
            $whBody = json_decode((string)file_get_contents('php://input'), true) ?: [];
            $whId   = (int)($whBody['id'] ?? 0);
            if ($whId <= 0) { sendJson(['error' => 'id is required.'], 400); break; }

            try {
                $note = 'Test delivery triggered by ' . (string)($authUser['Username'] ?? 'an admin') . ' via the API.';
                $result = webhookEnqueueForSubscription($whDb, $whId, 'webhook.test', ['note' => $note], ['source' => 'api']);
                if (!$result['ok']) { sendJson(['error' => $result['error'] ?? 'Could not queue a test event.'], 400); break; }
                logActivity('api.admin.webhook.test', 'webhook', (string)$whId, ['delivery_id' => $result['delivery_id'] ?? null]);
                sendJson(['ok' => true, 'delivery_id' => $result['delivery_id'] ?? null]);
            } catch (\Throwable $te) {
                logActivityError('api.admin.webhook.test', 'webhook', (string)$whId, $te);
                sendJson(['error' => 'Could not queue a test event.'], 500);
            }
            break;
        }

        /* Permanently delete a subscription (its deliveries CASCADE away).
           POST body (JSON): { id } */
        case 'admin_webhook_delete': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_webhooks', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_webhooks entitlement is required.'], 403);
                break;
            }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'webhook_admin.php';
            $whDb = getDbMysqli();
            if (!webhookSchemaReady($whDb)) {
                sendJson(['error' => 'Webhook tables are not migrated on this environment.'], 409);
                break;
            }
            $whBody = json_decode((string)file_get_contents('php://input'), true) ?: [];
            $whId   = (int)($whBody['id'] ?? 0);
            if ($whId <= 0) { sendJson(['error' => 'id is required.'], 400); break; }

            try {
                $row = webhookSubscriptionGet($whDb, $whId);
                if ($row === null) { sendJson(['error' => 'Subscription not found.'], 404); break; }
                $result = webhookSubscriptionDelete($whDb, $whId);
                if (!$result['ok']) { sendJson(['error' => 'Could not delete the subscription.'], 400); break; }
                logActivity('api.admin.webhook.delete', 'webhook', (string)$whId, ['label' => $row['Label']]);
                sendJson(['ok' => true]);
            } catch (\Throwable $te) {
                logActivityError('api.admin.webhook.delete', 'webhook', (string)$whId, $te);
                sendJson(['error' => 'Could not delete the subscription.'], 500);
            }
            break;
        }

        /* Put a failed/dead/cancelled delivery back in the queue to retry
           now. POST body (JSON): { delivery_id } */
        case 'admin_webhook_redrive': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('manage_webhooks', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The manage_webhooks entitlement is required.'], 403);
                break;
            }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'webhook_admin.php';
            $whDb = getDbMysqli();
            if (!webhookSchemaReady($whDb)) {
                sendJson(['error' => 'Webhook tables are not migrated on this environment.'], 409);
                break;
            }
            $whBody       = json_decode((string)file_get_contents('php://input'), true) ?: [];
            $whDeliveryId = (int)($whBody['delivery_id'] ?? 0);
            if ($whDeliveryId <= 0) { sendJson(['error' => 'delivery_id is required.'], 400); break; }

            try {
                $result = webhookDeliveryRedrive($whDb, $whDeliveryId);
                if (!$result['ok']) {
                    sendJson(['error' => 'Could not re-drive — the delivery may no longer be in a retryable state.'], 409);
                    break;
                }
                logActivity('api.admin.webhook.delivery_redrive', 'webhook', (string)$whDeliveryId, []);
                sendJson(['ok' => true]);
            } catch (\Throwable $te) {
                logActivityError('api.admin.webhook.delivery_redrive', 'webhook', (string)$whDeliveryId, $te);
                sendJson(['error' => 'Could not re-drive the delivery.'], 500);
            }
            break;
        }

        /* =================================================================
         * ADMIN — INTERNET ARCHIVE OCR RECONCILE (#94 Phase 1, ported to
         * the API by API-coverage batch 6b — .claude/
         * api-coverage-2026-08-28.md §4.3 A17, owner-confirmed
         * native-curator surface, Q1=yes)
         *
         * Assessed alongside the MARCXML imports above as one of A17's
         * "genuinely multi-step / interactive tools" — UNLIKE the
         * bulk-promote wizard (manage/musicians-bulk-promote.php, deferred
         * — see this batch's report) and the family_manifest wizard
         * (manage/songbooks.php, also deferred), this one turned out to be
         * a genuinely clean single POST -> JSON-report call: an
         * archive.org identifier + a songbook abbreviation in, a scored
         * candidate report out, with no per-row human correction step and
         * no server-side stored wizard state (every call recomputes the
         * plan from the current DB, exactly like force_refresh does for
         * the cache). Mirrors manage/ia-reconcile.php's POST 'run' handler
         * exactly, delegating end-to-end to the SAME pure pipeline the
         * page calls — includes/ia_client.php's iaCachedMetadata()/
         * iaCachedFulltext() (SSRF-hardened archive.org fetch + DB cache)
         * and includes/ia_reconcile.php's iaRecSegmentOcr()/
         * iaRecSongFeatures()/iaRecScoreCandidates()/iaRecPersistRun()
         * (rule #22) — never a forked fetch/segment/score copy.
         *
         * ZERO WRITES TO SONG CONTENT — the only write is audit
         * bookkeeping (iaRecPersistRun(), itself table-existence-gated and
         * best-effort: a pre-migration install still gets the report, just
         * with `persisted: false`). Gate: edit_songs — identical to the
         * page's own gate (curators who work the gap list can run audits
         * themselves; there is no destructive action to gate more
         * tightly, mirroring the page's own doc-block rationale).
         *
         * POST body: { identifier (required — an archive.org item id or a
         *   details/download URL), songbook_abbr (required),
         *   force_refresh? (bypass the DB cache) }
         * ================================================================= */
        case 'admin_ia_reconcile_run': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
                sendJson(['error' => 'POST method required.'], 405);
                break;
            }
            $authUser = getAuthenticatedUser();
            if (!$authUser || !userHasEntitlement('edit_songs', $authUser['Role'] ?? null)) {
                sendJson(['error' => 'The edit_songs entitlement is required.'], 403);
                break;
            }

            /* Required explicitly rather than leaning on a transitive pull
               from elsewhere in this file (this file's own top-of-file
               precedent, #1698's user_status.php comment) — a transitive
               require is a dependency nothing states and nothing enforces. */
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'identifier_normalize.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'ia_client.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'ia_reconcile.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'title_normalize.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'song_similarity.php';

            $body         = json_decode((string)file_get_contents('php://input'), true) ?: [];
            $identifier   = ihymns_canonical_ia_identifier((string)($body['identifier'] ?? ''));
            $songbookAbbr = trim((string)($body['songbook_abbr'] ?? ''));
            $forceRefresh = !empty($body['force_refresh']);

            if ($identifier === null || $identifier === '') {
                sendJson(['error' => 'That does not look like a valid archive.org identifier or URL.'], 400);
                break;
            }
            if ($songbookAbbr === '') {
                sendJson(['error' => 'songbook_abbr is required.'], 400);
                break;
            }

            $db = getDbMysqli();

            /* @disabled-visible: admin surface (#94/#1765) — mirrors the
               page's own doc-block: a disabled songbook stays fully
               auditable here (owner decision); a curator reconciling a
               disabled songbook against an archive.org scan is exactly as
               legitimate as reconciling any other book. Validate songbook
               existence via a bound lookup — never trust the posted
               abbreviation blindly (rule #5); mirrors the page's own
               against-the-picker-list check. */
            $sbChk = $db->prepare('SELECT 1 FROM tblSongbooks WHERE Abbreviation = ? LIMIT 1');
            $sbChk->bind_param('s', $songbookAbbr);
            $sbChk->execute();
            $songbookValid = $sbChk->get_result()->fetch_row() !== null;
            $sbChk->close();
            if (!$songbookValid) {
                sendJson(['error' => 'Unknown songbook_abbr.'], 400);
                break;
            }

            try {
                /* A cold fetch + segment + score of a large book can exceed
                   the default 30s on shared hosting; cached re-runs are
                   seconds — same rationale as the page's own
                   set_time_limit() call. */
                @set_time_limit(300);

                $metadata = iaCachedMetadata($db, $identifier, $forceRefresh);
                $fulltext = $metadata !== null ? iaCachedFulltext($db, $identifier, $forceRefresh) : null;
                if ($metadata === null || $fulltext === null) {
                    sendJson(['error' => 'archive.org did not answer for "' . $identifier . '", the item has no OCR '
                        . 'text file (_djvu.txt), or the response exceeded the size cap.'], 502);
                    break;
                }

                $candidates = iaRecSegmentOcr($fulltext['text']);
                if (!$candidates) {
                    sendJson(['error' => 'The OCR text was fetched (' . strlen($fulltext['text']) . ' bytes) but could '
                        . 'not be segmented into any hymn-shaped candidates.'], 422);
                    break;
                }

                $songFeatures = iaRecSongFeatures($db, $songbookAbbr);
                $reportResult = iaRecScoreCandidates($candidates, $songFeatures);
                $persisted    = iaRecPersistRun($db, $identifier, $songbookAbbr, $fulltext['sha256'], $reportResult['candidates']);

                logActivity('api.admin.ia_reconcile.run', 'songbook', $songbookAbbr, [
                    'identifier' => $identifier,
                    'candidates' => count($reportResult['candidates']),
                    'gaps'       => $reportResult['summary']['counts']['gap'] ?? 0,
                ]);
                sendJson([
                    'ok'           => true,
                    'identifier'   => $identifier,
                    'songbookAbbr' => $songbookAbbr,
                    'fileName'     => $fulltext['fileName'],
                    'fetchedAt'    => $fulltext['fetchedAt'],
                    'persisted'    => $persisted,
                    'summary'      => $reportResult['summary'],
                    'candidates'   => $reportResult['candidates'],
                ]);
            } catch (\Throwable $e) {
                logActivityError('api.admin.ia_reconcile.run', 'songbook', $songbookAbbr, $e);
                error_log('[admin_ia_reconcile_run] ' . $e->getMessage());
                sendJson(['error' => 'Could not run the reconcile audit.'], 500);
            }
            break;
        }

        /* -----------------------------------------------------------------
         * Live Follow (#1268) — web/PWA real-time multi-device follow.
         * DB-relayed short-poll over tblLiveFollowSessions (no SSE — shared
         * hosting can't hold a worker per follower). The host writes its
         * current song/section/state and bumps StateRevision; followers poll
         * with ?since=<rev> and get a near-free "unchanged" until it advances.
         * Host endpoints require auth + ownership; join/poll are anonymous,
         * scoped by the unguessable code. State-changing POSTs inherit the
         * X-Requested-With CSRF guard at the top of this file.
         * ----------------------------------------------------------------- */
        case 'live_follow_create': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'live_activity_push.php';
            $userId = (int)$authUser['Id'];
            $liveIp = $_SERVER['REMOTE_ADDR'] ?? '';

            /* 20 new sessions / hour / user is plenty for a worship leader. */
            checkRateLimit('live_follow_create', $liveIp, 20, 3600, true, $userId);
            recordRateLimitHit('live_follow_create', rateLimitKey($liveIp, $userId));

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            $setlistId = isset($body['setlistId'])
                ? mb_substr(preg_replace('/[^a-zA-Z0-9_\-]/', '', (string)$body['setlistId']), 0, 100) : null;
            if ($setlistId === '') { $setlistId = null; }
            $songId = isset($body['songId']) ? _liveFollowCleanSongId((string)$body['songId']) : null;
            if ($songId === '') { $songId = null; }
            $componentIndex = (isset($body['componentIndex']) && $body['componentIndex'] !== null)
                ? min(9999, max(0, (int)$body['componentIndex'])) : null;
            $stateJson = serviceMode_cleanState($body['state'] ?? null);
            $orgId = null; /* v1: org scoping deferred; the FK stays NULL (SET NULL-safe). */
            /* #1405 side-finding fix (rule #26) — host-mode Live Follow never
               stamped Channel, so an alpha-created session was joinable from
               production against the shared DB. Stamped here + filtered in
               live_follow_join/_poll below. */
            $channel = serviceMode_channel();

            $db = getDbMysqli();

            /* #1770 C2 — resolve + stamp the leader-idle timeout. Gated on
               the idle columns existing: on an un-migrated install neither
               query runs, so create stays byte-identical to pre-#1770. On a
               migrated install the resolved value is stamped on THIS row
               (see includes/service_mode.php's "stamp-at-create" doc-block)
               so every later gate/prune reads a pure column, never re-runs
               the app→org→user precedence chain per request.
               #1798 — the host may DECLARE a session length at "Go Live"
               ("keep live for 30 min / 1 hour / 2 hours / until I end it").
               $enforcedMins (by-ref out-param) is the host's OWN org-enforced
               cap, if any — the org lock wins for the host even when they
               explicitly asked for longer, mirroring live_follow_extend's
               identical host-side cap. A client that sends nothing keeps
               today's resolved-default behaviour byte-for-byte. */
            $idleColsExist   = serviceMode_idleColumnsExist($db);
            $enforcedMins    = null;
            $idleTimeoutMins = $idleColsExist ? serviceMode_resolveIdleTimeoutMins($db, $userId, $enforcedMins) : null;
            if ($idleColsExist && isset($body['idleTimeoutMins']) && is_numeric($body['idleTimeoutMins'])) {
                $chosenIdle = max(LIVE_FOLLOW_IDLE_TIMEOUT_MIN_MINUTES, min(LIVE_FOLLOW_IDLE_TIMEOUT_MAX_MINUTES, (int)$body['idleTimeoutMins']));
                if ($enforcedMins !== null) {
                    $chosenIdle = min($chosenIdle, $enforcedMins);
                }
                $idleTimeoutMins = $chosenIdle;
            }

            /* #1770 C2 — opportunistic idle-session prune, piggy-backed on
               this hot path (mirrors serviceMode_retireExpiredCodes()'s own
               placement rationale: no cron on this host). Self-gated + fully
               wrapped internally — a prune failure can never fail this
               create. Run BEFORE the supersede below so a host whose OWN
               prior session just went idle is pruned via this path rather
               than silently superseded with no 'end' push. */
            serviceMode_pruneIdleQuickSessions($db, $channel);

            /* Reject an unknown songId up front — the CurrentSongId FK would
               otherwise throw 1452 under STRICT → an uncaught 500. */
            if ($songId !== null) {
                /* #1694 — filtered: a hidden song cannot be NEWLY broadcast
                   (congregants would poll an id that 410s). An in-flight
                   session's CurrentSongId is untouched. #1765 — same for a
                   song whose songbook has been disabled. */
                $chkSong = $db->prepare('SELECT 1 FROM tblSongs WHERE SongId = ? AND ' . songVisibleSql($db, '') . ' AND ' . songServableSql($db, '') . ' LIMIT 1');
                $chkSong->bind_param('s', $songId);
                $chkSong->execute();
                $songOk = $chkSong->get_result()->fetch_row() !== null;
                $chkSong->close();
                if (!$songOk) { sendJson(['error' => 'Unknown song.'], 400); break; }
            }

            /* One active session per host — supersede any prior one. #1429 —
               capture the OLD session's Id BEFORE deactivating so its Live
               Activity (if any device registered one) can be told the
               broadcast has ended, rather than left stuck "live" forever.
               #1429 Audit-B F4 — CHANNEL-SCOPED (rule #26), matching
               service_session_start's own supersede below: without this, a
               host's prior active session on a DIFFERENT channel (e.g. an
               alpha-created session, HostUserId shared across the 3
               docroots via the same MySQL) would be silently deactivated
               here with NO end-push ever sent for it (liveActivitySessionPush
               itself channel-re-resolves and would just no-op on a
               cross-channel session id). */
            $oldSel = $db->prepare('SELECT Id FROM tblLiveFollowSessions WHERE HostUserId = ? AND IsActive = 1 AND Channel = ?');
            $oldSel->bind_param('is', $userId, $channel);
            $oldSel->execute();
            $oldRow = $oldSel->get_result()->fetch_assoc();
            $oldSel->close();

            $deact = $db->prepare('UPDATE tblLiveFollowSessions SET IsActive = 0 WHERE HostUserId = ? AND IsActive = 1 AND Channel = ?');
            $deact->bind_param('is', $userId, $channel);
            $deact->execute();
            $superseded = $deact->affected_rows > 0;
            $deact->close();
            if ($oldRow) {
                $oldSessionId = (int)$oldRow['Id'];
                /* #1770 C3 — a host restarting supersedes their own old
                   session here; that old session's presence rows must be
                   revoked too, or a follower who joined it keeps a live
                   CCLI-unlock token until its own ExpiresAt (plan §11
                   landmine 4 — the SAME instant-revocation shape as
                   live_follow_leave and the idle prune, applied to the
                   THIRD session-death path). Table-existence-gated + wrapped. */
                if (serviceMode_presenceTableExists($db)) {
                    try {
                        $oldRevStmt = $db->prepare('UPDATE tblServicePresence SET IsActive = 0 WHERE SessionId = ?');
                        $oldRevStmt->bind_param('i', $oldSessionId);
                        $oldRevStmt->execute();
                        $oldRevStmt->close();
                    } catch (\Throwable $_e) {
                        error_log('[live_follow_create/supersede-presence] ' . $_e->getMessage());
                    }
                }
                liveActivitySessionPush($db, $oldSessionId, 'end');
            }

            /* Crockford-ish base32, no ambiguous glyphs (no I/L/O/U/0/1). */
            $alphabet = 'ABCDEFGHJKMNPQRSTVWXYZ23456789';
            $alphaMax = strlen($alphabet) - 1;
            $code = '';
            $inserted = false;
            for ($attempt = 0; $attempt < 6 && !$inserted; $attempt++) {
                $code = '';
                for ($i = 0; $i < 6; $i++) { $code .= $alphabet[random_int(0, $alphaMax)]; }
                try {
                    /* #1770 C2 — two INSERT shapes (the service_join
                       Role-gate precedent, api.php's serviceMode_presenceRoleColumnExists
                       branch) rather than one dynamically-built column list:
                       clearer to read, and mysqli's bind_param type string
                       must match the placeholder count exactly either way. */
                    if ($idleColsExist) {
                        $ins = $db->prepare(
                            'INSERT INTO tblLiveFollowSessions
                                (SessionCode, HostUserId, OrgId, SetlistId, CurrentSongId,
                                 CurrentComponentIndex, StateJson, Channel, IsActive, StartedAt,
                                 LastHeartbeatAt, ExpiresAt, StateRevision, LastLeaderSeenAt, IdleTimeoutMins)
                             VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP(),
                                     DATE_ADD(UTC_TIMESTAMP(), INTERVAL 4 HOUR), 0, UTC_TIMESTAMP(), ?)'
                        );
                        $ins->bind_param('siississi', $code, $userId, $orgId, $setlistId, $songId, $componentIndex, $stateJson, $channel, $idleTimeoutMins);
                    } else {
                        $ins = $db->prepare(
                            'INSERT INTO tblLiveFollowSessions
                                (SessionCode, HostUserId, OrgId, SetlistId, CurrentSongId,
                                 CurrentComponentIndex, StateJson, Channel, IsActive, StartedAt,
                                 LastHeartbeatAt, ExpiresAt, StateRevision)
                             VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP(),
                                     DATE_ADD(UTC_TIMESTAMP(), INTERVAL 4 HOUR), 0)'
                        );
                        $ins->bind_param('siississ', $code, $userId, $orgId, $setlistId, $songId, $componentIndex, $stateJson, $channel);
                    }
                    $ins->execute();
                    $ins->close();
                    $inserted = true;
                } catch (\mysqli_sql_exception $e) {
                    /* uq_Code collision (errno 1062) — retry; anything else is real. */
                    if ($e->getCode() !== 1062) { throw $e; }
                }
            }
            if (!$inserted) { sendJson(['error' => 'Could not allocate a session code, please retry.'], 503); break; }

            /* §3.2 breadcrumb — numeric Id only, never the SessionCode. */
            $newSessionId = (int)$db->insert_id;
            logActivity('live.session.create', 'live_session', (string)$newSessionId, [
                'superseded'  => $superseded,
                'has_setlist' => $setlistId !== null,
                'has_song'    => $songId !== null,
            ]);

            /* #1429 — sessionId exposed so the native app can immediately
               register a Live Activity push token against THIS session
               (apns_register's kind=liveActivity branch requires it).
               #1770 C2 — idleTimeoutMins is ADDITIVE (null pre-migration);
               a client that doesn't read the key is unaffected. */
            sendJson(['ok' => true, 'code' => $code, 'revision' => 0, 'sessionId' => $newSessionId, 'idleTimeoutMins' => $idleTimeoutMins]);
            break;
        }

        case 'live_follow_update': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'live_activity_push.php';
            $userId = (int)$authUser['Id'];
            $liveIp = $_SERVER['REMOTE_ADDR'] ?? '';

            /* Generous: a fast operator + heartbeats stay well under 600/min. */
            checkRateLimit('live_follow_update', $liveIp, 600, 60, true, $userId);
            recordRateLimitHit('live_follow_update', rateLimitKey($liveIp, $userId));

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            $code = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($body['code'] ?? '')));
            if (!preg_match('/^[A-Z0-9]{4,12}$/', $code)) { sendJson(['error' => 'Invalid session code.'], 400); break; }

            /* The host broadcasts its FULL current context each update. */
            $songId = isset($body['songId']) ? _liveFollowCleanSongId((string)$body['songId']) : '';
            if ($songId === '') { sendJson(['error' => 'songId is required.'], 400); break; }
            $componentIndex = (isset($body['componentIndex']) && $body['componentIndex'] !== null)
                ? min(9999, max(0, (int)$body['componentIndex'])) : null;
            $stateJson = serviceMode_cleanState($body['state'] ?? null);

            $db = getDbMysqli();

            /* Reject an unknown songId before the CurrentSongId FK throws 1452 → 500.
               #1694 — filtered: a hidden song cannot be NEWLY broadcast.
               #1765 — same for a song whose songbook has been disabled. */
            $chkSong = $db->prepare('SELECT 1 FROM tblSongs WHERE SongId = ? AND ' . songVisibleSql($db, '') . ' AND ' . songServableSql($db, '') . ' LIMIT 1');
            $chkSong->bind_param('s', $songId);
            $chkSong->execute();
            $songOk = $chkSong->get_result()->fetch_row() !== null;
            $chkSong->close();
            if (!$songOk) { sendJson(['error' => 'Unknown song.'], 400); break; }

            /* §3.2 breadcrumb prep — resolve the numeric Id + the PRE-update
               CurrentSongId so a genuine song change (vs a component-index-only
               nudge) can be detected after the write; IDs only, never the code. */
            $preSel = $db->prepare('SELECT Id, CurrentSongId FROM tblLiveFollowSessions WHERE SessionCode = ? AND HostUserId = ? AND IsActive = 1');
            $preSel->bind_param('si', $code, $userId);
            $preSel->execute();
            $preRow = $preSel->get_result()->fetch_assoc();
            $preSel->close();

            /* #1770 C2 — a genuine broadcast IS leader interaction, so
               LastLeaderSeenAt is bumped unconditionally here (gated only on
               the column existing, never on a client flag — unlike the
               heartbeat's opt-in `leaderActive`, an actual song/section
               change needs no client cooperation to count as "a human is
               driving"). The WHERE gains the idle-freshness predicate so a
               broadcast against an idle-expired session falls through to the
               SAME pre-existing 409 the host client already tears down on
               (live-follow.js:186-191) — zero client change needed for the
               close-detection path. Both fragments are '' pre-migration, so
               this SQL is byte-identical to the pre-#1770 statement then. */
            $idleFreshSql  = serviceMode_idleFreshSql($db, 'tblLiveFollowSessions');
            $leaderSeenSet = serviceMode_idleColumnsExist($db) ? ', LastLeaderSeenAt = UTC_TIMESTAMP()' : '';
            $upd = $db->prepare(
                'UPDATE tblLiveFollowSessions
                    SET CurrentSongId = ?, CurrentComponentIndex = ?, StateJson = ?,
                        LastHeartbeatAt = UTC_TIMESTAMP()' . $leaderSeenSet . ',
                        ExpiresAt = DATE_ADD(UTC_TIMESTAMP(), INTERVAL 4 HOUR),
                        StateRevision = StateRevision + 1
                  WHERE SessionCode = ? AND HostUserId = ? AND IsActive = 1' . $idleFreshSql
            );
            $upd->bind_param('sissi', $songId, $componentIndex, $stateJson, $code, $userId);
            $upd->execute();
            $changed = $upd->affected_rows;
            $upd->close();
            if ($changed === 0) { sendJson(['ok' => false, 'error' => 'Session not found, not yours, or ended.'], 409); break; }

            if ($preRow && (string)($preRow['CurrentSongId'] ?? '') !== (string)$songId) {
                logActivity('live.broadcast.song', 'live_session', (string)$preRow['Id'], ['song_id' => $songId]);
            }

            $sel = $db->prepare('SELECT StateRevision FROM tblLiveFollowSessions WHERE SessionCode = ? AND HostUserId = ?');
            $sel->bind_param('si', $code, $userId);
            $sel->execute();
            $revRow = $sel->get_result()->fetch_row();
            $rev = $revRow ? (int)$revRow[0] : 0;
            $sel->close();

            /* #1429 — $preRow['Id'] is the session's numeric Id (unchanged by
               this UPDATE, since it filters on SessionCode+HostUserId, not
               Id) — reused here rather than re-selecting it. */
            if (isset($preRow['Id'])) {
                liveActivitySessionPush($db, (int)$preRow['Id'], 'update');
            }

            sendJson(['ok' => true, 'revision' => $rev]);
            break;
        }

        case 'live_follow_heartbeat': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            $userId = (int)$authUser['Id'];

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }
            $code = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($body['code'] ?? '')));
            if (!preg_match('/^[A-Z0-9]{4,12}$/', $code)) { sendJson(['error' => 'Invalid session code.'], 400); break; }
            /* #1770 C2 — an EXPLICIT, client-declared "a human touched the
               app since the last beat" flag. The automated 30s keepalive
               ALONE must never bump LastLeaderSeenAt (plan §11 landmine 3:
               that recreates the immortal-abandoned-tab bug this feature
               exists to fix) — only a genuine leaderActive:true does. A
               pre-#1770 C5 client never sends this key, so `$leaderActive`
               is always false for it and this endpoint's SQL is unchanged
               for such callers even on a migrated install. */
            $leaderActive = !empty($body['leaderActive']);

            $db = getDbMysqli();
            $idleColsExist = serviceMode_idleColumnsExist($db);
            $leaderSeenSet = ($idleColsExist && $leaderActive) ? ', LastLeaderSeenAt = UTC_TIMESTAMP()' : '';

            /* Keepalive only — does NOT bump StateRevision (no state changed). */
            $hb = $db->prepare(
                'UPDATE tblLiveFollowSessions
                    SET LastHeartbeatAt = UTC_TIMESTAMP()' . $leaderSeenSet . ',
                        ExpiresAt = DATE_ADD(UTC_TIMESTAMP(), INTERVAL 4 HOUR)
                  WHERE SessionCode = ? AND HostUserId = ? AND IsActive = 1'
            );
            $hb->bind_param('si', $code, $userId);
            $hb->execute();
            $hb->close();

            /* Liveness via existence, NOT affected_rows: two heartbeats in the
               same second write identical timestamps, so affected_rows (changed
               rows) would be 0 even though the session is fine.
               #1770 C2 — the idle-freshness predicate is folded into THIS
               read (not the UPDATE above, whose job is only to keep
               LastHeartbeatAt/ExpiresAt current) so an idle-expired session
               still gets touched harmlessly but answers ok:false — the same
               signal live-follow.js already treats as "session ended"
               (:214), so this needs no client change to take effect. */
            $idleFreshSql = serviceMode_idleFreshSql($db, 'tblLiveFollowSessions');
            $chk = $db->prepare(
                'SELECT 1 FROM tblLiveFollowSessions
                  WHERE SessionCode = ? AND HostUserId = ? AND IsActive = 1' . $idleFreshSql
            );
            $chk->bind_param('si', $code, $userId);
            $chk->execute();
            $alive = $chk->get_result()->fetch_row() !== null;
            $chk->close();

            sendJson(['ok' => $alive]);
            break;
        }

        case 'live_follow_leave': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'live_activity_push.php';
            $userId = (int)$authUser['Id'];

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }
            $code = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($body['code'] ?? '')));
            if (!preg_match('/^[A-Z0-9]{4,12}$/', $code)) { sendJson(['error' => 'Invalid session code.'], 400); break; }

            $db = getDbMysqli();

            /* §3.2 breadcrumb prep — resolve the numeric Id before ending so the
               log carries an id, never the SessionCode. */
            $endSel = $db->prepare('SELECT Id FROM tblLiveFollowSessions WHERE SessionCode = ? AND HostUserId = ?');
            $endSel->bind_param('si', $code, $userId);
            $endSel->execute();
            $endRow = $endSel->get_result()->fetch_assoc();
            $endSel->close();

            $end = $db->prepare('UPDATE tblLiveFollowSessions SET IsActive = 0 WHERE SessionCode = ? AND HostUserId = ?');
            $end->bind_param('si', $code, $userId);
            $end->execute();
            $end->close();

            if ($endRow) {
                $endSessionId = (int)$endRow['Id'];
                /* #1770 C3 — instant gate revocation, the same shape as
                   service_session_end's transaction (api.php:17608-17633)
                   and the idle prune (service_mode.php). Every follower's
                   presence dies the moment the HOST ends the session — this
                   is the "session death" half of the leader-idle mitigation
                   (plan §11 landmine 4: presence revocation on EVERY
                   session-death path). Table-existence-gated + wrapped:
                   never fails an otherwise-successful leave. */
                if (serviceMode_presenceTableExists($db)) {
                    try {
                        $revStmt = $db->prepare('UPDATE tblServicePresence SET IsActive = 0 WHERE SessionId = ?');
                        $revStmt->bind_param('i', $endSessionId);
                        $revStmt->execute();
                        $revStmt->close();
                    } catch (\Throwable $_e) {
                        error_log('[live_follow_leave/presence] ' . $_e->getMessage());
                    }
                }
                logActivity('live.session.end', 'live_session', (string)$endSessionId, []);
                liveActivitySessionPush($db, $endSessionId, 'end');
            }

            sendJson(['ok' => true]);
            break;
        }

        /* -----------------------------------------------------------------
         * #1798 (follow-on to #1770/#1792) — extend/keep a running Quick
         * ("Go Live") session alive mid-service. ELI5: the leader's phone
         * died during the sermon and the idle clock is about to close their
         * session — this resets the clock and (optionally) widens the
         * window, and lets a church admin do the same on the leader's
         * behalf. DETAILED — authorisation is resolved via the HOST's OWN
         * `tblOrganisationMembers` rows, never the session's `OrgId` column:
         * Quick sessions keep `OrgId = NULL` (rule #26, load-bearing for the
         * CCLI gate), so "is the caller an org-admin who may act here?" is
         * answered by walking from the HOST to their orgs, not from the
         * session. Existence-gated on `serviceMode_idleColumnsExist()` — the
         * whole idle machinery (and therefore "extend" as a concept) simply
         * doesn't exist pre-#1770 migration.
         * ----------------------------------------------------------------- */
        case 'live_follow_extend': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            /* validateCsrfRequest() lives in manage/includes/auth.php — the
               SAME belt-and-braces pattern as auth_provider_unlink/
               account_delete (rule #29): the global X-Requested-With gate
               (api.php top-of-file) already blocks a cross-site POST; this
               is a second, independent check on THIS state-changing write. */
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'manage' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'auth.php';
            $userId        = (int)$authUser['Id'];
            $requesterRole = (string)($authUser['Role'] ?? '');
            $liveIp        = $_SERVER['REMOTE_ADDR'] ?? '';

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            $csrfToken = is_string($body['csrf_token'] ?? null) ? $body['csrf_token'] : null;
            if (!validateCsrfRequest($csrfToken)) {
                sendJson(['error' => 'Cross-origin request rejected.'], 403);
                break;
            }

            /* 60 extends / hour / user — generous for the occasional
               dead-phone-mid-sermon case, paired with recordRateLimitHit
               below (the two-call contract, rule #1636 /
               test-rate-limit-pairing.php). */
            checkRateLimit('live_follow_extend', $liveIp, 60, 3600, true, $userId);
            recordRateLimitHit('live_follow_extend', rateLimitKey($liveIp, $userId));

            $code = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($body['code'] ?? '')));
            if (!preg_match('/^[A-Z0-9]{4,12}$/', $code)) { sendJson(['error' => 'Invalid session code.'], 400); break; }

            $requestedIdle = $body['idleTimeoutMins'] ?? null;
            if ($requestedIdle === null || !is_numeric($requestedIdle)) {
                sendJson(['error' => 'idleTimeoutMins is required.'], 400);
                break;
            }

            $db = getDbMysqli();

            /* Gate FIRST, before anything below touches the IdleTimeoutMins/
               LastLeaderSeenAt columns — mysqli runs STRICT (rule #9), so an
               un-migrated install would throw, not silently no-op. 409 (not
               404/400) so the client can tell "not applicable on this
               install yet" apart from "wrong code" (rule #35). */
            if (!serviceMode_idleColumnsExist($db)) {
                sendJson(['error' => 'This install has not been migrated for Live Follow session lengths yet.'], 409);
                break;
            }

            /* Resolve the session — channel-scoped (rule #26): a code on a
               DIFFERENT docroot's session must never be touched, even though
               all three docroots share one MySQL. Every write below keys off
               this row's numeric Id, so the channel scoping happens HERE,
               once, rather than being repeated on the UPDATE. */
            $channel = serviceMode_channel();
            $selSess = $db->prepare(
                'SELECT Id, HostUserId FROM tblLiveFollowSessions
                  WHERE SessionCode = ? AND Channel = ? AND IsActive = 1'
            );
            $selSess->bind_param('ss', $code, $channel);
            $selSess->execute();
            $sessRow = $selSess->get_result()->fetch_assoc();
            $selSess->close();
            if (!$sessRow) { sendJson(['error' => 'Session not found or ended.'], 404); break; }
            $sessionId  = (int)$sessRow['Id'];
            $hostUserId = (int)$sessRow['HostUserId'];

            /* Authorisation — the HOST, OR an admin/owner of an org the HOST
               belongs to, OR a site admin/global_admin (mirrors
               userCanActOnOrg()'s own role check). Resolved via the HOST's
               tblOrganisationMembers rows, never the session's own OrgId —
               Quick sessions keep OrgId = NULL (rule #26). Extracted into
               serviceMode_liveFollowExtendAuthorize() so the DECISION is
               independently unit-testable (tests/php/test-live-follow-extend.php)
               without an HTTP harness around this dispatcher. */
            $authKind = serviceMode_liveFollowExtendAuthorize($db, $hostUserId, $userId, $requesterRole);
            if ($authKind === 'denied') {
                sendJson(['error' => 'Not authorised to extend this session.'], 403);
                break;
            }
            $isHost = ($authKind === 'host');

            $chosenIdle = max(LIVE_FOLLOW_IDLE_TIMEOUT_MIN_MINUTES, min(LIVE_FOLLOW_IDLE_TIMEOUT_MAX_MINUTES, (int)$requestedIdle));
            if ($isHost) {
                /* The HOST's own org-enforced cap binds them here exactly as
                   it did at create (live_follow_create above) — asking for
                   more time through the "Extend" control doesn't lift the
                   org's lock. */
                $enforcedMins = null;
                serviceMode_resolveIdleTimeoutMins($db, $hostUserId, $enforcedMins);
                if ($enforcedMins !== null) {
                    $chosenIdle = min($chosenIdle, $enforcedMins);
                }
            }
            /* else: an org-admin or site-admin extending on the host's
               behalf holds the authority to override that lock — capped
               only at the global [5,240] band already applied above. */
            $appliedIdle = $chosenIdle;

            /* Set the new window AND reset the idle clock to now, so the
               FULL window applies from the moment of extending — the whole
               point of the feature (a dead phone mid-sermon shouldn't leave
               the leader with whatever fraction of the old window remained). */
            $upd = $db->prepare(
                'UPDATE tblLiveFollowSessions
                    SET IdleTimeoutMins = ?, LastLeaderSeenAt = UTC_TIMESTAMP(),
                        ExpiresAt = DATE_ADD(UTC_TIMESTAMP(), INTERVAL 4 HOUR)
                  WHERE Id = ? AND IsActive = 1'
            );
            $upd->bind_param('ii', $appliedIdle, $sessionId);
            $upd->execute();
            $changed = $upd->affected_rows;
            $upd->close();
            if ($changed === 0) {
                sendJson(['ok' => false, 'error' => 'Session not found, not yours, or ended.'], 409);
                break;
            }

            logActivity('live.session.extend', 'live_session', (string)$sessionId, [
                'by'   => $isHost ? 'host' : 'org_admin',
                'mins' => $appliedIdle,
            ]);

            sendJson(['ok' => true, 'idleTimeoutMins' => $appliedIdle]);
            break;
        }

        case 'live_follow_join': {
            $code = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($_GET['code'] ?? '')));
            if (!preg_match('/^[A-Z0-9]{4,12}$/', $code)) { sendJson(['ok' => false, 'error' => 'Invalid session code.'], 400); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            $liveIp = $_SERVER['REMOTE_ADDR'] ?? '';

            /* Join is infrequent (once per follower) but a whole congregation
               joins over a minute or two behind ONE church-wifi NAT IP, so the
               per-IP cap is generous (120/60s). It still blunts cheap code
               enumeration: the access control remains the session CODE, and a
               minted follow token only buckets the per-token poll rate limiter
               below (it is NOT an authorisation grant). NAT-safe model mirrors
               service_join/service_poll (rule #26 / #1377). Unchanged by
               #1770 C3 — this is still the pre-token, correct rate-limit
               class (I2). */
            checkRateLimit('live_follow_join', $liveIp, 120, 60, true);
            recordRateLimitHit('live_follow_join', $liveIp);

            /* #1770 C3 — ADDITIVE POST mode (req #3/#6): a POST body carrying
               a valid presenceDeviceId opts a follower into a
               tblServicePresence row (below), which is what lets them ride
               the session host's CCLI licence via
               serviceMode_presenceCcliNumber()'s new host branch. Validated
               EXACTLY like service_join's own presenceDeviceId handling
               (api.php's `service_join` case). A GET request — every
               existing client, forever, until the #1770 C5+ client ships —
               never enters this branch, so the resolve query and response
               below stay byte-identical for it. */
            $isPresenceJoin = ($_SERVER['REQUEST_METHOD'] === 'POST');
            $presenceDeviceId = '';
            if ($isPresenceJoin) {
                $joinBody = json_decode(file_get_contents('php://input'), true);
                if (!is_array($joinBody)) { $joinBody = []; }
                $presenceDeviceId = preg_replace('/[^A-Za-z0-9\-]/', '', (string)($joinBody['presenceDeviceId'] ?? ''));
                $presenceDeviceId = mb_substr($presenceDeviceId, 0, 64);
            }

            $db = getDbMysqli();
            /* #1405 side-finding fix (rule #26) — Channel filter added so an
               alpha/beta-created session is never joinable on production
               against the shared DB (a host session now stamps Channel at
               live_follow_create). #1386 */
            $channel = serviceMode_channel();
            /* #1792 — the JOIN gate is now "is the session still ALIVE?", NOT
               "did the host beat within 180s". A Quick join code is FIXED, so
               (Kahoot/Mentimeter) it stays joinable for as long as the session
               lives; serviceMode_liveFollowAliveSql() returns the idle-window
               predicate on a migrated install (the configurable idle-auto-close
               is the "session over" boundary — a backgrounded host phone no
               longer locks followers out) and falls back to the 180s
               heartbeat window only when #1770's idle machinery isn't migrated.
               #1770 C2 anti-probe: an idle-expired session stops resolving here
               too — the same 404 path below covers "not found"/"expired"/idle,
               so an idle-closed host is indistinguishable from an ended one (I6).
               #1770 C3 — s.ExpiresAt added to the SELECT becomes the minted
               presence row's own ExpiresAt below (service_join's `$m['ExpiresAt']`
               read); unused by the pre-existing response fields. */
            $aliveSql = serviceMode_liveFollowAliveSql($db, 's');
            $stmt = $db->prepare(
                'SELECT s.Id, s.CurrentSongId, s.CurrentComponentIndex, s.StateJson, s.StateRevision, s.ExpiresAt,
                        u.DisplayName AS HostName
                   FROM tblLiveFollowSessions s
                   JOIN tblUsers u ON u.Id = s.HostUserId
                  WHERE s.SessionCode = ? AND s.Channel = ? AND s.IsActive = 1
                    ' . $aliveSql
            );
            $stmt->bind_param('ss', $code, $channel);
            $stmt->execute();
            $row = $stmt->get_result()->fetch_assoc();
            $stmt->close();

            /* Identical message for missing / expired / wrong code so liveness
               can't be probed cheaply (combined with the rate limit). */
            if (!$row) {
                /* #1792 — before the deliberately-opaque generic message, check
                   whether this well-formed code is live on ANOTHER channel: the
                   "host on my laptop's dev URL, join on my phone's live PWA"
                   test is exactly this cross-channel case, and the generic
                   "not found" made it read as broken. The hint fires ONLY for a
                   code the caller already holds validly elsewhere, so it does
                   NOT re-open the anti-probe leak (see the helper's doc-block).
                   The per-IP join budget was already spent unconditionally
                   above (recordRateLimitHit), so this adds no free oracle. */
                if (serviceMode_codeOnOtherChannel($db, $code, $channel)) {
                    logActivity('live.session.join', 'live_session', '', ['reason' => 'wrong_channel'], 'failure');
                    sendJson(['ok' => false, 'error' => SERVICE_MODE_WRONG_CHANNEL_MESSAGE], 404); break;
                }
                /* §3.2 breadcrumb — no numeric id to log (nothing matched); the
                   reason is generic on purpose (never the code, never "wrong
                   code" vs "expired" — that would re-open the anti-probe leak). */
                logActivity('live.session.join', 'live_session', '', ['reason' => 'not_found_or_stale'], 'failure');
                sendJson(['ok' => false, 'error' => 'Session not found or ended.'], 404); break;
            }

            /* Mint a per-follower token (16 random bytes → 32 hex chars). It is
               STATELESS — nothing is persisted server-side; it exists purely so
               the poll endpoint can bucket the rate limiter per follower instead
               of per shared NAT IP. The session CODE stays the access control. */
            $followToken = bin2hex(random_bytes(16));

            /* #1770 C3 — mint (or re-activate, on a re-join) the presence
               row ONLY when the caller opted in with a valid device id AND
               the presence table exists (table-existence-gated — see
               serviceMode_presenceTableExists()'s doc-block). Best-effort:
               a presence-mint failure must never fail an otherwise-valid
               join, so it is wrapped and simply leaves $presenceToken null
               (the response then looks exactly like a pre-#1770-C3 GET
               join). Upserts on the SAME `uq_DeviceSession (SessionId,
               PresenceDeviceId)` shape service_join already uses, and
               (like service_join) stamps `OrgId/VenueId/ScheduleId/
               OccurrenceDate` as their column DEFAULT NULL — a Quick
               session simply has none of those. */
            $presenceToken = null;
            if ($isPresenceJoin && $presenceDeviceId !== '' && serviceMode_presenceTableExists($db)) {
                try {
                    $sessionId    = (int)$row['Id'];
                    $expiresAt    = (string)($row['ExpiresAt'] ?? '');
                    $mintedToken  = rtrim(strtr(base64_encode(random_bytes(32)), '+/', '-_'), '=');
                    if (serviceMode_presenceRoleColumnExists($db)) {
                        $pIns = $db->prepare(
                            "INSERT INTO tblServicePresence
                                (SessionId, Channel, PresenceDeviceId, PresenceToken, Role, JoinedAt, LastSeenAt, ExpiresAt, IsActive)
                             VALUES (?, ?, ?, ?, 'congregant', UTC_TIMESTAMP(), UTC_TIMESTAMP(), ?, 1)
                             ON DUPLICATE KEY UPDATE PresenceToken = VALUES(PresenceToken), Role = VALUES(Role),
                                 LastSeenAt = UTC_TIMESTAMP(), ExpiresAt = VALUES(ExpiresAt), IsActive = 1"
                        );
                    } else {
                        $pIns = $db->prepare(
                            "INSERT INTO tblServicePresence
                                (SessionId, Channel, PresenceDeviceId, PresenceToken, JoinedAt, LastSeenAt, ExpiresAt, IsActive)
                             VALUES (?, ?, ?, ?, UTC_TIMESTAMP(), UTC_TIMESTAMP(), ?, 1)
                             ON DUPLICATE KEY UPDATE PresenceToken = VALUES(PresenceToken),
                                 LastSeenAt = UTC_TIMESTAMP(), ExpiresAt = VALUES(ExpiresAt), IsActive = 1"
                        );
                    }
                    $pIns->bind_param('issss', $sessionId, $channel, $presenceDeviceId, $mintedToken, $expiresAt);
                    $pIns->execute();
                    $pIns->close();
                    $presenceToken = $mintedToken;
                } catch (\Throwable $_e) {
                    error_log('[live_follow_join/presence] ' . $_e->getMessage());
                    $presenceToken = null;
                }
            }

            logActivity('live.session.join', 'live_session', (string)$row['Id'], ['has_presence' => $presenceToken !== null]);

            sendJson([
                'ok'              => true,
                'code'            => $code,
                'followToken'     => $followToken,
                /* #1770 C3 — additive; null unless this was an opted-in POST
                   join AND the presence table exists. A client that never
                   reads this key (every client before #1770 C5) is
                   unaffected — the `followToken` back-compat-by-absence
                   precedent (live-follow.js:266-270). */
                'presenceToken'   => $presenceToken,
                'hostDisplayName' => (string)($row['HostName'] ?? ''),
                'currentSongId'   => $row['CurrentSongId'],
                'componentIndex'  => $row['CurrentComponentIndex'] !== null ? (int)$row['CurrentComponentIndex'] : null,
                'state'           => $row['StateJson'] !== null ? json_decode($row['StateJson'], true) : null,
                'revision'        => (int)$row['StateRevision'],
            ]);
            break;
        }

        case 'live_follow_poll': {
            $code = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($_GET['code'] ?? '')));
            if (!preg_match('/^[A-Z0-9]{4,12}$/', $code)) { sendJson(['active' => false], 400); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            $since = (int)($_GET['since'] ?? 0);
            $liveIp = $_SERVER['REMOTE_ADDR'] ?? '';

            /* NAT-safe rate limiting (#1377, mirrors service_poll / rule #26).
               A congregation in one building shares ONE public IP (church-wifi
               NAT) and each follower polls every ~2.5s, so a per-IP cap throttles
               the whole room. When the client sends the per-follower token minted
               at join, bucket PER TOKEN ('tok:<token>', generous 40/60s for ~2.5s
               polling) so each device gets its own budget and one bad token can't
               DoS the rest. Fall back to the per-IP cap ONLY when the token is
               absent (an old client) — the IP path keeps `poll` from being an
               un-throttled code-existence oracle for those legacy callers. */
            $liveTok = preg_replace('/[^a-f0-9]/', '', substr((string)($_GET['token'] ?? ''), 0, 40));
            if ($liveTok !== '') {
                /* #1492 — bucket on a HASH of the follow token, never the raw
                   token (which would persist into tblLoginAttempts.IpAddress).
                   Mirrors service_poll's presence-token bucket. */
                $liveBucket = 'tok:' . substr(hash('sha256', $liveTok), 0, 24);
                checkRateLimit('live_follow_poll', $liveBucket, 40, 60, true);
                recordRateLimitHit('live_follow_poll', $liveBucket);
            } else {
                checkRateLimit('live_follow_poll', $liveIp, 600, 60, true);
                recordRateLimitHit('live_follow_poll', $liveIp);
            }
            $db = getDbMysqli();
            /* #1405 side-finding fix (rule #26) — Channel filter, mirrors join. */
            $channel = serviceMode_channel();
            /* #1792 — Fresh follows the SAME "alive, not just recently-beaten"
               rule as the join (serviceMode_liveFollowAliveSql): a follower
               keeps polling successfully for as long as the session lives, so a
               backgrounded host phone doesn't flip everyone to active:false.
               The fragment opens with " AND (…" and nests inside Fresh's own
               parens: `(IsActive = 1 AND (IdleTimeoutMins IS NULL OR …))` when
               migrated, `(IsActive = 1 AND LastHeartbeatAt > 180s)` when not.
               The bare table name IS the alias here (no alias in this query). */
            $aliveSql = serviceMode_liveFollowAliveSql($db, 'tblLiveFollowSessions');
            $stmt = $db->prepare(
                'SELECT CurrentSongId, CurrentComponentIndex, StateJson, StateRevision,
                        (IsActive = 1' . $aliveSql . ') AS Fresh
                   FROM tblLiveFollowSessions
                  WHERE SessionCode = ? AND Channel = ?'
            );
            $stmt->bind_param('ss', $code, $channel);
            $stmt->execute();
            $row = $stmt->get_result()->fetch_assoc();
            $stmt->close();

            if (!$row || (int)$row['Fresh'] !== 1) { sendJson(['active' => false]); break; }

            $rev = (int)$row['StateRevision'];
            if ($rev <= $since) { sendJson(['changed' => false, 'revision' => $rev]); break; }

            sendJson([
                'changed'        => true,
                'currentSongId'  => $row['CurrentSongId'],
                'componentIndex' => $row['CurrentComponentIndex'] !== null ? (int)$row['CurrentComponentIndex'] : null,
                'state'          => $row['StateJson'] !== null ? json_decode($row['StateJson'], true) : null,
                'revision'       => $rev,
            ]);
            break;
        }

        /* =================================================================
         * SERVICE MODE (#1335) — operator endpoints (Phase 2b).
         * A venue/service session congregants join via a rotating code (2c)
         * + (Phase 3) get a temporary presence-scoped CCLI unlock. Operator =
         * global_admin/admin OR an org-admin/owner of the venue's org. Every
         * row is CHANNEL-scoped (the 3-docroot guard) so an alpha/beta session
         * is never joinable on production. State-changing POSTs inherit the
         * X-Requested-With CSRF guard at the top of this file.
         * ================================================================= */
        case 'service_session_start': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'entitlements.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'live_activity_push.php';
            $userId = (int)$authUser['Id'];
            $role   = (string)($authUser['Role'] ?? '');
            $svcIp  = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_session_start', $svcIp, 30, 3600, true, $userId);
            recordRateLimitHit('service_session_start', rateLimitKey($svcIp, $userId));

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }
            $venueId    = (int)($body['venueId'] ?? 0);
            $scheduleId = (int)($body['scheduleId'] ?? 0);
            $occDate    = (string)($body['occurrenceDate'] ?? '');
            if ($venueId <= 0) { sendJson(['error' => 'Missing venue.'], 400); break; }
            if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $occDate)) { sendJson(['error' => 'Invalid occurrence date.'], 400); break; }

            $db = getDbMysqli();
            $channel = serviceMode_channel();

            $vstmt = $db->prepare('SELECT OrgId, TimeZone FROM tblOrgVenues WHERE Id = ? AND IsActive = 1');
            $vstmt->bind_param('i', $venueId);
            $vstmt->execute();
            $venue = $vstmt->get_result()->fetch_assoc();
            $vstmt->close();
            if (!$venue) { sendJson(['error' => 'Unknown venue.'], 404); break; }
            $orgId   = (int)$venue['OrgId'];
            $venueTz = (string)($venue['TimeZone'] ?? 'UTC');

            $canOperate = ($role === 'global_admin' || $role === 'admin')
                || in_array($orgId, userIsOrgAdminOf($userId), true);
            if (!$canOperate) {
                logActivity('service.session.start', 'organisation', (string)$orgId, ['reason' => 'not_authorised', 'venue_id' => $venueId], 'failure');
                sendJson(['error' => 'Not authorised for this organisation.'], 403); break;
            }

            /* Schedule (if given) must belong to the venue → start/duration/tz.
               No schedule selected (scheduleId <= 0) is the AD-HOC path: the
               10:00/90-minute values below are a placeholder, not a real
               chosen time (#1576 — see serviceMode_occurrenceEndUtc()'s
               doc-block for why that matters to the end-time floor). */
            $startTime = '10:00:00'; $duration = 90; $schedTz = $venueTz; $scheduleIdN = null;
            $isAdHoc = true;
            if ($scheduleId > 0) {
                $sstmt = $db->prepare('SELECT StartTime, DurationMins, TimeZone FROM tblOrgServiceSchedules WHERE Id = ? AND VenueId = ?');
                $sstmt->bind_param('ii', $scheduleId, $venueId);
                $sstmt->execute();
                $sched = $sstmt->get_result()->fetch_assoc();
                $sstmt->close();
                if (!$sched) { sendJson(['error' => 'Unknown schedule for this venue.'], 404); break; }
                $startTime   = (string)$sched['StartTime'];
                $duration    = (int)$sched['DurationMins'];
                $schedTz     = ($sched['TimeZone'] ?? '') ?: $venueTz;
                $scheduleIdN = $scheduleId;
                $isAdHoc     = false;
            }
            /* #1576 — $isAdHoc floors the result so an ad-hoc evening start
               is never born already-expired; an explicit schedule stays honest. */
            $endUtc = serviceMode_occurrenceEndUtc($occDate, $startTime, $duration, $schedTz, $isAdHoc);

            /* #1429 — capture the OLD session's Id BEFORE deactivating (same
               rationale as live_follow_create's supersede, above) so its
               Live Activity is told the broadcast ended rather than left
               stuck "live". */
            $oldSel = $db->prepare(
                "SELECT Id FROM tblLiveFollowSessions
                  WHERE SessionKind = 'service' AND IsActive = 1 AND Channel = ?
                    AND VenueId = ? AND OccurrenceDate = ? AND (ScheduleId <=> ?)"
            );
            $oldSel->bind_param('sisi', $channel, $venueId, $occDate, $scheduleIdN);
            $oldSel->execute();
            $oldRow = $oldSel->get_result()->fetch_assoc();
            $oldSel->close();

            /* Supersede any prior active service session for the same occurrence + channel. */
            $deact = $db->prepare(
                "UPDATE tblLiveFollowSessions SET IsActive = 0
                  WHERE SessionKind = 'service' AND IsActive = 1 AND Channel = ?
                    AND VenueId = ? AND OccurrenceDate = ? AND (ScheduleId <=> ?)"
            );
            $deact->bind_param('sisi', $channel, $venueId, $occDate, $scheduleIdN);
            $deact->execute();
            $superseded = $deact->affected_rows > 0;
            $deact->close();
            if ($oldRow) {
                liveActivitySessionPush($db, (int)$oldRow['Id'], 'end');
                /* #1621 — a superseded session must not keep holding its join
                   codes' slots in the global uq_ActiveCode index. Retire them
                   (a Status transition to 'expired'; the rows are KEPT — see
                   serviceMode_retireSessionCodes()) as the symmetric partner of
                   the same call in service_session_end below. Without it,
                   restarting a service silently burns a code every time.
                   Anything this misses — the theoretical case where the
                   supersede UPDATE deactivated more than the one session
                   captured above — is picked up by the opportunistic expiry
                   retirement inside serviceMode_mintCode() within one rotation
                   window. */
                serviceMode_retireSessionCodes($db, (int)$oldRow['Id'], $channel);
            }

            /* Insert the session (SessionKind=service; SessionCode is the spine's
               required unique id, internal — congregants use the rotating codes).
               ExpiresAt = the resolved-UTC occurrence end. Retry on uq_Code. */
            $newSessionId = 0;
            $ins = $db->prepare(
                "INSERT INTO tblLiveFollowSessions
                    (SessionCode, HostUserId, OrgId, VenueId, ScheduleId, OccurrenceDate,
                     SessionKind, Channel, IsActive, StartedAt, LastHeartbeatAt, ExpiresAt, StateRevision)
                 VALUES (?, ?, ?, ?, ?, ?, 'service', ?, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP(), ?, 0)"
            );
            $sessionCode = '';
            $ins->bind_param('siiiisss', $sessionCode, $userId, $orgId, $venueId, $scheduleIdN, $occDate, $channel, $endUtc);
            for ($attempt = 0; $attempt < 6 && $newSessionId === 0; $attempt++) {
                $sessionCode = 'SVC' . serviceMode_generateCode(8);
                try {
                    $ins->execute();
                    $newSessionId = (int)$db->insert_id;
                } catch (\mysqli_sql_exception $e) {
                    if ($e->getCode() !== 1062) { throw $e; }
                }
            }
            $ins->close();
            if ($newSessionId === 0) { sendJson(['error' => 'Could not start the session, please retry.'], 503); break; }

            $code = serviceMode_mintCode($db, $newSessionId);
            logActivity('service.session.start', 'organisation', (string)$orgId, [
                'session_id'       => $newSessionId,
                'venue_id'         => $venueId,
                'channel'          => $channel,
                'schedule_id'      => $scheduleIdN,
                'occurrence_date'  => $occDate,
                'superseded'       => $superseded,
            ]);
            /* #1909 — partner webhook (dormant no-op). NEVER the join code — the
               venue rotating code IS proof-of-presence (rule #26). */
            webhookEmit('service.started', [
                'session_kind'    => 'service',
                'org_id'          => $orgId,
                'venue_id'        => $venueId,
                'occurrence_date' => $occDate,
            ], ['source' => 'api', 'entity_id' => (string)$newSessionId]);
            sendJson(['ok' => true, 'sessionId' => $newSessionId, 'code' => $code, 'occurrenceEnd' => $endUtc]);
            break;
        }

        case 'service_code_rotate':
        case 'service_code_current':
        case 'service_session_end': {
            $isRotate  = ($action === 'service_code_rotate');
            $isEnd     = ($action === 'service_session_end');
            $isCurrent = ($action === 'service_code_current');
            if (($isRotate || $isEnd) && $_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'entitlements.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'live_activity_push.php';
            $userId = (int)$authUser['Id'];
            $role   = (string)($authUser['Role'] ?? '');
            $svcIp  = $_SERVER['REMOTE_ADDR'] ?? '';
            /* #1636 — paired writer. $userId is always set (authenticated
               above), so rateLimitKey() resolves to 'user:<id>': this is a
               PER-OPERATOR budget, not per-IP, and two leaders sharing the
               church wifi cannot throttle each other. */
            checkRateLimit('service_operator', $svcIp, 600, 60, true, $userId);
            recordRateLimitHit('service_operator', rateLimitKey($svcIp, $userId));

            $sessionId = $isRotate || $isEnd
                ? (int)((json_decode(file_get_contents('php://input'), true) ?: [])['sessionId'] ?? 0)
                : (int)($_GET['sessionId'] ?? 0);
            if ($sessionId <= 0) { sendJson(['error' => 'Missing session.'], 400); break; }

            $db = getDbMysqli();
            $channel = serviceMode_channel();
            /* Resolve the session (channel-scoped) + gate on operator. */
            $sstmt = $db->prepare("SELECT OrgId, HostUserId, IsActive FROM tblLiveFollowSessions WHERE Id = ? AND SessionKind = 'service' AND Channel = ?");
            $sstmt->bind_param('is', $sessionId, $channel);
            $sstmt->execute();
            $sess = $sstmt->get_result()->fetch_assoc();
            $sstmt->close();
            if (!$sess) {
                /* §3.2 breadcrumb — failures only for rotate/current (the
                   service_session_end 404 is unchanged, no entry requested).
                   OrgId is unresolved (no matching session), so entityId is
                   empty — the reason + session_id are the useful signal. */
                if ($isRotate || $isCurrent) {
                    logActivity(
                        $isRotate ? 'service.code.rotate' : 'service.code.current',
                        'organisation', '', ['session_id' => $sessionId, 'reason' => 'unknown_session'], 'failure'
                    );
                }
                sendJson(['error' => 'Unknown session.'], 404); break;
            }
            $orgId = (int)$sess['OrgId'];
            $canOperate = ($role === 'global_admin' || $role === 'admin')
                || (int)$sess['HostUserId'] === $userId
                || in_array($orgId, userIsOrgAdminOf($userId), true);
            if (!$canOperate) {
                if ($isRotate || $isCurrent) {
                    logActivity(
                        $isRotate ? 'service.code.rotate' : 'service.code.current',
                        'organisation', (string)$orgId, ['session_id' => $sessionId, 'reason' => 'not_authorised'], 'failure'
                    );
                }
                sendJson(['error' => 'Not authorised.'], 403); break;
            }

            if ($isEnd) {
                $db->begin_transaction();
                try {
                    $e1 = $db->prepare('UPDATE tblLiveFollowSessions SET IsActive = 0 WHERE Id = ?');
                    $e1->bind_param('i', $sessionId); $e1->execute(); $e1->close();
                    /* Revoke all presence → immediate gate revocation. */
                    $e2 = $db->prepare('UPDATE tblServicePresence SET IsActive = 0 WHERE SessionId = ?');
                    $e2->bind_param('i', $sessionId); $e2->execute(); $e2->close();
                    /* #1621 — retire this session's join codes IN THE SAME
                       TRANSACTION, so a half-ended session can never strand a
                       live code. Before this, ending a service left its
                       'current' (+ 'previous') rows at a LIVE Status forever:
                       harmless while uq_Session_Code was session-scoped, but
                       with the global uq_ActiveCode slot it means every ended
                       service permanently holds a code and the unique index
                       grows with cumulative history rather than with concurrent
                       services. Status transition only — the rows are KEPT for
                       audit ('expired' records WHY the code died: the service
                       ended, as opposed to 'superseded' = it rotated). */
                    serviceMode_retireSessionCodes($db, $sessionId, $channel);
                    $db->commit();
                } catch (\Throwable $e) { $db->rollback(); throw $e; }
                logActivity('service.session.end', 'organisation', (string)$orgId, ['session_id' => $sessionId]);
                /* #1909 — partner webhook (dormant no-op). Operator-initiated end. */
                webhookEmit('service.ended', [
                    'session_kind' => 'service',
                    'org_id'       => $orgId,
                    'ended_reason' => 'operator',
                ], ['source' => 'api', 'entity_id' => (string)$sessionId]);
                liveActivitySessionPush($db, $sessionId, 'end');
                sendJson(['ok' => true]);
                break;
            }

            if ($isRotate) {
                if ((int)$sess['IsActive'] !== 1) {
                    logActivity('service.code.rotate', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'reason' => 'session_not_active'], 'failure');
                    sendJson(['error' => 'Session is not active.'], 409); break;
                }
                /* The rotate doubles as a heartbeat keeping the session fresh. */
                $hb = $db->prepare('UPDATE tblLiveFollowSessions SET LastHeartbeatAt = UTC_TIMESTAMP() WHERE Id = ?');
                $hb->bind_param('i', $sessionId); $hb->execute(); $hb->close();
                $code = serviceMode_mintCode($db, $sessionId);
                sendJson(['ok' => true, 'code' => $code]);
                break;
            }

            /* service_code_current — projection/leader resume after a reload OR the
               visibility/focus wake refresh. Heartbeat here too (#1386 wake-
               alignment): the read used to be heartbeat-free, so a backgrounded
               broadcaster tab that wakes did NOT revive the session until the next
               30s rotate — leaving a gap where joins/polls saw it stale. Mirrors
               live-follow.js's wake-beat. Operator-gated + active-only, so only a
               genuine open operator tab can keep a session alive. */
            if ((int)$sess['IsActive'] === 1) {
                $hbc = $db->prepare('UPDATE tblLiveFollowSessions SET LastHeartbeatAt = UTC_TIMESTAMP() WHERE Id = ?');
                $hbc->bind_param('i', $sessionId);
                $hbc->execute();
                $hbc->close();
            }
            $cur = $db->prepare("SELECT Code FROM tblLiveFollowJoinCodes WHERE SessionId = ? AND Status = 'current' AND ExpiresAt > UTC_TIMESTAMP() ORDER BY Generation DESC LIMIT 1");
            $cur->bind_param('i', $sessionId);
            $cur->execute();
            $row = $cur->get_result()->fetch_assoc();
            $cur->close();
            if (!$row) {
                /* Current expired (e.g. tab slept) — mint a fresh one if the session's still active. */
                if ((int)$sess['IsActive'] === 1) {
                    $code = serviceMode_mintCode($db, $sessionId);
                    sendJson(['ok' => true, 'code' => $code]);
                } else {
                    logActivity('service.code.current', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'reason' => 'session_not_active'], 'failure');
                    sendJson(['ok' => false, 'error' => 'Session not active.'], 409);
                }
                break;
            }
            sendJson(['ok' => true, 'code' => (string)$row['Code']]);
            break;
        }

        /* -----------------------------------------------------------------
         * SERVICE MODE (#1335) — broadcast (operator) + congregant join/poll/
         * leave (Phase 2c). The broadcast endpoint serves BOTH broadcaster
         * mechanisms (the projection laptop OR a separate leader device) — it
         * just needs the sessionId + operator auth. Congregant endpoints are
         * anonymous, gated by the unguessable rotating code (join) / opaque
         * presence token (poll/leave), CHANNEL-scoped, NAT-safe per-token.
         * ----------------------------------------------------------------- */
        case 'service_broadcast': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'entitlements.php';
            /* #1408 — session_control_token.php supplies BOTH the shared
               serviceMode_userCanOperate() check AND the control-token
               validator the new delegated-auth path below consults. */
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'session_control_token.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'live_activity_push.php';

            /* #1408 — EARLY per-IP throttle, DISTINCT bucket from the
               per-user one below. Before this change, an unauthenticated
               caller 401'd immediately (no DB query at all); now the
               control-token path means auth can't be resolved until AFTER
               the session row is read, so an anonymous/probing caller could
               otherwise trigger unlimited session-lookup queries with zero
               credentials at all. Generously sized (mirrors service_join's
               own anonymous-safe per-IP cap) so it never bites a real
               operator or delegated device. */
            /* #1636 — paired writer. Per-IP is CORRECT here and not a rule
               #26 violation: this bucket exists precisely to cap the
               ANONYMOUS, pre-auth session lookups an unidentified caller can
               trigger, so there is no user and no presence token to key on
               yet. It is a broadcaster-side endpoint (operators/leader
               devices), never a congregant path, and 300/min is far above
               any real broadcaster — a congregation following along hits
               service_poll, which is keyed per presence token. */
            $svcProbeIp = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_broadcast_probe', $svcProbeIp, 300, 60, true, null);
            recordRateLimitHit('service_broadcast_probe', $svcProbeIp);

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }
            $sessionId = (int)($body['sessionId'] ?? 0);
            if ($sessionId <= 0) { sendJson(['error' => 'Missing session.'], 400); break; }
            $songId = isset($body['songId']) ? _liveFollowCleanSongId((string)$body['songId']) : null;
            if ($songId === '') { $songId = null; }
            $componentIndex = (isset($body['componentIndex']) && $body['componentIndex'] !== null)
                ? min(9999, max(0, (int)$body['componentIndex'])) : null;
            $stateJson = serviceMode_cleanState($body['state'] ?? null);

            $db = getDbMysqli();
            $channel = serviceMode_channel();
            /* CurrentSongId added to the SELECT (§3.2) so a genuine song change
               can be detected below without a second round-trip. */
            $sstmt = $db->prepare("SELECT OrgId, HostUserId, CurrentSongId FROM tblLiveFollowSessions WHERE Id = ? AND SessionKind = 'service' AND Channel = ? AND IsActive = 1");
            $sstmt->bind_param('is', $sessionId, $channel);
            $sstmt->execute();
            $sess = $sstmt->get_result()->fetch_assoc();
            $sstmt->close();
            if (!$sess) {
                /* OrgId is unresolved (no matching session) — entityId empty. */
                logActivity('service.broadcast.song', 'organisation', '', ['session_id' => $sessionId, 'reason' => 'unknown_or_ended'], 'failure');
                sendJson(['error' => 'Unknown or ended session.'], 404); break;
            }
            $orgId = (int)$sess['OrgId'];

            /* #1408 — TWO ways to authorise a broadcast: the operator's own
               bearer (unchanged, existing behaviour, tried FIRST and
               authoritative when it resolves) OR a scoped, revocable
               control token presented in the body (a delegated co-leader's
               device that never signed in at all). The token path is only
               even consulted when there is no authorised bearer, so an
               operator's own request is never weakened by this addition. */
            $authUser = getAuthenticatedUser();
            $userId = null;
            $canOperate = false;
            if ($authUser) {
                $userId = (int)$authUser['Id'];
                $role   = (string)($authUser['Role'] ?? '');
                $canOperate = serviceMode_userCanOperate($userId, $role, $orgId, (int)$sess['HostUserId']);
            }
            $viaControlToken = false;
            if (!$canOperate) {
                $controlToken = is_string($body['controlToken'] ?? null) ? $body['controlToken'] : '';
                if ($controlToken !== '' && sessionControlTokensTableExists($db)
                    && sessionControlToken_validate($db, $controlToken, $sessionId, $channel)) {
                    $canOperate = true;
                    $viaControlToken = true;
                }
            }

            /* #1636 — paired writer. NOTE $userId is genuinely NULLABLE here:
               the #1408 delegated control-token path authorises a device that
               never signed in, so rateLimitKey() falls back to the IP for
               those callers and resolves to 'user:<id>' for a bearer
               operator. That fallback is exactly why the key must come from
               the shared helper — hand-writing `'user:' . $userId` would file
               rows under the literal key 'user:' while the check counted the
               IP bucket, re-creating #1636's never-trips bug on the very
               endpoint being fixed. Broadcasts are operator actions (a handful
               per service), so 600/min never bites a real leader even when the
               whole team shares one IP. */
            $svcBroadcastIp = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_broadcast', $svcBroadcastIp, 600, 60, true, $userId);
            recordRateLimitHit('service_broadcast', rateLimitKey($svcBroadcastIp, $userId));

            if (!$canOperate) {
                logActivity('service.broadcast.song', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'reason' => 'not_authorised'], 'failure');
                sendJson(['error' => 'Not authorised.'], 403); break;
            }

            if ($songId !== null) {
                /* #1694 — filtered: a hidden song cannot be NEWLY broadcast.
                   #1765 — same for a song whose songbook has been disabled. */
                $chk = $db->prepare('SELECT 1 FROM tblSongs WHERE SongId = ? AND ' . songVisibleSql($db, '') . ' AND ' . songServableSql($db, '') . ' LIMIT 1');
                $chk->bind_param('s', $songId);
                $chk->execute();
                $ok = $chk->get_result()->fetch_row() !== null;
                $chk->close();
                if (!$ok) {
                    logActivity('service.broadcast.song', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'reason' => 'unknown_song'], 'failure');
                    sendJson(['error' => 'Unknown song.'], 400); break;
                }
            }

            /* #1770 C4 — the UPDATE + revision re-read + Live Activity push
               is now the ONE shared core, serviceMode_applyBroadcast()
               (includes/service_mode.php), so `service_drive` (below) writes
               through the exact same path rather than a second copy (rule
               #26 I4 / plan guard G4). Fixture-diffed byte-identical: same
               SQL text, same statement order, same LastHeartbeatAt touch. */
            /* #1897 W2 — usage context for the projected-usage log inside the
               core. $userId is nullable (the #1408 control-token path); 'via'
               is the same fixed 'bearer'|'control_token' vocabulary the
               breadcrumb below uses. */
            $revision = serviceMode_applyBroadcast($db, $sessionId, $songId, $componentIndex, $stateJson, [
                'userId' => $userId,
                'via'    => $viaControlToken ? 'control_token' : 'bearer',
            ]);

            /* §3.2 — song-change only, never on a component-index-only nudge.
               'via' (#1408) is a fixed 'bearer'|'control_token' string —
               never sensitive, useful adoption signal for the new
               delegated-auth path. */
            if ($songId !== null && (string)($sess['CurrentSongId'] ?? '') !== (string)$songId) {
                logActivity('service.broadcast.song', 'organisation', (string)$orgId, [
                    'session_id' => $sessionId,
                    'song_id'    => $songId,
                    'channel'    => $channel,
                    'via'        => $viaControlToken ? 'control_token' : 'bearer',
                ]);
            }

            sendJson(['ok' => true, 'revision' => $revision]);
            break;
        }

        case 'service_join': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            $svcIp = $_SERVER['REMOTE_ADDR'] ?? '';
            /* Generous per-IP cap — a whole congregation joins at once behind one
               church-wifi IP, so this is high; the real throttle is the per-device
               presence row + the rotating code's air-gap.

               #1636 — THIS IS THE ANTI-PROBE CONTROL ON JOIN-CODE GUESSING, and
               it was doubly dead: nothing ever recorded a hit (so the counter was
               permanently 0) AND the verdict was discarded (autoRespond=false,
               return value unused), so it could not have refused anything even
               with a working counter. #1621 hardened the codes themselves on the
               assumption this throttle existed.

               KEY DECISION (rule #26 — presence limiting is per token, NEVER per
               IP). This one bucket CANNOT be keyed on a presence token: the token
               is MINTED BY THIS ENDPOINT, so a joining congregant has none yet.
               The only other client-supplied handle is presenceDeviceId, which the
               client mints itself — a code-guesser would simply roll a new one per
               request, so keying on it would give an anti-probe control of exactly
               zero value. Per-IP is therefore the only workable key here.

               What keeps that from locking out a NAT-shared congregation — the
               precise failure rule #26 forbids — is that ONLY FAILED JOINS are
               recorded (see the resolve-failure branch below). checkRateLimit()
               counts rows regardless of their Success flag, so recording nothing on
               the success path means a congregant who types the CORRECT code never
               consumes a single unit of budget, no matter how many of them share
               one church IP. The cap is thus, in effect, 300 FAILED joins per
               minute per IP: unreachable by legitimate use, while a brute-forcer
               (who produces nothing but failures) is throttled immediately.
               This mirrors auth_login_acct, which likewise records only in its
               shared unknown-user/wrong-password branch.

               Verdict is now USED rather than discarded — hence autoRespond stays
               false, so the refusal can carry the §3.2 breadcrumb this file
               requires instead of exiting silently inside the helper. */
            if (!checkRateLimit('service_join', $svcIp, 300, 60, false, null)) {
                logActivity('service.presence.join', 'organisation', '', ['reason' => 'rate_limited'], 'failure');
                sendJson(['ok' => false, 'error' => 'Too many join attempts from this network. Please wait a moment and try again.'], 429);
                break;
            }

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }
            $code   = strtoupper(preg_replace('/[^A-Za-z0-9]/', '', (string)($body['code'] ?? '')));
            $venueId = (int)($body['venueId'] ?? 0);  /* OPTIONAL — 0 = resolve by code+channel alone (congregant typed it off the screen). */
            $deviceId = preg_replace('/[^A-Za-z0-9\-]/', '', (string)($body['presenceDeviceId'] ?? ''));
            $deviceId = mb_substr($deviceId, 0, 64);
            /* #1406 — optional client-declared role (congregant | projector),
               fail-open to 'congregant' on anything unrecognised or absent. */
            $joinRole = serviceMode_cleanPresenceRole($body['role'] ?? null);
            if ($code === '' || $deviceId === '') { sendJson(['ok' => false, 'error' => 'Invalid join request.'], 400); break; }

            $db = getDbMysqli();
            $channel = serviceMode_channel();
            /* #1621 — $joinFailReason distinguishes 'code_not_active' from
               'ambiguous_code' for the SERVER-SIDE breadcrumb only; the
               user-facing message below is deliberately identical for both. */
            $joinFailReason = null;
            $sess = serviceMode_resolveJoin($db, $code, $venueId, $channel, $joinFailReason);
            if (!$sess) {
                /* Opaque — don't distinguish wrong/expired/unknown/ambiguous
                   (anti-probe; telling a prober "that code resolves twice" is
                   itself a signal). §3.2 breadcrumb: OrgId is unresolved, never
                   the code.
                   #1621 — the wording is the ROTATING-CODE mental model: the
                   venue screen shows a new code every ~30s, so "expired, look at
                   the screen" is both the truthful answer in the overwhelmingly
                   common case AND the right instruction in every other one,
                   including the ambiguity refusal (where guessing a winner could
                   have handed the congregant another organisation's service —
                   and, via serviceMode_presenceCcliNumber(), its CCLI unlock). */
                /* #1636 — the ONLY place service_join spends rate-limit budget.
                   A failed join is either a brute-force guess or a congregant
                   who was too slow for the ~30s code rotation; both are cheap
                   to absorb at 300/min, and a SUCCESSFUL join never records,
                   so an entire NAT-shared congregation joining correctly can
                   never exhaust the bucket (rule #26). Success=false marks the
                   row as a failure for audit; checkRateLimit() ignores the flag
                   and counts rows, which is what makes "budget only failures"
                   work at all. */
                recordRateLimitHit('service_join', $svcIp, false);
                /* #1792 — cross-channel hint, placed AFTER recordRateLimitHit so
                   a cross-channel probe spends rate-limit budget exactly like
                   any other failed join (no new free oracle). Fires only for a
                   code already live on another docroot — the wrong-web-address
                   case — never revealing a CURRENT-channel session's liveness
                   (anti-probe opacity preserved; see the helper's doc-block). */
                if (serviceMode_codeOnOtherChannel($db, $code, $channel)) {
                    logActivity('service.presence.join', 'organisation', '', ['reason' => 'wrong_channel', 'channel' => $channel], 'failure');
                    sendJson(['ok' => false, 'error' => SERVICE_MODE_WRONG_CHANNEL_MESSAGE], 404);
                    break;
                }
                logActivity('service.presence.join', 'organisation', '', ['reason' => $joinFailReason ?? 'code_not_active', 'channel' => $channel], 'failure');
                sendJson(['ok' => false, 'error' => 'That code has expired. Check the screen for the new code.'], 404);
                break;
            }
            $sessionId = (int)$sess['Id'];

            /* Resolve the session's ExpiresAt (the resolved-UTC occurrence end) +
               its current broadcast state for an immediate follow. */
            $meta = $db->prepare('SELECT ExpiresAt, CurrentSongId, CurrentComponentIndex, StateJson, StateRevision FROM tblLiveFollowSessions WHERE Id = ?');
            $meta->bind_param('i', $sessionId);
            $meta->execute();
            $m = $meta->get_result()->fetch_assoc();
            $meta->close();
            $expiresAt = (string)($m['ExpiresAt'] ?? '');

            /* Opaque presence token (base64url 32 bytes = 43 chars) — the gate key. */
            $token = rtrim(strtr(base64_encode(random_bytes(32)), '+/', '-_'), '=');
            $orgId = $sess['OrgId'] !== null ? (int)$sess['OrgId'] : null;
            $sVenueId = $sess['VenueId'] !== null ? (int)$sess['VenueId'] : null;
            $schedId = $sess['ScheduleId'] !== null ? (int)$sess['ScheduleId'] : null;
            $occDate = $sess['OccurrenceDate'] !== null ? (string)$sess['OccurrenceDate'] : null;

            /* Upsert presence: one row per (session, device); a re-join reactivates
               + re-tokens rather than duplicating (uq_DeviceSession). Role (#1406)
               is columnExists-gated so this stays dormant-safe pre-migration.
               NOTE — this also fixes a pre-existing bind_param type-string/
               variable-count mismatch in the no-Role branch ('iiiissssss' was
               10 chars for only 9 bound variables, which throws ArgumentCountError
               on PHP 8.1+ on every call; confirmed against a live mysqli
               connection during this change). */
            if (serviceMode_presenceRoleColumnExists($db)) {
                $ins = $db->prepare(
                    "INSERT INTO tblServicePresence
                        (SessionId, OrgId, VenueId, ScheduleId, OccurrenceDate, Channel,
                         PresenceDeviceId, PresenceToken, Role, JoinedAt, LastSeenAt, ExpiresAt, IsActive)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, UTC_TIMESTAMP(), UTC_TIMESTAMP(), ?, 1)
                     ON DUPLICATE KEY UPDATE PresenceToken = VALUES(PresenceToken), Role = VALUES(Role),
                         LastSeenAt = UTC_TIMESTAMP(), ExpiresAt = VALUES(ExpiresAt), IsActive = 1"
                );
                $ins->bind_param('iiiissssss', $sessionId, $orgId, $sVenueId, $schedId, $occDate, $channel, $deviceId, $token, $joinRole, $expiresAt);
            } else {
                $ins = $db->prepare(
                    "INSERT INTO tblServicePresence
                        (SessionId, OrgId, VenueId, ScheduleId, OccurrenceDate, Channel,
                         PresenceDeviceId, PresenceToken, JoinedAt, LastSeenAt, ExpiresAt, IsActive)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, UTC_TIMESTAMP(), UTC_TIMESTAMP(), ?, 1)
                     ON DUPLICATE KEY UPDATE PresenceToken = VALUES(PresenceToken),
                         LastSeenAt = UTC_TIMESTAMP(), ExpiresAt = VALUES(ExpiresAt), IsActive = 1"
                );
                $ins->bind_param('iiiisssss', $sessionId, $orgId, $sVenueId, $schedId, $occDate, $channel, $deviceId, $token, $expiresAt);
            }
            $ins->execute();
            $ins->close();

            /* §3.2 breadcrumb — never the presence device id, only ids/channel. */
            logActivity('service.presence.join', 'organisation', $orgId !== null ? (string)$orgId : '', ['session_id' => $sessionId, 'channel' => $channel]);

            sendJson([
                'ok' => true,
                'presenceToken' => $token,
                'pollIntervalMs' => serviceMode_pollIntervalMs($joinRole),
                'currentSongId' => $m['CurrentSongId'] ?? null,
                'componentIndex' => isset($m['CurrentComponentIndex']) ? (int)$m['CurrentComponentIndex'] : null,
                'state' => isset($m['StateJson']) && $m['StateJson'] !== null ? json_decode((string)$m['StateJson'], true) : null,
                'revision' => (int)($m['StateRevision'] ?? 0),
            ]);
            break;
        }

        case 'service_poll': {
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            $token = (string)($_GET['presenceToken'] ?? '');
            if (!preg_match('/^[A-Za-z0-9_\-]{43}$/', $token)) { sendJson(['active' => false]); break; }
            $since = max(0, (int)($_GET['since'] ?? 0));

            $db = getDbMysqli();

            /* #1406 — per-role poll budget: a projector polls near-1s cadence so
               the existing flat 40/min (sized for a ~2.5s congregant phone) would
               throttle it. Resolve the presence row's declared Role FIRST (cheap
               indexed lookup on the same uq_Token unique key the main query below
               also hits) so the rate-limit decision uses the right bucket size —
               columnExists-gated, fail-open 'congregant' pre-migration. Still
               PER PRESENCE TOKEN, never per-IP (rule #26 — a NAT-shared
               congregation is one IP). */
            $pollRole = serviceMode_presenceRole($db, $token);
            $pollMax  = ($pollRole === 'projector') ? 90 : 40;
            /* #1636 — was doubly dead (never recorded AND the verdict
               discarded via autoRespond=false + unused return). Now enforced.
               The key is UNCHANGED and already rule-#26 correct: 'tok:<hash>'
               is the PRESENCE TOKEN, so every congregant device has its own
               budget and a NAT-shared congregation is never throttled as one
               caller. autoRespond=true emits the standard 429; service-follow.js
               polls on a 2500ms setInterval behind a re-entrancy guard (24/min
               against a 40/min cap) and treats a 429 as a transient tick — it
               checks `d.active === false` explicitly, so the 429 body cannot be
               mistaken for "the service ended".
               VOLUME NOTE: checkRateLimit() writes one tblLoginAttempts row per
               request (the hazard api.php's health-probe comment documents).
               Rows here are self-limiting — once the cap trips, the check exits
               before the record — so the ceiling is $pollMax rows/min/device,
               retained 30 days by .sql/cleanup.php. Migrating high-frequency
               pollers onto the windowed tblReadRateLimit counter is the right
               long-term shape, but enforceReadRateLimit() resolves its own key
               from the bearer/cookie and congregants are ANONYMOUS, so it would
               silently fall back to per-IP — the exact rule #26 violation. It
               needs an explicit-key parameter first; tracked as follow-up. */
            $svcPollKey = 'tok:' . substr(hash('sha256', $token), 0, 24);
            checkRateLimit('service_poll', $svcPollKey, $pollMax, 60, true, null);
            recordRateLimitHit('service_poll', $svcPollKey);

            $channel = serviceMode_channel();
            /* Unified freshness window (was 120s — aligned to Live Follow's 180s,
               #1386). Trusted int constant, interpolated (not a bound value). */
            $freshness = (int) LIVE_SESSION_FRESHNESS_SECONDS;
            $stmt = $db->prepare(
                "SELECT s.CurrentSongId, s.CurrentComponentIndex, s.StateJson, s.StateRevision
                   FROM tblServicePresence p
                   JOIN tblLiveFollowSessions s ON s.Id = p.SessionId
                  WHERE p.PresenceToken = ? AND p.IsActive = 1 AND p.ExpiresAt > UTC_TIMESTAMP()
                    AND s.IsActive = 1 AND s.Channel = ?
                    AND s.LastHeartbeatAt > DATE_SUB(UTC_TIMESTAMP(), INTERVAL {$freshness} SECOND)
                  LIMIT 1"
            );
            $stmt->bind_param('ss', $token, $channel);
            $stmt->execute();
            $row = $stmt->get_result()->fetch_assoc();
            $stmt->close();
            if (!$row) { sendJson(['active' => false]); break; }

            /* Touch liveness (best-effort; not every poll needs it but cheap). */
            $touch = $db->prepare('UPDATE tblServicePresence SET LastSeenAt = UTC_TIMESTAMP() WHERE PresenceToken = ?');
            $touch->bind_param('s', $token);
            $touch->execute();
            $touch->close();

            $revision = (int)$row['StateRevision'];
            if ($revision <= $since) { sendJson(['active' => true, 'changed' => false, 'revision' => $revision]); break; }
            sendJson([
                'active' => true,
                'changed' => true,
                'currentSongId' => $row['CurrentSongId'] ?? null,
                'componentIndex' => isset($row['CurrentComponentIndex']) ? (int)$row['CurrentComponentIndex'] : null,
                'state' => isset($row['StateJson']) && $row['StateJson'] !== null ? json_decode((string)$row['StateJson'], true) : null,
                'revision' => $revision,
            ]);
            break;
        }

        case 'service_leave': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            $token = (string)(($body = json_decode(file_get_contents('php://input'), true)) && is_array($body) ? ($body['presenceToken'] ?? '') : '');
            if (!preg_match('/^[A-Za-z0-9_\-]{43}$/', $token)) { sendJson(['ok' => true]); break; }
            $db = getDbMysqli();

            /* §3.2 breadcrumb prep — resolve session/org/channel from the
               presence row BEFORE revoking; IDs only, never the token. */
            $leaveSel = $db->prepare('SELECT SessionId, OrgId, Channel FROM tblServicePresence WHERE PresenceToken = ?');
            $leaveSel->bind_param('s', $token);
            $leaveSel->execute();
            $leaveRow = $leaveSel->get_result()->fetch_assoc();
            $leaveSel->close();

            /* Immediate gate revocation. */
            $upd = $db->prepare('UPDATE tblServicePresence SET IsActive = 0 WHERE PresenceToken = ?');
            $upd->bind_param('s', $token);
            $upd->execute();
            $upd->close();

            if ($leaveRow) {
                $leaveOrgId = $leaveRow['OrgId'] !== null ? (string)(int)$leaveRow['OrgId'] : '';
                logActivity('service.presence.leave', 'organisation', $leaveOrgId, [
                    'session_id' => $leaveRow['SessionId'] !== null ? (int)$leaveRow['SessionId'] : null,
                    'channel'    => (string)($leaveRow['Channel'] ?? ''),
                ]);
            }

            sendJson(['ok' => true]);
            break;
        }

        /* -----------------------------------------------------------------
         * SESSION CONTROL TOKENS (#1408, Apple Phase-2 PR-9) — delegated
         * remote-control of ONE live/service session without sharing the
         * operator's login. `tblSessionControlTokens` shipped live-dormant
         * in #1511; every read/write below is
         * sessionControlTokensTableExists()-gated. `service_broadcast`
         * (above) is the ONE consumer of a minted token today.
         * ----------------------------------------------------------------- */
        case 'service_control_token_mint': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'manage' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'auth.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'session_control_token.php';

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            /* CSRF (rule #29) — belt-and-braces same as auth_device_code_
               approve / auth_provider_unlink: the global X-Requested-With
               gate (api.php top-of-file) already blocks a cross-site POST;
               this is a second, independent check on THIS state-changing,
               credential-minting endpoint. */
            $csrfToken = is_string($body['csrf_token'] ?? null) ? $body['csrf_token'] : null;
            if (!validateCsrfRequest($csrfToken)) {
                sendJson(['error' => 'Cross-origin request rejected.'], 403); break;
            }

            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            $userId = (int)$authUser['Id'];
            $role   = (string)($authUser['Role'] ?? '');

            $db = getDbMysqli();
            if (!sessionControlTokensTableExists($db)) {
                sendJson(['error' => 'Session control tokens are not available yet.'], 503); break;
            }

            /* #1636 — paired writer. Authenticated above, so the bucket is
               'user:<id>': a per-operator cap on minting delegated broadcast
               credentials, unaffected by how many leaders share an IP. */
            $svcMintIp = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_control_token_mint', $svcMintIp, 30, 3600, true, $userId);
            recordRateLimitHit('service_control_token_mint', rateLimitKey($svcMintIp, $userId));

            $sessionId = (int)($body['sessionId'] ?? 0);
            if ($sessionId <= 0) { sendJson(['error' => 'Missing session.'], 400); break; }

            $channel = serviceMode_channel();
            $sstmt = $db->prepare("SELECT OrgId, HostUserId, ExpiresAt FROM tblLiveFollowSessions WHERE Id = ? AND SessionKind = 'service' AND Channel = ? AND IsActive = 1");
            $sstmt->bind_param('is', $sessionId, $channel);
            $sstmt->execute();
            $sess = $sstmt->get_result()->fetch_assoc();
            $sstmt->close();
            if (!$sess) {
                logActivity('service.control_token.mint', 'organisation', '', ['session_id' => $sessionId, 'reason' => 'unknown_or_ended'], 'failure');
                sendJson(['error' => 'Unknown or ended session.'], 404); break;
            }
            $orgId = (int)$sess['OrgId'];
            if (!serviceMode_userCanOperate($userId, $role, $orgId, (int)$sess['HostUserId'])) {
                logActivity('service.control_token.mint', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'reason' => 'not_authorised'], 'failure');
                sendJson(['error' => 'Not authorised.'], 403); break;
            }

            $token = sessionControlToken_mint($db, $sessionId, $channel, (string)$sess['ExpiresAt']);
            if ($token === null) {
                sendJson(['error' => 'Could not mint a control token, please retry.'], 503); break;
            }

            /* §3.2 breadcrumb — IDs only, NEVER the raw token (this file's
               header discipline). */
            logActivity('service.control_token.mint', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'channel' => $channel]);

            sendJson([
                'ok'        => true,
                'token'     => $token,
                'scope'     => 'broadcast',
                'sessionId' => $sessionId,
            ]);
            break;
        }

        case 'service_control_token_revoke': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'manage' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'auth.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'session_control_token.php';

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            $csrfToken = is_string($body['csrf_token'] ?? null) ? $body['csrf_token'] : null;
            if (!validateCsrfRequest($csrfToken)) {
                sendJson(['error' => 'Cross-origin request rejected.'], 403); break;
            }

            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            $userId = (int)$authUser['Id'];
            $role   = (string)($authUser['Role'] ?? '');

            $db = getDbMysqli();
            if (!sessionControlTokensTableExists($db)) {
                sendJson(['error' => 'Session control tokens are not available yet.'], 503); break;
            }

            /* #1636 — paired writer; per-operator, as for the mint above. The
               cap is deliberately the more generous of the pair: revoking is
               the SAFE direction, and a leader must never be blocked from
               killing a delegated device mid-service. */
            $svcRevokeIp = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_control_token_revoke', $svcRevokeIp, 60, 3600, true, $userId);
            recordRateLimitHit('service_control_token_revoke', rateLimitKey($svcRevokeIp, $userId));

            $sessionId = (int)($body['sessionId'] ?? 0);
            if ($sessionId <= 0) { sendJson(['error' => 'Missing session.'], 400); break; }

            $channel = serviceMode_channel();
            $sstmt = $db->prepare("SELECT OrgId, HostUserId FROM tblLiveFollowSessions WHERE Id = ? AND SessionKind = 'service' AND Channel = ?");
            $sstmt->bind_param('is', $sessionId, $channel);
            $sstmt->execute();
            $sess = $sstmt->get_result()->fetch_assoc();
            $sstmt->close();
            if (!$sess) {
                logActivity('service.control_token.revoke', 'organisation', '', ['session_id' => $sessionId, 'reason' => 'unknown_session'], 'failure');
                sendJson(['error' => 'Unknown session.'], 404); break;
            }
            $orgId = (int)$sess['OrgId'];
            if (!serviceMode_userCanOperate($userId, $role, $orgId, (int)$sess['HostUserId'])) {
                logActivity('service.control_token.revoke', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'reason' => 'not_authorised'], 'failure');
                sendJson(['error' => 'Not authorised.'], 403); break;
            }

            $revoked = sessionControlToken_revokeAllForSession($db, $sessionId, $channel);
            logActivity('service.control_token.revoke', 'organisation', (string)$orgId, ['session_id' => $sessionId, 'channel' => $channel, 'revoked' => $revoked]);

            sendJson(['ok' => true, 'revoked' => $revoked]);
            break;
        }

        /* =================================================================
         * EXTERNAL PRESENTATION-APP DRIVER (#1770 C4, req #4/#7).
         * `service_drive` is the stable internal contract any automation
         * (ProPresenter-class shim, a Companion webhook, a curl loop) can
         * drive a church's Service-Mode session through, authenticated by a
         * durable org-scoped `tblServiceDriverKeys` credential rather than a
         * login. `service_driver_key_{mint,revoke,list}` are the lifecycle
         * endpoints an org-admin uses to provision/retire those credentials.
         * All FOUR are table-existence-gated (503 un-migrated) — see
         * includes/service_driver_keys.php's header for the full design.
         * ================================================================= */
        case 'service_drive': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_mode.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_driver_keys.php';

            /* 1. Pre-auth per-IP probe cap — mirrors service_broadcast_probe
               (api.php, #1408): auth cannot be resolved until AFTER the raw
               key is hashed and looked up, so an unauthenticated/probing
               caller must still be capped before that lookup runs. Per-IP is
               the correct class here (I2) — this is a machine/driver
               endpoint, never a congregant path; a real driver posts once
               per slide change, nowhere near 300/min. */
            $driveProbeIp = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_drive_probe', $driveProbeIp, 300, 60, true, null);
            recordRateLimitHit('service_drive_probe', $driveProbeIp);

            $db = getDbMysqli();
            if (!serviceDriverKeysTableExists($db)) {
                sendJson(['error' => 'Driver keys are not available yet.'], 503); break;
            }

            /* 2. Auth — Authorization: Bearer <key> or X-API-Key: <key>
               (apiKeyFromRequest() — the shared header parser, reused rather
               than re-parsed). */
            $rawKey = apiKeyFromRequest();
            if ($rawKey === null) {
                http_response_code(401);
                header('WWW-Authenticate: Bearer realm="iHymns Service Drive"');
                sendJson(['error' => 'Missing driver key. Send "Authorization: Bearer <key>" or "X-API-Key: <key>".'], 401);
                break;
            }
            $driverKey = serviceDriverKeyVerify($db, $rawKey);
            if ($driverKey === null) {
                http_response_code(401);
                header('WWW-Authenticate: Bearer realm="iHymns Service Drive"');
                sendJson(['error' => 'Invalid or revoked driver key.'], 401);
                break;
            }

            /* 3. Rate limit PER KEY (I2 — never per-IP for an authenticated
               machine caller; #1492's "bucket on a HASH of the credential,
               never the raw value" discipline). 600/min is generous for a
               genuine slide-by-slide driver. */
            $driveKeyBucket = 'drvkey:' . substr(hash('sha256', $rawKey), 0, 24);
            checkRateLimit('service_drive', $driveKeyBucket, 600, 60, true, null);
            recordRateLimitHit('service_drive', $driveKeyBucket);

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            /* songRef (free-text title resolution) is EXPLICITLY DEFERRED to
               the ProPresenter protocol spike (plan §7/§10 S1) — answer 422
               so a shim fails LOUD, never silently. Checked before anything
               else so a shim relying on it finds out immediately. */
            if (isset($body['songRef']) && is_string($body['songRef']) && trim($body['songRef']) !== '') {
                sendJson(['error' => 'songRef not supported yet', 'code' => 'song_ref_unsupported'], 422); break;
            }

            $channel = serviceMode_channel();
            $sessionIdIn = (int)($body['sessionId'] ?? 0);
            $venueIdIn   = (int)($body['venueId'] ?? 0);

            /* 4. Session resolution — EVERY query below is channel-filtered
               AND scoped to the KEY'S OWN organisation (rule #26): a driver
               key can never resolve, let alone drive, a session belonging
               to another org, even on the same channel. This is what makes
               a shim config STATIC — it names a session or a venue, never
               "any session anywhere". */
            if ($sessionIdIn > 0) {
                $sstmt = $db->prepare(
                    "SELECT Id, CurrentSongId FROM tblLiveFollowSessions
                      WHERE Id = ? AND SessionKind = 'service' AND Channel = ? AND IsActive = 1
                        AND OrgId = ?" . ($driverKey['VenueId'] !== null ? ' AND VenueId = ?' : '')
                );
                if ($driverKey['VenueId'] !== null) {
                    $sstmt->bind_param('isii', $sessionIdIn, $channel, $driverKey['OrgId'], $driverKey['VenueId']);
                } else {
                    $sstmt->bind_param('isi', $sessionIdIn, $channel, $driverKey['OrgId']);
                }
            } else {
                $targetVenueId = $venueIdIn > 0 ? $venueIdIn : $driverKey['VenueId'];
                if (!$targetVenueId) {
                    sendJson(['error' => 'No venue.'], 404); break;
                }
                /* "Freshest active" — a shim names a VENUE, never a session,
                   so it must resolve to whichever service is CURRENTLY
                   running there (the same heartbeat-freshness window every
                   other live-session resolver in this file uses). */
                $driveFreshness = (int) LIVE_SESSION_FRESHNESS_SECONDS;
                $sstmt = $db->prepare(
                    "SELECT Id, CurrentSongId FROM tblLiveFollowSessions
                      WHERE SessionKind = 'service' AND Channel = ? AND IsActive = 1
                        AND OrgId = ? AND VenueId = ?
                        AND LastHeartbeatAt > DATE_SUB(UTC_TIMESTAMP(), INTERVAL {$driveFreshness} SECOND)
                      ORDER BY LastHeartbeatAt DESC LIMIT 1"
                );
                $sstmt->bind_param('sii', $channel, $driverKey['OrgId'], $targetVenueId);
            }
            $sstmt->execute();
            $driveSess = $sstmt->get_result()->fetch_assoc();
            $sstmt->close();
            if (!$driveSess) {
                /* ONE opaque message for wrong-org/wrong-venue/no-session/
                   ended (I6 — never a code-existence oracle, plan §11
                   landmine 6). */
                logActivity('service.broadcast.song', 'organisation', (string)$driverKey['OrgId'], ['reason' => 'unknown_or_ended', 'via' => 'driver_key'], 'failure');
                sendJson(['error' => 'Unknown or ended session.'], 404); break;
            }
            $driveSessionId = (int)$driveSess['Id'];

            /* 5. Payload. `songId` absent/omitted → keep the session's
               CURRENT song (a driver adjusting only the section shouldn't
               have to repeat songId on every call — deliberately more
               forgiving than service_broadcast's console, which always
               tracks + resends full context). A PRESENT-but-invalid songId
               is still rejected the same way service_broadcast rejects one
               (#1694/#1765 visibility + servability). */
            $driveSongId = isset($body['songId']) ? _liveFollowCleanSongId((string)$body['songId']) : '';
            if ($driveSongId === '') {
                $effectiveSongId = $driveSess['CurrentSongId'] !== null ? (string)$driveSess['CurrentSongId'] : null;
            } else {
                $chkDrive = $db->prepare('SELECT 1 FROM tblSongs WHERE SongId = ? AND ' . songVisibleSql($db, '') . ' AND ' . songServableSql($db, '') . ' LIMIT 1');
                $chkDrive->bind_param('s', $driveSongId);
                $chkDrive->execute();
                $driveSongOk = $chkDrive->get_result()->fetch_row() !== null;
                $chkDrive->close();
                if (!$driveSongOk) {
                    logActivity('service.broadcast.song', 'organisation', (string)$driverKey['OrgId'], ['session_id' => $driveSessionId, 'reason' => 'unknown_song', 'via' => 'driver_key'], 'failure');
                    sendJson(['error' => 'Unknown song.'], 400); break;
                }
                $effectiveSongId = $driveSongId;
            }

            /* sectionIndex (explicit) wins outright over sectionRef (a label
               to resolve) when both are somehow sent. Neither given → the
               componentIndex is left null (song-level — matches
               ServiceBroadcaster's own "broadcast section 0/song-level on a
               plain song pick" default). */
            $driveComponentIndex = null;
            $sectionResolved = null;
            if (isset($body['sectionIndex']) && $body['sectionIndex'] !== null && is_numeric($body['sectionIndex'])) {
                $driveComponentIndex = min(9999, max(0, (int)$body['sectionIndex']));
                $sectionResolved = true;
            } elseif (isset($body['sectionRef']) && is_string($body['sectionRef']) && trim($body['sectionRef']) !== '') {
                $resolvedSection = ($effectiveSongId !== null)
                    ? serviceMode_resolveSectionIndex($db, $effectiveSongId, (string)$body['sectionRef'])
                    : null;
                if ($resolvedSection !== null) {
                    $driveComponentIndex = $resolvedSection;
                    $sectionResolved = true;
                } else {
                    /* Unresolvable → null → song-level only (owner req #7 —
                       never a guess). */
                    $sectionResolved = false;
                }
            }

            $driveStateJson = serviceMode_cleanState($body['state'] ?? null);

            /* 6. Write — the ONE core, the SAME one the operator console
               writes through (rule #26 I4 / guard G4). */
            /* #1897 W2 — driver-key funnel has no user at all; 'via' extends
               the existing 'bearer'|'control_token' vocabulary with 'driver_key'. */
            $driveRevision = serviceMode_applyBroadcast($db, $driveSessionId, $effectiveSongId, $driveComponentIndex, $driveStateJson, [
                'userId' => null,
                'via'    => 'driver_key',
            ]);

            /* 7. Breadcrumb — mirrors service_broadcast's own "song-change
               only" condition, extending the existing 'via' vocabulary
               (#1408's 'bearer'|'control_token', now +'driver_key'). */
            if ($driveSongId !== '' && (string)($driveSess['CurrentSongId'] ?? '') !== $driveSongId) {
                logActivity('service.broadcast.song', 'organisation', (string)$driverKey['OrgId'], [
                    'session_id' => $driveSessionId,
                    'song_id'    => $driveSongId,
                    'channel'    => $channel,
                    'via'        => 'driver_key',
                ]);
            }

            sendJson(['ok' => true, 'sessionId' => $driveSessionId, 'revision' => $driveRevision, 'sectionResolved' => $sectionResolved]);
            break;
        }

        case 'service_driver_key_mint': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'manage' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'auth.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'entitlements.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_driver_keys.php';

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            /* CSRF (rule #29) — belt-and-braces on this state-changing,
               credential-minting endpoint, same as service_control_token_mint. */
            $csrfToken = is_string($body['csrf_token'] ?? null) ? $body['csrf_token'] : null;
            if (!validateCsrfRequest($csrfToken)) {
                sendJson(['error' => 'Cross-origin request rejected.'], 403); break;
            }

            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            $userId = (int)$authUser['Id'];
            $role   = (string)($authUser['Role'] ?? '');

            $db = getDbMysqli();
            if (!serviceDriverKeysTableExists($db)) {
                sendJson(['error' => 'Driver keys are not available yet.'], 503); break;
            }

            $mintIp = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_driver_key_mint', $mintIp, SERVICE_DRIVER_KEY_MINT_LIMIT_PER_HOUR, 3600, true, $userId);
            recordRateLimitHit('service_driver_key_mint', rateLimitKey($mintIp, $userId));

            $mintOrgId = (int)($body['orgId'] ?? 0);
            $mintLabel = trim((string)($body['label'] ?? ''));
            $mintProtocol = (string)($body['protocol'] ?? 'generic');
            $mintVenueId = isset($body['venueId']) && (int)$body['venueId'] > 0 ? (int)$body['venueId'] : null;
            if ($mintOrgId <= 0 || $mintLabel === '') { sendJson(['error' => 'Missing organisation or label.'], 400); break; }

            /* Auth = admin/global_admin OR org-admin of the TARGET org — the
               same gate shape as service_session_start (api.php:17438-17443). */
            $mintCanOperate = ($role === 'global_admin' || $role === 'admin')
                || in_array($mintOrgId, userIsOrgAdminOf($userId), true);
            if (!$mintCanOperate) {
                logActivity('service.driver_key.mint', 'organisation', (string)$mintOrgId, ['reason' => 'not_authorised'], 'failure');
                sendJson(['error' => 'Not authorised for this organisation.'], 403); break;
            }

            /* Optional venue must belong to the same org (never let a key
               claim a narrowing to another org's venue). */
            if ($mintVenueId !== null) {
                $vchk = $db->prepare('SELECT 1 FROM tblOrgVenues WHERE Id = ? AND OrgId = ? LIMIT 1');
                $vchk->bind_param('ii', $mintVenueId, $mintOrgId);
                $vchk->execute();
                $vOk = $vchk->get_result()->fetch_row() !== null;
                $vchk->close();
                if (!$vOk) { sendJson(['error' => 'Unknown venue for this organisation.'], 400); break; }
            }

            $minted = serviceDriverKeyMint($db, $mintOrgId, $mintVenueId, $mintLabel, $mintProtocol, $userId);
            if ($minted === null) {
                sendJson(['error' => 'Could not mint a driver key, please retry.'], 503); break;
            }

            /* §3.2 breadcrumb — IDs + prefix only, NEVER the raw key. */
            logActivity('service.driver_key.mint', 'organisation', (string)$mintOrgId, ['key_id' => $minted['id'], 'venue_id' => $mintVenueId]);

            sendJson(['ok' => true, 'key' => $minted['raw'], 'id' => $minted['id'], 'prefix' => $minted['prefix']]);
            break;
        }

        case 'service_driver_key_revoke': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'manage' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'auth.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'entitlements.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_driver_keys.php';

            $body = json_decode(file_get_contents('php://input'), true);
            if (!is_array($body)) { $body = []; }

            $csrfToken = is_string($body['csrf_token'] ?? null) ? $body['csrf_token'] : null;
            if (!validateCsrfRequest($csrfToken)) {
                sendJson(['error' => 'Cross-origin request rejected.'], 403); break;
            }

            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            $userId = (int)$authUser['Id'];
            $role   = (string)($authUser['Role'] ?? '');

            $db = getDbMysqli();
            if (!serviceDriverKeysTableExists($db)) {
                sendJson(['error' => 'Driver keys are not available yet.'], 503); break;
            }

            $revokeIp = $_SERVER['REMOTE_ADDR'] ?? '';
            checkRateLimit('service_driver_key_revoke', $revokeIp, 60, 3600, true, $userId);
            recordRateLimitHit('service_driver_key_revoke', rateLimitKey($revokeIp, $userId));

            $revokeKeyId = (int)($body['id'] ?? 0);
            $revokeOrgId = (int)($body['orgId'] ?? 0);
            if ($revokeKeyId <= 0 || $revokeOrgId <= 0) { sendJson(['error' => 'Missing key or organisation.'], 400); break; }

            $revokeCanOperate = ($role === 'global_admin' || $role === 'admin')
                || in_array($revokeOrgId, userIsOrgAdminOf($userId), true);
            if (!$revokeCanOperate) {
                logActivity('service.driver_key.revoke', 'organisation', (string)$revokeOrgId, ['key_id' => $revokeKeyId, 'reason' => 'not_authorised'], 'failure');
                sendJson(['error' => 'Not authorised for this organisation.'], 403); break;
            }

            $revokedOk = serviceDriverKeyRevoke($db, $revokeKeyId, $revokeOrgId);
            logActivity('service.driver_key.revoke', 'organisation', (string)$revokeOrgId, ['key_id' => $revokeKeyId, 'revoked' => $revokedOk]);

            sendJson(['ok' => true, 'revoked' => $revokedOk]);
            break;
        }

        case 'service_driver_key_list': {
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'manage' . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'auth.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'entitlements.php';
            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'service_driver_keys.php';

            $authUser = getAuthenticatedUser();
            if (!$authUser) { sendJson(['error' => 'Not authenticated.'], 401); break; }
            $userId = (int)$authUser['Id'];
            $role   = (string)($authUser['Role'] ?? '');

            $db = getDbMysqli();
            if (!serviceDriverKeysTableExists($db)) {
                sendJson(['ok' => true, 'keys' => []]); break; /* dormant → empty list, not an error, for a read */
            }

            $listOrgId = (int)($_GET['orgId'] ?? 0);
            if ($listOrgId <= 0) { sendJson(['error' => 'Missing organisation.'], 400); break; }

            $listCanOperate = ($role === 'global_admin' || $role === 'admin')
                || in_array($listOrgId, userIsOrgAdminOf($userId), true);
            if (!$listCanOperate) { sendJson(['error' => 'Not authorised for this organisation.'], 403); break; }

            $rows = serviceDriverKeyList($db, $listOrgId);
            $keys = array_map(static function (array $r): array {
                return [
                    'id'         => (int)$r['Id'],
                    'venueId'    => $r['VenueId'] !== null ? (int)$r['VenueId'] : null,
                    'prefix'     => (string)$r['KeyPrefix'],
                    'label'      => (string)$r['Label'],
                    'scope'      => (string)$r['Scope'],
                    'protocol'   => (string)$r['Protocol'],
                    'active'     => (int)$r['IsActive'] === 1 && $r['RevokedAt'] === null,
                    'expiresAt'  => $r['ExpiresAt'],
                    'revokedAt'  => $r['RevokedAt'],
                    'lastUsedAt' => $r['LastUsedAt'],
                    'createdAt'  => $r['CreatedAt'],
                ];
            }, $rows);

            sendJson(['ok' => true, 'keys' => $keys]);
            break;
        }

        /* -----------------------------------------------------------------
         * CAPTCHA WIDGET-HEALTH HINT (the outage grace window's early warning)
         *
         * ELI5: when a visitor's browser cannot load the human-check widget, it
         * quietly tells us so — and all that does is make the server go and
         * check the provider for itself, a bit sooner than it otherwise would.
         *
         * ⚠️ THIS ENDPOINT CAN NEVER LET ANYBODY THROUGH. It is the one place
         * in this feature a CLIENT touches the outage machinery, so the rule
         * matters most here: "the provider is down" and "a bot omitted the
         * token" are indistinguishable if the evidence comes from the client,
         * so a request-borne claim must never move an allow decision — it would
         * be a one-line universal bypass the moment a bot copied it. What this
         * case is allowed to do is exactly two things: increment a telemetry
         * counter, and ASK THE SERVER TO LOOK. The looking
         * (captchaHealthEnsureFresh) makes an outbound probe the server was
         * entitled to make anyway, and the probe's verdict — not this request —
         * is what any later admission derives from. The response is identical
         * whatever the state, so it leaks nothing either.
         * Guard-enforced: tests/php/test-captcha-gate.php §8 asserts this case
         * body calls no decision function, and that captchaOutageDecision() has
         * exactly ONE call site tree-wide (captchaGate).
         *
         * WHY IT EARNS ITS KEEP: the widget fails in the BROWSER seconds before
         * the first token-less submission reaches us, and during a pure
         * widget-load outage the server would otherwise observe nothing at all
         * (token-less requests are refused with no network call). This turns
         * "the window opens after someone is refused" into "the window is
         * usually already open when they submit".
         *
         * NOT CSRF-GATED, deliberately: rule #29 targets state-changing writes,
         * and the only state here is a rate-limited counter plus a probe with
         * no user-visible effect. It must also remain callable from precisely
         * the broken path that produces it.
         *
         * DORMANT-GATED: on an unconfigured install this 400s like any unknown
         * action would — the endpoint does not observably exist.
         * ----------------------------------------------------------------- */
        case 'captcha_widget_health': {
            if ($_SERVER['REQUEST_METHOD'] !== 'POST') { sendJson(['error' => 'POST method required.'], 405); break; }
            if (captchaConfig() === null) { sendJson(['error' => 'Not available.'], 400); break; }

            require_once __DIR__ . DIRECTORY_SEPARATOR . 'includes' . DIRECTORY_SEPARATOR . 'rate_limit.php';
            $cwhIp = (string)($_SERVER['REMOTE_ADDR'] ?? '');
            /* Per-IP so one address cannot fill tblLoginAttempts. Not per
               presence/session — there is nothing to protect but the table. */
            if (!checkRateLimit(CAPTCHA_RATE_ACTION_HINT, $cwhIp, CAPTCHA_HINT_MAX_PER_WINDOW, CAPTCHA_HINT_WINDOW_SECONDS)) {
                sendJson(['ok' => true]);   /* same body as success — never a probe oracle */
                break;
            }
            recordRateLimitHit(CAPTCHA_RATE_ACTION_HINT, $cwhIp);

            /* The form key is read only to be VALIDATED and dropped: it exists
               so a future admin surface can say WHICH form users are failing
               on, and validating it keeps the wire contract honest today. It
               reaches no decision and is not stored. */
            $cwhBody = json_decode((string)file_get_contents('php://input'), true);
            $cwhForm = is_array($cwhBody) ? trim((string)($cwhBody['form'] ?? '')) : '';
            if ($cwhForm !== '' && !in_array($cwhForm, captchaFormKeys(), true)) {
                sendJson(['error' => 'Unknown form.'], 400);
                break;
            }

            captchaHealthNoteHint();                        /* telemetry counter only */
            captchaHealthEnsureFresh((array)captchaConfig()); /* ask the server to LOOK */

            sendJson(['ok' => true]);
            break;
        }

        /* -----------------------------------------------------------------
         * Unknown action
         * ----------------------------------------------------------------- */
        default:
            /* (#535) Record unknown-action attempts so admins can
               spot mis-typed action names from clients (often a
               sign of a forgotten case clause regressing). */
            logActivity(
                'api.unknown_action',
                'api',
                substr((string)$action, 0, 50),
                ['method' => $_SERVER['REQUEST_METHOD'] ?? ''],
                'failure'
            );
            sendJson(['error' => 'Unknown action: ' . htmlspecialchars($action)], 400);
            break;
    }
    } catch (\Throwable $_apiSwitchErr) {
        /* Catch-all for exceptions that escaped a case clause.
           One activity-log row tagged Result='error'; the existing
           500-response behaviour is preserved by re-throwing. */
        logActivityError(
            'api.' . substr((string)$action, 0, 40),
            'api',
            substr((string)$action, 0, 50),
            $_apiSwitchErr,
            ['duration_ms' => (int)((microtime(true) - $_apiSwitchStart) * 1000)]
        );
        /* Re-throw so the existing fatal-handler / 500 response path
           runs as it always has. We are observing, not changing the
           failure semantics. */
        throw $_apiSwitchErr;
    }

    exit;
}

/* =========================================================================
 * NO VALID REQUEST — Return 400
 * ========================================================================= */

sendJson(['error' => 'Missing required parameter: page or action'], 400);

/* =========================================================================
 * HELPER FUNCTIONS
 * ========================================================================= */

/**
 * Send a JSON response with appropriate headers.
 *
 * For v2 clients (opt-in via `X-API-Version: 2`, see `apiContractVersion()` in
 * `includes/api_envelope.php`) the payload is wrapped in the uniform envelope —
 * success → `{ ok:true, data:$data }`, any `$statusCode` >= 400 → the
 * `{ ok:false, error:{…} }` shape (#1201/#1761). v1 clients get the bare
 * `$data` exactly as before. This ONE chokepoint carries the whole envelope
 * for all ~971 call sites (rule #35); the handful of non-`sendJson` responses
 * (streaming exports, CSV, the health probe) are legitimately outside the JSON
 * envelope and documented as such. The wrap DECISION lives in the pure,
 * unit-tested `apiEnvelopeWrap()` (`tests/php/test-api-envelope.php`).
 *
 * @param array $data       Data to encode as JSON
 * @param int   $statusCode HTTP status code (default: 200)
 */
function sendJson(array $data, int $statusCode = 200): void
{
    http_response_code($statusCode);
    header('Content-Type: application/json; charset=UTF-8');
    header('X-Content-Type-Options: nosniff');
    header('Cache-Control: no-cache, must-revalidate');

    $version = apiContractVersion();
    if ($version >= 2) {
        // Echo the negotiated version + Vary so any intermediary keys a cache
        // entry by it (sendJson is already no-cache, so this is belt-and-braces).
        header('X-API-Version: 2');
        header('Vary: X-API-Version', false);
    }

    echo json_encode(
        apiEnvelopeWrap($data, $statusCode, $version),
        JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES
    );
}

/**
 * Build the standard bearer-auth success payload (#1402 prep — Apple
 * backend-auth plan §8 task B).
 *
 * WHY THIS EXISTS: `case 'auth_login'` (api.php:2178, pre-refactor) hand-built
 * this shape inline. The forthcoming `?action=auth_apple` (#1402) endpoint
 * MUST return a byte-identical shape — the native client's DTO
 * (`appApple/Packages/iHymnsKit/Sources/IHModels/AuthSession.swift`) decodes
 * exactly `token` + `user.{id, username, display_name, role,
 * avatar_service}`, and any drift between the two login paths (e.g. auth_apple
 * accidentally adding an `email` key, the way `auth_email_login_verify`'s
 * response does) would silently break Sign-in-with-Apple on the native app
 * while the PWA's own login kept working — a hard bug to spot without a
 * shared source of truth. Extracting the shape into one function makes
 * "does auth_apple match auth_login" a structural property instead of a
 * copy-paste convention; tests/php/test-auth-response-shape.php pins both the
 * key set AND (via a source grep) that every login-style case calls this
 * helper instead of hand-rolling the array again.
 *
 * ELI5: this is the one place that decides what a successful "you're logged
 * in" reply looks like, no matter which door (password, magic link, Apple)
 * the user walked through.
 *
 * @param string      $token          Raw (unhashed) bearer token — the caller
 *                                      already minted + persisted the sha256
 *                                      hash in tblApiTokens before calling this.
 * @param int         $userId         tblUsers.Id
 * @param string      $username       tblUsers.Username
 * @param string      $displayName    tblUsers.DisplayName
 * @param string      $role           tblUsers.Role
 * @param string|null $avatarService  tblUsers.AvatarService, or null when the
 *                                      column doesn't exist yet on this docroot
 *                                      (#616 column-existence gate, api.php:2073)
 *                                      or the user has no override.
 * @return array{token:string,user:array{id:int,username:string,display_name:string,role:string,avatar_service:?string}}
 *
 * @link https://developer.apple.com/documentation/sign_in_with_apple  auth_apple's consumer (#1402)
 */
function apiAuthSuccessPayload(
    string $token,
    int $userId,
    string $username,
    string $displayName,
    string $role,
    ?string $avatarService
): array {
    return [
        'token' => $token,
        'user'  => [
            'id'             => $userId,
            'username'       => $username,
            'display_name'   => $displayName,
            'role'           => $role,
            'avatar_service' => $avatarService,
        ],
    ];
}

/* =============================================================================
 * PASSWORD-RESET FLOOD CONTROL — pure helpers for ?action=auth_forgot_password
 * (#1028), mirroring the apiAuthSuccessPayload() pattern above.
 *
 * ELI5: before #1028 anyone could POST a known tester's email address in a
 * loop and we would mint a fresh reset token and send a real email EVERY time
 * — free inbox flooding, paid for with our token generation and our SMTP
 * reputation. These two helpers hold the throttling DECISION, kept PURE (no
 * DB, no superglobals, no clock) so tests/php/test-auth-rate-limit.php can
 * assert the anti-enumeration contract without a request or a database.
 *
 * WHY A SEPARATE FUNCTION RATHER THAN AN `if` IN THE CASE BODY: #898 fixed the
 * user-enumeration hole by making this endpoint return an IDENTICAL 200 whether
 * or not the account exists, and a rate limit is the classic way that contract
 * gets quietly broken again — "throttled" must not become the tell that says
 * "this address is real". apiForgotPasswordDecision() makes that structural
 * instead of conventional: it takes NO account-existence parameter, so account
 * existence CANNOT influence the response, and a future edit that tried to make
 * it would have to change the signature (which the test pins by reflection).
 * ========================================================================== */

/**
 * The ONE 200-response body ?action=auth_forgot_password ever returns.
 *
 * ELI5: the single "we've done what we can, check your inbox" reply — the same
 * words whether we just emailed a real user, found nobody with that address, or
 * quietly declined because that address has already had its share of resets
 * this hour.
 *
 * @return array{ok:bool,message:string}
 */
function apiForgotPasswordGenericResponse(): array
{
    return [
        'ok'      => true,
        'message' => 'If an account exists with that username or email, a reset link has been generated.',
    ];
}

/**
 * Decide what a forgot-password request does, given only the two throttle
 * verdicts. PURE — no DB, no superglobals, no time.
 *
 * ELI5: two buckets have already been checked before we get here — "has this
 * computer asked too often?" and "has this address been asked about too often?".
 * This function turns those two yes/nos into what the user sees.
 *
 * THE TWO BUCKETS ARE HANDLED DIFFERENTLY, ON PURPOSE:
 *
 *   - PER-IP exhausted → a real 429. This says something about the REQUESTER
 *     and nothing about any account: the bucket is keyed on the caller's own
 *     address, so the caller could have predicted the 429 from their own
 *     behaviour alone. Zero information transfer, and a legitimate user who
 *     double-clicked gets an honest, actionable answer.
 *
 *   - PER-IDENTIFIER exhausted → a SILENT DROP: the ordinary 200 body, no token
 *     minted, no email sent. A 429 here WOULD be an oracle in one specific
 *     case: an attacker probing an address they had not themselves exhausted
 *     could infer "somebody has been requesting resets for this address
 *     recently, so it is a real one". Returning the standard 200 removes the
 *     observable difference entirely. The cost is that a user who genuinely
 *     over-requests gets silence rather than an explanation — the correct trade
 *     for an endpoint whose whole job is to be uninformative (#898).
 *
 * Why an IDENTIFIER bucket at all, rather than per-IP only: per-IP alone stops
 * one machine, but the abuse in #1028 (flood a known tester's inbox) is exactly
 * what a handful of addresses — or a botnet — walks straight past. Capping per
 * submitted identifier caps the VICTIM'S INBOX no matter where the requests
 * come from. And why keep the per-IP bucket too: identifier-only would let one
 * machine cycle identifiers indefinitely, burning token generation and mail
 * quota across the whole user base. Neither is sufficient alone.
 *
 * The identifier bucket keys on the SUBMITTED string, never on a resolved
 * account, so it fills identically for a real and an imaginary address.
 *
 * @param bool $ipAllowed         Per-IP bucket still has budget.
 * @param bool $identifierAllowed Per-submitted-identifier bucket still has budget.
 * @return array{status:int,send:bool,body:array} `send` = may we mint a token
 *         and email it; `body`/`status` = exactly what to write to the client.
 */
function apiForgotPasswordDecision(bool $ipAllowed, bool $identifierAllowed): array
{
    if (!$ipAllowed) {
        return [
            'status' => 429,
            'send'   => false,
            'body'   => ['error' => 'Too many password reset requests. Please try again later.'],
        ];
    }
    if (!$identifierAllowed) {
        /* Silent drop — byte-identical to the allowed body below. */
        return ['status' => 200, 'send' => false, 'body' => apiForgotPasswordGenericResponse()];
    }
    return ['status' => 200, 'send' => true, 'body' => apiForgotPasswordGenericResponse()];
}

/**
 * Rate-limit bucket key for a submitted username-or-email.
 *
 * ELI5: turns whatever the user typed into a short fixed-length label we can
 * count against, so two people typing the same address land in the same bucket.
 *
 * Normalised with strtolower(trim()) — the SAME normalisation
 * generatePasswordResetToken() (manage/includes/auth.php) applies before its
 * lookup, so "Alice@Example.com " and "alice@example.com" cannot be split into
 * two buckets to double the budget for one real account.
 *
 * Hashed for two practical reasons, NOT for secrecy (an email address is
 * low-entropy and the activity-log row for this endpoint already records the
 * raw lookup): (1) tblLoginAttempts.IpAddress is VARCHAR(45) and email
 * addresses routinely exceed that — an un-hashed key would silently truncate
 * and merge unrelated addresses into one bucket; (2) it avoids copying account
 * identifiers into a second table. 'pwr:' + 40 hex = 44 chars, inside the
 * column width.
 *
 * @param string $submitted Raw `username` field from the request body.
 * @return string Bucket key, ≤45 chars.
 */
function apiForgotPasswordIdentifierKey(string $submitted): string
{
    return 'pwr:' . substr(hash('sha256', strtolower(trim($submitted))), 0, 40);
}

/* =============================================================================
 * SIGN IN WITH APPLE — account-mapping helpers (#1402)
 *
 * The `case 'auth_apple'` handler (above) delegates the `sub` → account
 * resolution here so the case block itself stays a readable top-to-bottom
 * sequence. All of §2.5's create-or-link decision lives in
 * _authAppleMapAccountTxn(); its wrapper _authAppleMapAccount() owns the
 * transaction boundary + the one-shot race retry §2.5(d) calls for.
 * ========================================================================= */

/**
 * Resolve+validate the `platform` discriminator for ?action=auth_apple
 * (#1470 W1) — PURE (no DB, no superglobals) so
 * tests/php/test-auth-apple-platform.php can assert the allow-list without
 * a request. Absent/empty → 'native' (every existing caller — the shipped
 * native app — never sends this field, so its request resolves EXACTLY as
 * it did before this discriminator existed). Any OTHER value is invalid; the
 * caller (the `auth_apple` case body) responds with its standard 400 shape
 * rather than silently guessing a platform.
 *
 * @param mixed $platformRaw The raw `platform` value from the decoded JSON body (or null/absent).
 * @return array{ok:bool,platform:?string} ok=false ⇒ platform is always null.
 */
function _authApplePlatformResolve($platformRaw): array
{
    if ($platformRaw === null || $platformRaw === '') {
        return ['ok' => true, 'platform' => 'native'];
    }
    if ($platformRaw === 'native' || $platformRaw === 'web') {
        return ['ok' => true, 'platform' => $platformRaw];
    }
    return ['ok' => false, 'platform' => null];
}

/**
 * Record a failed auth_apple attempt: a Success=0 tblLoginAttempts row (feeds
 * the per-IP rate-limit counter, mirroring auth_login) plus an
 * `auth.login_apple` failure row in tblActivityLog carrying ONLY the fixed
 * `$reason` code — never token/claim content (#1402 §2.7 — the client always
 * sees the SAME generic 401 message; the reason is for operator triage only).
 */
function _authAppleRecordFailure(\mysqli $db, string $clientIp, string $reason): void
{
    try {
        $stmt = $db->prepare("INSERT INTO tblLoginAttempts (IpAddress, Username, Success) VALUES (?, 'auth_apple', 0)");
        $stmt->bind_param('s', $clientIp);
        $stmt->execute();
        $stmt->close();
    } catch (\Throwable $_e) {
        /* Best-effort — a rate-limit bookkeeping failure must never block
           the (already-failing) response from going out. */
    }
    logActivity('auth.login_apple', '', '', ['reason' => $reason], 'failure');
}

/**
 * Fetch an active user's core fields in the exact shape apiAuthSuccessPayload()
 * needs, applying the same #616 AvatarService column-existence gate
 * getAuthenticatedUser()/auth_login use (api.php ~2073/~13104) so a
 * partly-migrated install still works. Returns null when the row is missing
 * OR IsActive = 0 — auth_apple's caller treats both the same way (a link
 * whose target account no longer exists would be an FK-integrity bug, and an
 * inactive account must be rejected exactly like auth_login does, api.php ~2129).
 *
 * @return array{Id:int,Username:string,DisplayName:string,Role:string,AvatarService:?string}|null
 */
function _authAppleFetchActiveUser(\mysqli $db, int $userId): ?array
{
    static $hasAvatarSvcCol = null;
    if ($hasAvatarSvcCol === null) {
        $r = $db->query(
            "SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
              WHERE TABLE_SCHEMA = DATABASE()
                AND TABLE_NAME   = 'tblUsers'
                AND COLUMN_NAME  = 'AvatarService' LIMIT 1"
        );
        $hasAvatarSvcCol = ($r && $r->fetch_row() !== null);
        if ($r) { $r->close(); }
    }
    $avatarSel = $hasAvatarSvcCol ? ', AvatarService' : ', NULL AS AvatarService';
    $stmt = $db->prepare("SELECT Id, Username, DisplayName, Role, IsActive {$avatarSel} FROM tblUsers WHERE Id = ?");
    $stmt->bind_param('i', $userId);
    $stmt->execute();
    $row = $stmt->get_result()->fetch_assoc();
    $stmt->close();
    if (!$row || (int)$row['IsActive'] !== 1) {
        return null;
    }
    $row['Id'] = (int)$row['Id'];
    return $row;
}

/**
 * Build the IdentityJson snapshot stored on a NEW/newly-linked
 * tblUserAuthProviders row (plan §2.5d) — a forward-looking capture of the
 * data Apple only ever sends once: `fullName` is present ONLY on the FIRST
 * authorization for a given Apple ID + app pair, so if we don't snapshot it
 * here it is gone forever.
 */
function _authAppleIdentityJson(array $claims, ?array $fullName): string
{
    $data = [];
    if (is_array($fullName)) {
        $given  = isset($fullName['givenName'])  ? mb_substr(trim((string)$fullName['givenName']), 0, 100)  : '';
        $family = isset($fullName['familyName']) ? mb_substr(trim((string)$fullName['familyName']), 0, 100) : '';
        if ($given !== '' || $family !== '') {
            $data['fullName'] = ['givenName' => $given, 'familyName' => $family];
        }
    }
    if (isset($claims['real_user_status'])) {
        $data['real_user_status'] = $claims['real_user_status'];
    }
    $data['email_verified'] = in_array($claims['email_verified'] ?? null, [true, 'true'], true);

    $encoded = json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    return $encoded !== false ? $encoded : '{}';
}

/**
 * Insert a NEW tblUserAuthProviders row linking $userId to the verified
 * Apple `sub`, then re-fetch the (now-linked) active user. Shared by §2.5(b)
 * link-mode and §2.5(c) email-auto-link.
 *
 * Duplicate-key handling (both UNIQUE constraints on the table):
 *   - `uq_user_provider` (UserId, Provider) — this account already has a
 *     DIFFERENT Apple identity linked → 409 "already linked to a different
 *     Apple ID."
 *   - `uq_provider_subject` (Provider, Subject) — this Apple identity is
 *     already linked to a DIFFERENT account (a race with a concurrent
 *     request) → 409 "already linked to another iHymns account."
 *
 * @return array{ok:true,userId:int,flow:string,user:array}|array{ok:false,status:int,message:string}
 */
function _authAppleInsertLink(\mysqli $db, int $userId, string $sub, array $claims, ?array $fullName, string $flow): array
{
    $claimEmail = is_string($claims['email'] ?? null) ? mb_strtolower(trim($claims['email'])) : '';
    $emailHost  = '';
    $atPos = strrpos($claimEmail, '@');
    if ($atPos !== false) {
        $emailHost = substr($claimEmail, $atPos + 1);
    }
    $isPrivateRelay = ($emailHost === 'privaterelay.appleid.com') ? 1 : 0;
    $identityJson   = _authAppleIdentityJson($claims, $fullName);

    try {
        $stmt = $db->prepare(
            "INSERT INTO tblUserAuthProviders (UserId, Provider, Subject, Email, EmailIsPrivateRelay, IdentityJson, LastLoginAt)
             VALUES (?, 'apple', ?, ?, ?, ?, NOW())"
        );
        $stmt->bind_param('issis', $userId, $sub, $claimEmail, $isPrivateRelay, $identityJson);
        $stmt->execute();
        $stmt->close();
    } catch (\mysqli_sql_exception $e) {
        if ($e->getCode() === 1062) {
            if (str_contains($e->getMessage(), 'uq_user_provider')) {
                return ['ok' => false, 'status' => 409, 'message' => 'This account is already linked to a different Apple ID.'];
            }
            return ['ok' => false, 'status' => 409, 'message' => 'This Apple ID is already linked to another iHymns account.'];
        }
        throw $e;
    }

    $userRow = _authAppleFetchActiveUser($db, $userId);
    if ($userRow === null) {
        /* The target account is disabled (or, in theory, vanished mid-flight).
           Reject WITHOUT persisting — the caller (_authAppleMapAccount) rolls
           back the whole transaction on any non-ok result, so the link row
           just inserted above never survives. */
        return ['ok' => false, 'status' => 403, 'message' => 'Account is disabled.'];
    }
    return ['ok' => true, 'userId' => $userId, 'flow' => $flow, 'user' => $userRow];
}

/**
 * §2.5(d) — nothing matched an existing/linkable account: create a brand-new
 * iHymns user (mirroring `_completeEmailLoginTxn()`, manage/includes/auth.php
 * ~1624) and link it to the verified Apple `sub`.
 *
 * Role is HARD-CODED to 'user' — deliberately NOT the first-user→global_admin
 * bootstrap `_completeEmailLoginTxn()` uses. A fresh-install race where the
 * very first account arrives via a public, replayable-looking endpoint must
 * never mint an admin; the web installer owns that bootstrap.
 *
 * @return array{ok:true,userId:int,flow:'created',user:array}|array{retry:true}
 */
function _authAppleCreateAndLink(\mysqli $db, string $sub, array $claims, ?array $fullName): array
{
    $emailVerifiedClaim = in_array($claims['email_verified'] ?? null, [true, 'true'], true);
    $claimEmail = is_string($claims['email'] ?? null) ? mb_strtolower(trim($claims['email'])) : '';

    /* Username: sanitised local-part of the claim email, or a random
       apple_<hex> handle when the email is absent or too short to sanitise
       into something usable (mirrors _completeEmailLoginTxn's fallback). */
    $username = '';
    if ($claimEmail !== '') {
        $localPart = strstr($claimEmail, '@', true);
        $username  = preg_replace('/[^a-z0-9_.\-]/', '', mb_strtolower((string)$localPart));
    }
    if (!is_string($username) || strlen($username) < 3) {
        $username = 'apple_' . bin2hex(random_bytes(3));
    }

    $baseUsername = $username;
    $counter = 1;
    $countStmt = $db->prepare('SELECT COUNT(*) FROM tblUsers WHERE Username = ?');
    $countStmt->bind_param('s', $username);
    while (true) {
        $countStmt->execute();
        $countRow = $countStmt->get_result()->fetch_row();
        if ((int)($countRow[0] ?? 0) === 0) { break; }
        $username = $baseUsername . $counter;
        $counter++;
    }
    $countStmt->close();

    $displayName = '';
    if (is_array($fullName)) {
        $given  = isset($fullName['givenName'])  ? mb_substr(trim((string)$fullName['givenName']), 0, 100)  : '';
        $family = isset($fullName['familyName']) ? mb_substr(trim((string)$fullName['familyName']), 0, 100) : '';
        $displayName = trim($given . ' ' . $family);
    }
    if ($displayName === '') {
        $displayName = ucfirst($baseUsername);
    }

    $emailVerifiedInt = $emailVerifiedClaim ? 1 : 0;
    $emptyPwHash = ''; /* Passwordless account sentinel (matches tblUsers.PasswordHash's documented convention). */
    $roleUser = 'user';

    $stmt = $db->prepare(
        'INSERT INTO tblUsers (Username, Email, EmailVerified, PasswordHash, DisplayName, Role)
         VALUES (?, ?, ?, ?, ?, ?)'
    );
    $stmt->bind_param('ssisss', $username, $claimEmail, $emailVerifiedInt, $emptyPwHash, $displayName, $roleUser);
    $stmt->execute();
    $newUserId = (int)$db->insert_id;
    $stmt->close();

    $emailHost = '';
    $atPos = strrpos($claimEmail, '@');
    if ($atPos !== false) {
        $emailHost = substr($claimEmail, $atPos + 1);
    }
    $isPrivateRelay = ($emailHost === 'privaterelay.appleid.com') ? 1 : 0;
    $identityJson   = _authAppleIdentityJson($claims, $fullName);

    try {
        $stmt = $db->prepare(
            "INSERT INTO tblUserAuthProviders (UserId, Provider, Subject, Email, EmailIsPrivateRelay, IdentityJson, LastLoginAt)
             VALUES (?, 'apple', ?, ?, ?, ?, NOW())"
        );
        $stmt->bind_param('issis', $newUserId, $sub, $claimEmail, $isPrivateRelay, $identityJson);
        $stmt->execute();
        $stmt->close();
    } catch (\mysqli_sql_exception $e) {
        if ($e->getCode() === 1062) {
            /* Concurrent duplicate on uq_provider_subject: another request
               for this EXACT Apple `sub` won the race between our (a) lookup
               (which found nothing) and this INSERT. Signal the wrapper to
               roll back this whole attempt (including the tblUsers row just
               created above) and re-resolve via a fresh (a) lookup — see
               _authAppleMapAccount()'s retry loop. (uq_user_provider cannot
               fire here: $newUserId was just minted, so it cannot already
               hold a link.) */
            return ['retry' => true];
        }
        throw $e;
    }

    $userRow = _authAppleFetchActiveUser($db, $newUserId);
    if ($userRow === null) {
        /* Should be unreachable — the row was just created with IsActive's
           schema default (1). A defensive throw beats indexing a null user. */
        throw new \RuntimeException('auth_apple: newly created user not found/active after insert (id ' . $newUserId . ')');
    }
    return ['ok' => true, 'userId' => $newUserId, 'flow' => 'created', 'user' => $userRow];
}

/**
 * §2.5 core — resolve the verified Apple `sub` to an iHymns account, in
 * priority order: (a) an existing link (the 99% warm path — never touches
 * email, so a user who disables their private-relay alias or flips
 * share-my-email keeps signing in fine) → (b) explicit link-mode against the
 * caller's current bearer → (c) strict email auto-link (JWT-verified email,
 * exactly one matching verified account, no existing Apple link) → (d) create
 * a brand-new account.
 *
 * Runs entirely inside its own transaction (mirrors completeEmailLogin()'s
 * #1011 wrapper). ANY throw rolls back and re-throws (the case block's
 * caller then hits the api.php global exception handler, api.php ~81, for a
 * clean JSON 500 — the account/link state is left exactly as it was before
 * this call). A non-'ok' result (conflict, disabled account, not-
 * authenticated for link mode) ALSO rolls back — even a rejected attempt
 * that inserted a link row (then discovered the target is disabled) must
 * leave no trace.
 *
 * @return array{ok:true,userId:int,flow:string,user:array}|array{ok:false,status:int,message:string}
 */
function _authAppleMapAccount(\mysqli $db, string $sub, array $claims, ?int $linkBearerUserId, ?array $fullName, bool $linkMode): array
{
    for ($attempt = 0; $attempt < 2; $attempt++) {
        $db->begin_transaction();
        try {
            $result = _authAppleMapAccountTxn($db, $sub, $claims, $linkBearerUserId, $fullName, $linkMode);
        } catch (\Throwable $e) {
            try { $db->rollback(); } catch (\Throwable $_ignore) { /* best-effort */ }
            throw $e;
        }

        if (($result['retry'] ?? false) === true) {
            try { $db->rollback(); } catch (\Throwable $_ignore) { /* best-effort */ }
            continue; /* Re-run (a) fresh — see _authAppleCreateAndLink()'s retry comment. */
        }

        if (($result['ok'] ?? false) === true) {
            $db->commit();
        } else {
            try { $db->rollback(); } catch (\Throwable $_ignore) { /* best-effort */ }
        }
        return $result;
    }

    /* Unreachable in practice — the retry always resolves via (a) on attempt
       2 once the winning transaction has committed — but never leave a
       function without a typed return on every path. */
    return ['ok' => false, 'status' => 500, 'message' => 'Could not resolve Apple account link.'];
}

/** Inner body of _authAppleMapAccount(), executed inside its transaction. See that function's docblock. */
function _authAppleMapAccountTxn(\mysqli $db, string $sub, array $claims, ?int $linkBearerUserId, ?array $fullName, bool $linkMode): array
{
    /* (a) Existing link — identity is ALWAYS (Provider, Subject), never email. */
    $stmt = $db->prepare("SELECT UserId FROM tblUserAuthProviders WHERE Provider = 'apple' AND Subject = ?");
    $stmt->bind_param('s', $sub);
    $stmt->execute();
    $linkRow = $stmt->get_result()->fetch_assoc();
    $stmt->close();
    if ($linkRow) {
        $userId = (int)$linkRow['UserId'];
        $userRow = _authAppleFetchActiveUser($db, $userId);
        if ($userRow === null) {
            return ['ok' => false, 'status' => 403, 'message' => 'Account is disabled.'];
        }
        return ['ok' => true, 'userId' => $userId, 'flow' => 'matched', 'user' => $userRow];
    }

    /* (b) No link + explicit link mode + valid bearer (checked by the case
       block before calling here — $linkBearerUserId is non-null only then). */
    if ($linkMode) {
        if ($linkBearerUserId === null) {
            return ['ok' => false, 'status' => 401, 'message' => 'Not authenticated.'];
        }
        return _authAppleInsertLink($db, $linkBearerUserId, $sub, $claims, $fullName, 'linked');
    }

    /* (c) Strict email auto-link. ALL FOUR conditions must hold:
       (1) JWT asserts email_verified; (2) EXACTLY ONE tblUsers row matches
       (Email has no UNIQUE constraint — 0 or ≥2 matches means no auto-link);
       (3) that row is itself EmailVerified — the account-takeover kill: an
       attacker who pre-registers an unverified account with the victim's
       address must never inherit it on the victim's first SIWA login;
       (4) that row has no existing Apple link (checked explicitly here so we
       never even attempt an INSERT that would race the uq_user_provider
       constraint for a no-op). */
    $emailVerifiedClaim = in_array($claims['email_verified'] ?? null, [true, 'true'], true);
    $claimEmail = is_string($claims['email'] ?? null) ? mb_strtolower(trim($claims['email'])) : '';
    if ($claimEmail !== '' && $emailVerifiedClaim) {
        $stmt = $db->prepare('SELECT Id, EmailVerified FROM tblUsers WHERE LOWER(Email) = ?');
        $stmt->bind_param('s', $claimEmail);
        $stmt->execute();
        $matches = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
        $stmt->close();
        if (count($matches) === 1 && (int)$matches[0]['EmailVerified'] === 1) {
            $candidateId = (int)$matches[0]['Id'];
            $existingStmt = $db->prepare("SELECT 1 FROM tblUserAuthProviders WHERE UserId = ? AND Provider = 'apple'");
            $existingStmt->bind_param('i', $candidateId);
            $existingStmt->execute();
            $alreadyLinked = $existingStmt->get_result()->fetch_row() !== null;
            $existingStmt->close();
            if (!$alreadyLinked) {
                return _authAppleInsertLink($db, $candidateId, $sub, $claims, $fullName, 'linked');
            }
        }
    }

    /* (d) Nothing matched — create a brand-new account. */
    return _authAppleCreateAndLink($db, $sub, $claims, $fullName);
}

/* =============================================================================
 * ACCOUNT DELETION — self-service helpers (#1403)
 *
 * The `case 'account_delete'` handler (above) delegates its re-auth check and
 * Apple-revoke step here so the case block itself stays a readable
 * top-to-bottom sequence. Shares the SIWA crypto core (includes/apple_siwa.php)
 * with `case 'auth_apple'` above — a `siwa_reauth` nonce purpose keeps a
 * login nonce from being replayed into a delete and vice versa.
 * ========================================================================= */

/**
 * Memoized existence probe for the SIWA tables (mirrors the same
 * INFORMATION_SCHEMA pattern as auth_apple's feature gate). account_delete
 * treats absence as "no Apple-specific work to do" rather than an error —
 * deletion must work identically on a docroot where the #1402 migration
 * hasn't been run yet.
 */
function _accountDeleteSiwaTablesReady(\mysqli $db): bool
{
    static $ready = null;
    if ($ready === null) {
        $r = $db->query(
            "SELECT 1 FROM INFORMATION_SCHEMA.TABLES
              WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'tblUserAuthProviders' LIMIT 1"
        );
        $ready = ($r && $r->fetch_row() !== null);
        if ($r) { $r->close(); }
    }
    return $ready;
}

/** True when $userId has an Apple identity linked. Used by the degenerate-account rung (§3.1). */
function _accountDeleteHasAppleLink(\mysqli $db, int $userId): bool
{
    if (!_accountDeleteSiwaTablesReady($db)) {
        return false;
    }
    $stmt = $db->prepare("SELECT 1 FROM tblUserAuthProviders WHERE UserId = ? AND Provider = 'apple'");
    $stmt->bind_param('i', $userId);
    $stmt->execute();
    $has = $stmt->get_result()->fetch_row() !== null;
    $stmt->close();
    return $has;
}

/**
 * Record a failed account_delete re-auth attempt: a Success=0
 * tblLoginAttempts row (feeds the per-IP rate limit) plus an
 * `account.delete` failure row in tblActivityLog carrying ONLY the fixed
 * `$reason` code and the (already-known, non-PII) numeric user id — never a
 * password, code, or token value.
 */
function _accountDeleteRecordFailure(\mysqli $db, string $clientIp, int $userId, string $reason): void
{
    try {
        $stmt = $db->prepare("INSERT INTO tblLoginAttempts (IpAddress, Username, Success) VALUES (?, 'account_delete', 0)");
        $stmt->bind_param('s', $clientIp);
        $stmt->execute();
        $stmt->close();
    } catch (\Throwable $_e) {
        /* Best-effort — a rate-limit bookkeeping failure must never block
           the (already-failing) response from going out. */
    }
    logActivity('account.delete', 'user', (string)$userId, ['reason' => $reason], 'failure');
}

/**
 * §3.1 rung 2 — verify a FRESH SIWA identity-token assertion for re-auth
 * purposes. Runs the FULL RS256 verify (same core as auth_apple) with nonce
 * Purpose `siwa_reauth` (kept separate from `siwa_login` so a sign-in nonce
 * can never be replayed into a delete, or vice versa), then requires the
 * verified `sub` to equal THIS account's own linked Apple Subject — a valid-
 * but-DIFFERENT Apple identity must not authorise deleting someone else's
 * account.
 *
 * @return array{ok:true,method:'siwa'}|array{ok:false,status:int,message:string,recordFailure?:bool,reason?:string}
 */
function _accountDeleteReauthSiwa(\mysqli $db, int $userId, string $identityToken, string $rawNonce): array
{
    if (!_accountDeleteSiwaTablesReady($db)) {
        return ['ok' => false, 'status' => 503, 'message' => 'Sign in with Apple is not yet available.'];
    }

    $stmt = $db->prepare("SELECT Subject FROM tblUserAuthProviders WHERE UserId = ? AND Provider = 'apple'");
    $stmt->bind_param('i', $userId);
    $stmt->execute();
    $linkRow = $stmt->get_result()->fetch_assoc();
    $stmt->close();
    if (!$linkRow) {
        return ['ok' => false, 'status' => 401, 'message' => 'Invalid Apple identity token.', 'recordFailure' => true, 'reason' => 'no_apple_link'];
    }
    $expectedSub = (string)$linkRow['Subject'];

    $peekParts = appleSiwaDecodeJwtParts($identityToken);
    if ($peekParts === null) {
        return ['ok' => false, 'status' => 401, 'message' => 'Invalid Apple identity token.', 'recordFailure' => true, 'reason' => 'malformed_jwt'];
    }
    $peekKid = $peekParts['header']['kid'] ?? null;
    $peekKid = is_string($peekKid) ? $peekKid : null;

    $jwks = appleSiwaJwksCached($db, $peekKid);
    if ($jwks === null || empty($jwks['keys'])) {
        return ['ok' => false, 'status' => 503, 'message' => 'Sign in with Apple is temporarily unavailable.'];
    }

    $verify = appleSiwaVerifyIdentityToken($identityToken, $jwks, IHYMNS_SIWA_CLIENT_ID, $rawNonce, time());
    if ($verify['ok'] !== true) {
        return ['ok' => false, 'status' => 401, 'message' => 'Invalid Apple identity token.', 'recordFailure' => true, 'reason' => (string)($verify['reason'] ?? 'verify_failed')];
    }

    $claimSub = (string)$verify['claims']['sub'];
    if (!hash_equals($expectedSub, $claimSub)) {
        return ['ok' => false, 'status' => 401, 'message' => 'Invalid Apple identity token.', 'recordFailure' => true, 'reason' => 'sub_mismatch'];
    }

    if (!appleSiwaConsumeNonce($db, 'siwa_reauth', $rawNonce)) {
        return ['ok' => false, 'status' => 401, 'message' => 'Invalid Apple identity token.', 'recordFailure' => true, 'reason' => 'nonce_replay'];
    }

    return ['ok' => true, 'method' => 'siwa'];
}

/**
 * §3.1 rung selector — checks the body for exactly the FIRST applicable
 * re-auth proof, in priority order: password → SIWA assertion → email code →
 * (degenerate-account only) an explicit `confirm: "DELETE"`. Every branch
 * that represents a WRONG proof (not merely an absent one) sets
 * `recordFailure` so the caller feeds the per-IP rate-limit counter.
 *
 * @return array{ok:true,method:string}|array{ok:false,status:int,message:string,recordFailure?:bool,reason?:string}
 */
function _accountDeleteReauth(\mysqli $db, int $userId, array $userDetail, array $body): array
{
    $password = $body['password'] ?? null;
    if (is_string($password) && $password !== '') {
        /* password_verify() against an empty hash (passwordless accounts,
           tblUsers.PasswordHash = '') safely returns false — same behaviour
           case 'auth_login' already relies on — so no separate "does this
           account even have a password" branch is needed. */
        if (!password_verify($password, (string)($userDetail['PasswordHash'] ?? ''))) {
            return ['ok' => false, 'status' => 401, 'message' => 'Current password is incorrect.', 'recordFailure' => true, 'reason' => 'wrong_password'];
        }
        return ['ok' => true, 'method' => 'password'];
    }

    $identityToken = $body['identityToken'] ?? null;
    $nonce = $body['nonce'] ?? null;
    if (is_string($identityToken) && $identityToken !== '' && is_string($nonce) && $nonce !== '') {
        return _accountDeleteReauthSiwa($db, $userId, $identityToken, $nonce);
    }

    $emailCode = $body['email_code'] ?? null;
    if (is_string($emailCode) && $emailCode !== '') {
        $email = (string)($userDetail['Email'] ?? '');
        if ($email === '') {
            return ['ok' => false, 'status' => 400, 'message' => 'Re-authentication required: provide password, identityToken+nonce, or email_code.'];
        }
        /* verifyEmailLoginCode() (manage/includes/auth.php) is single-use +
           10-minute-expiry already — the SAME code minted by the existing
           auth_email_login_request flow to the account's OWN email. */
        $verified = verifyEmailLoginCode($email, $emailCode);
        if ($verified === null) {
            return ['ok' => false, 'status' => 401, 'message' => 'Invalid or expired code.', 'recordFailure' => true, 'reason' => 'wrong_email_code'];
        }
        return ['ok' => true, 'method' => 'email_code'];
    }

    $confirm = $body['confirm'] ?? null;
    if (is_string($confirm) && $confirm === 'DELETE') {
        /* Degenerate account only (no password, no email, no Apple link) —
           there is no credential to prove, so the bearer alone (plus this
           explicit type-to-confirm literal) is accepted. Not reachable via
           any current signup path; documented + accepted per plan §8
           open-decision 3. */
        $degenerate = ((string)($userDetail['PasswordHash'] ?? '') === '')
            && ((string)($userDetail['Email'] ?? '') === '')
            && !_accountDeleteHasAppleLink($db, $userId);
        if ($degenerate) {
            return ['ok' => true, 'method' => 'confirm'];
        }
    }

    return ['ok' => false, 'status' => 400, 'message' => 'Re-authentication required: provide password, identityToken+nonce, or email_code.'];
}

/**
 * §3.3A — best-effort Apple `/auth/revoke`. Returns one of the plan's
 * outcome enum values; NEVER throws (every failure is caught and mapped to
 * `failed`) so the caller can safely treat this as a pure side-effect step
 * that cannot abort the deletion.
 *
 * @param array  $linkRow      The tblUserAuthProviders row (Subject, RefreshToken).
 * @param string $reauthMethod Which re-auth rung succeeded — 'siwa' unlocks
 *                               the just-in-time code exchange below when no
 *                               refresh token was already stored.
 * @param array  $body         The request body — read for `authorizationCode`
 *                               ONLY when $reauthMethod === 'siwa'.
 * @return string 'ok'|'failed'|'skipped_no_key'|'skipped_no_token'
 */
function _accountDeleteRevokeApple(array $linkRow, string $reauthMethod, array $body): string
{
    $revokeToken = isset($linkRow['RefreshToken']) && $linkRow['RefreshToken'] !== null
        ? (string)$linkRow['RefreshToken']
        : null;

    $teamId = (string)(getAppSetting('apple_team_id', '') ?? '');
    $keyId  = (string)(getAppSetting('apple_siwa_key_id', '') ?? '');
    $p8Pem  = (string)(getAppSetting('apple_siwa_private_key', '') ?? '');
    $hasKey = ($teamId !== '' && $keyId !== '' && $p8Pem !== '');

    /* No stored refresh token, but THIS request's re-auth was itself a fresh
       SIWA assertion carrying an authorizationCode (§2.6 machinery) — spend
       it now purely to obtain a revocable token before it's gone. */
    if ($revokeToken === null && $reauthMethod === 'siwa' && $hasKey) {
        $authCode = $body['authorizationCode'] ?? null;
        if (is_string($authCode) && $authCode !== '') {
            try {
                $clientSecret = appleSiwaBuildClientSecret($teamId, $keyId, IHYMNS_SIWA_CLIENT_ID, $p8Pem, time());
                if ($clientSecret !== null) {
                    $tokenResp = appleSiwaExchangeCode($authCode, $clientSecret, IHYMNS_SIWA_CLIENT_ID);
                    if ($tokenResp !== null && !empty($tokenResp['refresh_token']) && is_string($tokenResp['refresh_token'])) {
                        $revokeToken = $tokenResp['refresh_token'];
                    }
                }
            } catch (\Throwable $e) {
                error_log('[api/account_delete token_exchange] ' . $e->getMessage());
            }
        }
    }

    if ($revokeToken === null) {
        return 'skipped_no_token';
    }
    if (!$hasKey) {
        return 'skipped_no_key';
    }

    try {
        $clientSecret = appleSiwaBuildClientSecret($teamId, $keyId, IHYMNS_SIWA_CLIENT_ID, $p8Pem, time());
        if ($clientSecret === null) {
            return 'skipped_no_key'; /* .p8 present but doesn't parse as an EC key — treat as "no usable key". */
        }
        return appleSiwaRevokeToken($revokeToken, 'refresh_token', $clientSecret, IHYMNS_SIWA_CLIENT_ID) ? 'ok' : 'failed';
    } catch (\Throwable $e) {
        error_log('[api/account_delete revoke] ' . $e->getMessage());
        return 'failed';
    }
}

/* =============================================================================
 * LINKED-ACCOUNT UNLINK — helpers for `case 'auth_provider_unlink'` (#1479 W3)
 *
 * Mirrors the account_delete helpers immediately above: the case block stays
 * a readable top-to-bottom sequence, the LOCKOUT-GUARD decision is a PURE
 * function (no DB, no superglobals) so its full truth table — including the
 * private-relay-email stranding case round-2 review of the SIWA-web strategy
 * caught — is unit-testable without a database (tests/php/
 * test-auth-provider-unlink.php), and the Apple-revoke I/O shell is kept
 * separate from that decision.
 * ========================================================================= */

/**
 * PURE core of the auth_provider_unlink lockout guard (strategy doc §5(d)).
 * Decides whether the account keeps at least one WORKING sign-in method
 * after $provider's row is removed. Every input is an explicit parameter —
 * no DB, no superglobals — so the full truth table is assertable directly.
 *
 * A survivor is ANY of:
 *   (a) $passwordHash is non-empty (tblUsers.PasswordHash <> '') — the
 *       account can always sign in with its password.
 *   (b) $emailVerified AND $emailLoginOperational AND the account's OWN
 *       email is NOT an Apple private-relay alias — magic-link email
 *       sign-in still works. The private-relay exclusion is load-bearing:
 *       unlinking Apple deactivates that relay alias server-side, so mail
 *       sent to it bounces forever — "the account has a verified email"
 *       would otherwise stay true right up to the moment it becomes
 *       permanently unusable (the exact stranding hole round-2 review of
 *       the SIWA-web strategy caught).
 *   (c) $otherProviders is non-empty — another, DIFFERENT linked provider
 *       (e.g. a future Google/SIGNula link) still works.
 *
 * @param string   $passwordHash          tblUsers.PasswordHash.
 * @param bool     $emailVerified         tblUsers.EmailVerified === 1.
 * @param string   $email                 tblUsers.Email (may be '').
 * @param bool     $emailLoginOperational EmailService::isConfigured() — the
 *                                          SAME config app_status's
 *                                          emailLoginEnabled flag reads.
 * @param string[] $otherProviders        Provider names of the account's
 *                                          OTHER tblUserAuthProviders rows
 *                                          (excludes the one being removed).
 * @return bool True = a surviving method remains; the unlink may proceed.
 */
function _authProviderUnlinkSurvives(
    string $passwordHash,
    bool $emailVerified,
    string $email,
    bool $emailLoginOperational,
    array $otherProviders
): bool {
    if ($passwordHash !== '') {
        return true;
    }

    if ($emailVerified && $emailLoginOperational) {
        $email = trim($email);
        if ($email !== '') {
            $atPos = strrpos($email, '@');
            $isPrivateRelay = ($atPos !== false)
                && (strtolower(substr($email, $atPos + 1)) === 'privaterelay.appleid.com');
            if (!$isPrivateRelay) {
                return true;
            }
        }
    }

    return count($otherProviders) > 0;
}

/**
 * Best-effort Apple `/auth/revoke` for auth_provider_unlink (#1479 W3).
 * Mirrors _accountDeleteRevokeApple() immediately above, but tries BOTH of
 * our own client ids — native's IHYMNS_SIWA_CLIENT_ID and, if configured,
 * the web Services ID — because tblUserAuthProviders.RefreshToken holds
 * whichever platform most recently captured one (#1470 W1 lets EITHER
 * platform write this single column via the SAME best-effort code-exchange
 * step in `case 'auth_apple'`) and Apple's `/auth/revoke` requires the SAME
 * client_id that originally requested the token. Trying native first
 * (today's only populated case) then falling back to the web Services ID is
 * a strict improvement over guessing a single hardcoded aud, while staying
 * non-blocking/never-fatal like every other Apple I/O call in this file —
 * every failure is caught and mapped to 'failed', never thrown.
 *
 * @param array $linkRow The (already-deleted-from-DB, still in PHP memory)
 *                         tblUserAuthProviders row snapshot — needs RefreshToken.
 * @return string 'ok'|'failed'|'skipped_no_key'|'skipped_no_token'
 */
function _authProviderUnlinkRevokeApple(array $linkRow): string
{
    $revokeToken = isset($linkRow['RefreshToken']) && $linkRow['RefreshToken'] !== null
        ? (string)$linkRow['RefreshToken']
        : null;
    if ($revokeToken === null || $revokeToken === '') {
        return 'skipped_no_token';
    }

    $teamId = (string)(getAppSetting('apple_team_id', '') ?? '');
    $keyId  = (string)(getAppSetting('apple_siwa_key_id', '') ?? '');
    $p8Pem  = (string)(getAppSetting('apple_siwa_private_key', '') ?? '');
    if ($teamId === '' || $keyId === '' || $p8Pem === '') {
        return 'skipped_no_key';
    }

    $servicesId = trim((string)(getAppSetting('apple_siwa_services_id', '') ?? ''));
    $candidateClientIds = array_values(array_unique(array_filter(
        [IHYMNS_SIWA_CLIENT_ID, $servicesId],
        static fn(string $c): bool => $c !== ''
    )));

    foreach ($candidateClientIds as $clientId) {
        try {
            $clientSecret = appleSiwaBuildClientSecret($teamId, $keyId, $clientId, $p8Pem, time());
            if ($clientSecret === null) {
                continue; /* .p8 present but doesn't parse as an EC key for this sub — try the next candidate. */
            }
            if (appleSiwaRevokeToken($revokeToken, 'refresh_token', $clientSecret, $clientId)) {
                return 'ok';
            }
        } catch (\Throwable $e) {
            error_log('[api/auth_provider_unlink revoke] ' . $e->getMessage());
        }
    }
    return 'failed';
}

/**
 * Mask an email address for the linked-accounts UI (#1479 W3) —
 * `auth_providers_list` must NEVER return the raw Subject/RefreshToken, and
 * the informational Email column is masked too (defence in depth — it's
 * link-time metadata, not a secret, but there's no reason to echo it back in
 * full). `alice@example.com` -> `a****@e****.com`; '' or no '@' -> ''.
 *
 * @param string $email Raw tblUserAuthProviders.Email (may be '').
 * @return string Masked form, or '' when $email is empty / has no '@'.
 */
function _authProviderMaskEmail(string $email): string
{
    $atPos = strrpos($email, '@');
    if ($email === '' || $atPos === false) {
        return '';
    }
    $local  = substr($email, 0, $atPos);
    $domain = substr($email, $atPos + 1);

    $maskPart = static function (string $s): string {
        if ($s === '') {
            return '';
        }
        return $s[0] . str_repeat('*', max(1, mb_strlen($s) - 1));
    };

    $domainParts = explode('.', $domain);
    $domainParts[0] = $maskPart($domainParts[0]);

    return $maskPart($local) . '@' . implode('.', $domainParts);
}

/**
 * Shared row-builder for the caller's linked providers (#1479 W3) — used by
 * BOTH `auth_providers_list` and `auth_provider_unlink`'s response (so the
 * Settings "Connected accounts" card can redraw itself from either call
 * without a second round-trip). NEVER selects Subject or RefreshToken.
 *
 * @param \mysqli $db
 * @param int     $userId
 * @return array<int,array{provider:string,email_masked:string,is_private_relay:bool,linked_at:?string}>
 */
function _authProviderListForUser(\mysqli $db, int $userId): array
{
    $stmt = $db->prepare(
        'SELECT Provider, Email, EmailIsPrivateRelay, CreatedAt
           FROM tblUserAuthProviders WHERE UserId = ? ORDER BY CreatedAt ASC'
    );
    $stmt->bind_param('i', $userId);
    $stmt->execute();
    $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
    $stmt->close();

    return array_map(static function (array $row): array {
        return [
            'provider'         => (string)$row['Provider'],
            'email_masked'     => _authProviderMaskEmail((string)($row['Email'] ?? '')),
            'is_private_relay' => ((int)($row['EmailIsPrivateRelay'] ?? 0)) === 1,
            'linked_at'        => $row['CreatedAt'] !== null ? (string)$row['CreatedAt'] : null,
        ];
    }, $rows);
}

/**
 * Live Follow (#1268) — sanitise a SongId from client input to the SongId
 * charset (alnum + _ -) and the column width (VARCHAR(20)). Empty after
 * cleaning ⇒ '' (caller treats as "no song").
 */
function _liveFollowCleanSongId(string $raw): string
{
    return mb_substr(preg_replace('/[^a-zA-Z0-9_\-]/', '', $raw), 0, 20);
}

/* =========================================================================
 * ORG-ADMIN SELF-SERVICE (batch 3, O2/O4) — private wire-shape helpers
 * ========================================================================= */

/**
 * Shape an organisation's logo rows for a JSON response. Field names
 * (`kind`/`variant`/`v`/`alt`/`width`/`height`) match the `my_organisations`
 * action's existing `logos` field (§6.3, #1830) EXACTLY — the same
 * `{kind, variant, v}` triple `js/modules/org-logo.js`'s `orgLogoUrl()`
 * already knows how to turn into a serving URL — plus the admin-only
 * fields an EDITING surface needs that a public display doesn't
 * (`mime`/`byteSize`/`isActive`; `my_organisations` pre-filters to
 * active-only rows so never needs the flag on the wire, and this O2
 * surface must show hidden rows too so a curator can un-hide them).
 * NEVER the stored bytes (rule #42 — a logo is served as `<img src>`,
 * built by the client from `kind`/`variant`/`v`, never inlined here).
 * Used by the org_admin_logo_upload/_delete/_set_active actions to echo
 * the STORED state back after a write (rule #35/#40).
 */
function _apiOrgLogoWireList(\mysqli $db, int $orgId): array
{
    return array_map(static function (array $l): array {
        return [
            'kind'     => (string)$l['Kind'],
            'variant'  => (string)$l['Variant'],
            'v'        => (string)$l['Sha256'],
            'alt'      => $l['AltText'] !== null ? (string)$l['AltText'] : null,
            'width'    => $l['Width']  !== null ? (int)$l['Width']  : null,
            'height'   => $l['Height'] !== null ? (int)$l['Height'] : null,
            'mime'     => (string)$l['Mime'],
            'byteSize' => (int)$l['ByteSize'],
            'isActive' => (bool)$l['IsActive'],
        ];
    }, orgLogoListForOrg($db, $orgId));
}

/**
 * Shape one venue row (`venueAdminGetVenue()`'s shape) for a JSON
 * response — the SAME per-field names the `org_venues` action (API-
 * coverage batch 1, C2) already emits for a venue object, plus `orgId`
 * (org_venues nests venues under their org so never needs it repeated; a
 * single-venue write echo does). Used by the O4 org_admin_venue_save
 * action to echo the STORED row back (rule #35/#40).
 */
function _apiVenueWire(?array $v): ?array
{
    if ($v === null) { return null; }
    return [
        'id'           => (int)$v['Id'],
        'orgId'        => (int)$v['OrgId'],
        'name'         => (string)$v['Name'],
        'addressLine'  => $v['AddressLine'] ?? null,
        'city'         => $v['City'] ?? null,
        'postcode'     => $v['Postcode'] ?? null,
        'countryCode'  => $v['CountryCode'] ?? null,
        'latitude'     => $v['Latitude'] !== null ? (float)$v['Latitude'] : null,
        'longitude'    => $v['Longitude'] !== null ? (float)$v['Longitude'] : null,
        'radiusMetres' => $v['RadiusMetres'] !== null ? (int)$v['RadiusMetres'] : null,
        'timeZone'     => (string)$v['TimeZone'],
        'isActive'     => (bool)$v['IsActive'],
    ];
}

/**
 * Shape one service-schedule row (`venueAdminGetSchedule()`'s shape) for a
 * JSON response — the SAME per-field names `org_venues` already emits for
 * a schedule object, plus `orgId`/`venueId` (org_venues nests schedules
 * under their venue so never needs either repeated). Used by the O4
 * org_admin_schedule_save action.
 */
function _apiScheduleWire(?array $s): ?array
{
    if ($s === null) { return null; }
    return [
        'id'             => (int)$s['Id'],
        'orgId'          => (int)$s['OrgId'],
        'venueId'        => (int)$s['VenueId'],
        'title'          => (string)$s['Title'],
        'dayOfWeek'      => (int)($s['DayOfWeek'] ?? 0),
        'startTime'      => (string)$s['StartTime'],
        'durationMins'   => (int)$s['DurationMins'],
        'recurrenceKind' => (string)$s['RecurrenceKind'],
        'timeZone'       => (string)$s['_EffTz'],
        'isActive'       => (bool)$s['IsActive'],
    ];
}

/**
 * Extract a Bearer token from the Authorization header.
 *
 * @return string|null The token string, or null if not present
 */
function getAuthBearerToken(): ?string
{
    $header = $_SERVER['HTTP_AUTHORIZATION']
           ?? $_SERVER['REDIRECT_HTTP_AUTHORIZATION']
           ?? '';

    if (preg_match('/^Bearer\s+([a-f0-9]{64})$/i', $header, $m)) {
        return $m[1];
    }

    /* Cookie fallback (#390) — enables cross-subdomain sign-in and plain
       page loads without JS having to attach the Authorization header. */
    if (!empty($_COOKIE['ihymns_auth']) && preg_match('/^[a-f0-9]{64}$/i', $_COOKIE['ihymns_auth'])) {
        return $_COOKIE['ihymns_auth'];
    }

    return null;
}

/* Cross-subdomain auth-cookie helpers (_authCookieOpts / setAuthTokenCookie /
   clearAuthTokenCookie) were extracted to includes/auth_cookie.php (#1377/#1376)
   so the /manage admin login can mint the SAME `ihymns_auth` cookie without
   pulling in api.php wholesale — see that file's header for the rationale. The
   require lives in the bootstrap block near the top of this file; this comment
   marks where the inline copies used to be so a future reader isn't surprised
   the definitions aren't here. */

/**
 * Slide the token's ExpiresAt forward by 30 days so that any active use
 * resets the clock (#390). To avoid a DB write on every authenticated
 * request, we only bump when the current ExpiresAt is less than
 * (30 days - 1 day) from now — i.e. at most once per day per token.
 * Also refreshes the browser-side cookie lifetime so the two stay in sync.
 */
function slideAuthTokenExpiry(string $rawToken): void
{
    try {
        $hashedToken  = hash('sha256', $rawToken);
        $newExpiresTs = time() + 30 * 86400;
        $newExpiresAt = gmdate('Y-m-d H:i:s', $newExpiresTs);
        $threshold    = gmdate('Y-m-d H:i:s', time() + 29 * 86400);

        $db = getDbMysqli();
        /* #1409 — LastSeenAt piggybacks on this SAME already-throttled
           UPDATE (fires at most once per ~24h of active use PER TOKEN)
           rather than a new per-request write. A "last active" column read
           at ~1-day granularity is still genuinely useful for a
           manage-devices list ("today" / "3 days ago" / …), and a
           finer-grained version would mean adding a NEW round-trip to
           LITERALLY EVERY authenticated request across the whole app — the
           "don't add per-request overhead carelessly" trade-off the #1409
           plan explicitly calls out. columnExists-gated (via
           apiTokensDeviceMetaColumnsExist(), includes/api_tokens.php) so an
           un-migrated docroot's UPDATE stays byte-identical to before this
           change. A future finer-grained version, if ever wanted, is a
           one-line follow-up: a SEPARATE throttled write inside
           getAuthenticatedUser() itself once the extra per-request query is
           judged worth it — deliberately NOT done here. */
        $hasDeviceMetaCols = function_exists('apiTokensDeviceMetaColumnsExist') && apiTokensDeviceMetaColumnsExist($db);
        $sql = $hasDeviceMetaCols
            ? 'UPDATE tblApiTokens SET ExpiresAt = ?, LastSeenAt = UTC_TIMESTAMP() WHERE Token = ? AND ExpiresAt < ?'
            : 'UPDATE tblApiTokens SET ExpiresAt = ? WHERE Token = ? AND ExpiresAt < ?';
        $stmt = $db->prepare($sql);
        $stmt->bind_param('sss', $newExpiresAt, $hashedToken, $threshold);
        $stmt->execute();
        $bumped = $stmt->affected_rows > 0;
        $stmt->close();

        /* If the DB row was bumped, push the cookie forward as well. */
        if ($bumped) {
            setAuthTokenCookie($rawToken, $newExpiresTs);
        }
    } catch (\Throwable $e) {
        /* Non-fatal: sliding expiry is best-effort. Logged so admins
           notice if the UPDATE is failing systematically (e.g.,
           tblApiTokens DDL drift). */
        error_log('[api/slideAuthTokenExpiry] ' . $e->getMessage());
    }
}

/**
 * Authenticate a request using a Bearer token.
 * Returns the user row if valid, null otherwise.
 *
 * @return array|null User data { id, username, display_name, role }
 */
function getAuthenticatedUser(): ?array
{
    $token = getAuthBearerToken();
    if (!$token) return null;

    $db = getDbMysqli();
    $hashedToken = hash('sha256', $token);
    $now = gmdate('Y-m-d H:i:s');

    /* AvatarService (#616) is selected only when the column exists, so
       a partly-migrated install keeps working. The check is cached for
       the lifetime of the request via a static. */
    static $hasAvatarSvcCol = null;
    if ($hasAvatarSvcCol === null) {
        $r = $db->query(
            "SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
              WHERE TABLE_SCHEMA = DATABASE()
                AND TABLE_NAME   = 'tblUsers'
                AND COLUMN_NAME  = 'AvatarService' LIMIT 1"
        );
        $hasAvatarSvcCol = ($r && $r->fetch_row() !== null);
        if ($r) $r->close();
    }
    $avatarSvcCol = $hasAvatarSvcCol ? ', u.AvatarService' : ', NULL AS AvatarService';
    $emailCol     = ', u.Email';

    $stmt = $db->prepare(
        "SELECT u.Id, u.Username, u.DisplayName, u.Role
                {$emailCol}
                {$avatarSvcCol}
         FROM tblApiTokens t
         JOIN tblUsers u ON u.Id = t.UserId
         WHERE t.Token = ? AND t.ExpiresAt > ? AND u.IsActive = 1"
    );
    $stmt->bind_param('ss', $hashedToken, $now);
    $stmt->execute();
    $user = $stmt->get_result()->fetch_assoc();
    $stmt->close();

    if (!$user) return null;

    /* Sliding expiry (#390) — any active use extends the token 30 days,
       at most once per day per token. Keeps long-term users signed in
       without daily DB writes. */
    slideAuthTokenExpiry($token);

    $user['Id'] = (int)$user['Id'];
    return $user;
}

/**
 * Convert a full song object to a lightweight summary for list views.
 * Excludes the full lyrics/components to reduce payload size.
 *
 * @param array $song Full song object
 * @return array Summary with id, number, title, songbook, etc.
 */
function songToSummary(array $song): array
{
    $summary = [
        'id'           => $song['id'] ?? '',
        'number'       => $song['number'] ?? 0,
        'title'        => $song['title'] ?? '',
        'songbook'     => $song['songbook'] ?? '',
        'songbookName' => $song['songbookName'] ?? '',
        'writers'      => $song['writers'] ?? [],
        'hasAudio'     => $song['hasAudio'] ?? false,
        'hasSheetMusic' => $song['hasSheetMusic'] ?? false,
    ];

    /* Live-search extras (#1014) — only present when set, so number /
       songbook summaries stay minimal. lyricsSnippet rides along when
       a body match drove the hit; matchedVia carries the curator
       alt-title hint (#832). */
    if (!empty($song['lyricsSnippet'])) {
        $summary['lyricsSnippet'] = $song['lyricsSnippet'];
    }
    if (!empty($song['matchedVia'])) {
        $summary['matchedVia'] = $song['matchedVia'];
    }

    return $summary;
}
